"""
This file contains all the classes present in the autosar schema.
It provides methods to access/modify/create elements from the autosar
arxml file.
"""

from __future__ import annotations

from lxml import etree
from enum import Enum, unique
import logging, os.path, sys
from typing import Type, Any
from .utils import datatype_utils
from .utils.XmlElementDirtyTracker import XmlElementDirtyTracker

# dict supposed to be used internally by the module to store the path and its corresponding autosar node
__pathsToNodeDict__ = {}
__autosarPathsToNodeDict__ = {}
__refBaseToArPackageDict__={}
# root autosar node
__autosarNode__ = None
# ElementDirtyTracker for xml nodes
XDT = XmlElementDirtyTracker()

# namespace for autosar arxml files
__autosarNsMap__ = {None: "http://autosar.org/schema/r4.0", 'xsi': "http://www.w3.org/2001/XMLSchema-instance"}
__rootSchemaAttr__ = {'{http://www.w3.org/2001/XMLSchema-instance}schemaLocation': 'http://autosar.org/schema/r4.0 AUTOSAR_00049.xsd'}


def read(files: list[str]=[]) -> tuple['AUTOSAR', bool]:
    """
    Reads the given files/files inside the folder and returns the AUTOSAR root.

    :param files: List of arxml file or folders containing arxml file
    :return: The merged AUTOSAR root node(the current file + all other
             files already loaded) and the status. May return None
             if the given file is not AUTOSAR compliant file or if
             it does not have any AR-PACKAGES.
    """
    global __autosarNode__
    status = True

    if isinstance(files, list) is False:
        raise InvalidInputException('argument files should be list of file')

    for file in files:
        if os.path.isdir(file):
            status &= __read_folder(file)
        else:
            status &= __read_file(file)
        if status is False:
            break

    # Resolve the references of all the nodes.
    if status is True:
        # Identify any reference bases
        referenceBases = get_all_instances(__autosarNode__, ReferenceBase)
        for r in referenceBases:
            r._resolve_references()
            if r.get_package() is not None:
                __refBaseToArPackageDict__[r.get_shortLabel()] = r.get_package()

        for node in __pathsToNodeDict__.values():
            node._resolve_references()
    return __autosarNode__, status


def __read_folder(folder: str) -> bool:
    status = True
    for root, dirs, files in os.walk(folder):
        for file in files:
            if file.endswith(".arxml"):
                status &= __read_file(os.path.join(root, file))
            if status is False:
                break
    return status


def __read_file(file: str) -> bool:
    global __autosarNode__
    status = False
    tree = etree.parse(file, etree.XMLParser(huge_tree=True, remove_blank_text=True))

    if tree is not None and tree.getroot() is not None:
        if etree.QName(tree.getroot()).localname == 'AUTOSAR':
            status = True
            asrRootNode = AUTOSAR()._build(tree.getroot(), file)
            if len(asrRootNode.get_arPackages()) > 0:
                logging.info('{} read successfull.'.format(file))
                if __autosarNode__ is None:
                    __autosarNode__ = asrRootNode
                else:
                    for arpackage in asrRootNode.get_arPackages():
                        __merge_to_parent_node(arpackage, __autosarNode__)

                __autosarNode__._mergedFromNodes[file] = asrRootNode
            else:
                logging.warning('{} read but no ar-packages found. Hence ingoring the file contents.'.format(file))
        else:
            logging.error('{} read Failed. AUTOSAR root node not found in the arxml file.'.format(file))
    else:
        logging.error('{} read Failed. Seems like the file is not a valid arxml file.'.format(file))

    return status


def __merge_to_parent_node(node, parentNode):
    """
    Merges the child node to the parent node.
    """
    nodeWithSamePath = list(filter(lambda n: n == node, parentNode.get_children()))
    if nodeWithSamePath is None or len(nodeWithSamePath) == 0:
        parentNode.add_child(node)
    else:
        if nodeWithSamePath[0].is_atp_splitable():
            #ignore if value variation points
            for child in list(filter(lambda n: not isinstance(n, (AttributeValueVariationPoint, MultilanguageLongName)), node.get_children())):
                __merge_to_parent_node(child, nodeWithSamePath[0])
        elif isinstance(nodeWithSamePath[0], Identifiable):
            logging.warning('The node {} with short name {} is not splitable, but found in multiple files.'.format(nodeWithSamePath[0].__class__.__name__, nodeWithSamePath[0].name))


def new_file(path: str, defaultArPackage: str='RootPackage', overWrite: bool=False) -> 'ARPackage':
    """
    Creates a new file and return the ar-package node.
    Throws exception if the file already exist when the
    argument overWrite is not provided or is False.

    :param path: The absolute path where the file needs to be created.
    :param defaultArPackage: The name of the default ar-package.
    :param overWrite: Pass True if the new file should overwrite if
                      a file is already present in the given path.
    :return: The Ar-package.
    """
    global __autosarNode__
    if os.path.isfile(path) and overWrite is False:
        raise FileExistsError('File {} already exists. If it needs overwriting, then please set True for argument overWrite.'.format(path))

    # Create file
    root = etree.Element('AUTOSAR', nsmap=__autosarNsMap__, attrib=__rootSchemaAttr__)
    arpackages = etree.SubElement(root, 'AR-PACKAGES')
    arpackage = etree.SubElement(arpackages, 'AR-PACKAGE')
    shortName = etree.SubElement(arpackage, 'SHORT-NAME')
    shortName.text = defaultArPackage
    et = etree.ElementTree(root)
    et.write(path, pretty_print=True, xml_declaration=True,   encoding="utf-8")
    logging.info('File created successfully at {}.'.format(path))

    # Now create the Autosar object
    asrRootNode = AUTOSAR()._build(root, path)
    createdArPackage = next(iter(asrRootNode.get_arPackages()))
    if __autosarNode__ is None:
        __autosarNode__ = asrRootNode
    else:
        __merge_to_parent_node(createdArPackage, __autosarNode__) #Merging the new arpackage to the root node.

    __autosarNode__._mergedFromNodes[path] = asrRootNode
    return createdArPackage


def get_root() -> 'AUTOSAR':
    """
    Returns the root AUTOSAR node.
    """
    global __autosarNode__
    return __autosarNode__


def reinit() -> None:
    """
    Re-initialize the package. All the loaded model entities(from input
    /newly created files, modified/new model objects) will be removed.
    """
    global __autosarNode__
    __autosarNode__ = None # Reinit the root node.
    __pathsToNodeDict__.clear() # Clearing the cache
    __autosarPathsToNodeDict__.clear() # Clearing the cache
    __refBaseToArPackageDict__.clear() # Clearing the cache
    XDT.clear_dirty() # Clearing the dirty element tracing


def get_node(path) -> 'AutosarNode':
    """
    Returns the autosar node for the corresponding path.

    :param path: The fully qualified autosar path for eg: /Autosar/Swc1/port1.
    :return: The node corresponding to the path or None if the node for path is not available.
    """
    if path in __autosarPathsToNodeDict__:
        return __autosarPathsToNodeDict__[path]
    else:
        return None


def get_all_instances(node: 'AutosarNode', clazz) -> list['AutosarNode']:
    """
    Returns all the instances of the given class type by performing a deep search under the given node
    :param node: The node under which the type needs to be searched for.
    :param clazz: The python class type of the node to be searched for.
    """
    instances = []
    for child in node.get_children():
        if isinstance(child, clazz):
            instances.append(child)
        instances.extend(get_all_instances(child, clazz))
    return instances


def export_to_file(element: 'AutosarNode', path: str, overWrite: bool=False) -> None:
    """
    Export the element to the given file.
    :param element: the element which needs to be exported.
    :param path: the file path to which the element is exported.
    :param overWrite: Pass True if the new file should overwrite if
                  a file is already present in the given path.
    """
    if isinstance(element, CollectableElement):
        element.export_to_file(path, overWrite)
    else:
        raise Exception('Only elements of type CollectableElement can be exported(for eg: ARPackage, ApplicationSwComponentType, ISignal etc etc.)')


def save(files: list[str]=[]) -> None:
    """
    Saves the changes in AUTOSAR model.
    :param files: The files to be saved. If not provided
                  all the input files will be saved.
    """
    global __autosarNode__
    if __autosarNode__ is not None:
    	__autosarNode__.save(files)


def saveAs(file: str, overWrite: bool=False) -> None:
    """
    Saves the changes in AUTOSAR model(contents from input files, created files,
    new model entities, modified model entities) to a single file. This package
    do not validate if there exists AR-PACKAGE was duplicate names. It is the
    responsibility of the user to make sure this.

    :param file: The file where the complete AUTOSAR model will be saved.
    :param overWrite: Pass True if the new file should overwrite if
                      a file is already present in the given path.
    """
    global __autosarNode__
    __autosarNode__.saveAs(file, overWrite=overWrite)


def __str_to_class__(str):
    """
    To be used internally by the package.
    """
    return getattr(sys.modules[__name__], str)


class AutosarNode:
    """
    Base class for all autosar nodes
    """
    def __init__(self):
        """
        Constructor for any Autosar node.
        """
        self._parent = None
        self._node = None
        self.name = None
        self.path = ''
        self.autosar_path = ''
        self.file = ''
        self._insert_after_tags = []
        self.referenced_by = set()


    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        """
        Build the node
        :param parent: The parent under which new model element needs to be created.
        :param node: The xml node for which the autosar node needs to be created.
        """
        self._parent = parent
        self._node = node
        self.file = file
        shortNameNode = node.find('{*}SHORT-NAME')
        if shortNameNode is not None:
            self.name = shortNameNode.text

        self._build_path(elementNameIfShortNameMissing)
        return self


    def _build_path(self, elementNameIfShortNameMissing = None):
        """
        Builds the path for the current node.
        """
        # First remove the current node from dict
        if self.path in __pathsToNodeDict__:
            del __pathsToNodeDict__[self.path]
        # Build the node and add to dict.
        if self.path not in __pathsToNodeDict__ and self._parent is not None:
            if self.name is not None:
                self.path = self._parent.path + '/' + self.name
                self.autosar_path = self._parent.autosar_path + '/' + self.name
                if self.autosar_path not in __autosarPathsToNodeDict__:
                    __autosarPathsToNodeDict__[self.autosar_path] = self
            elif elementNameIfShortNameMissing is not None:
                self.path = self._parent.path + '/' + elementNameIfShortNameMissing
                self.autosar_path = self._parent.autosar_path
            else:
                self.path = self._parent.path + '[' + self.__class__.__name__ + ']'
                self.autosar_path = self._parent.autosar_path

            if self.path not in __pathsToNodeDict__:
                __pathsToNodeDict__[self.path] = self
        else:
            self.path = ''


    @staticmethod
    def _add_or_get_xml_node(parentNode, tagName, dest = None, createNode = True, forceCreate = False, create_after_nodes = []):
        """
        Get or create a new xml node with the tagName.
        :param parentNode: Parent node under which the new tag needs to be created.
        :param tagName: The tag name which needs to be created.
        :param dest: The destination object if its a reference value.
        :param createNode: Create node is it doesn't exist.
        :param forceCreate: Create element forecefully even if it exists.
        :param create_after_nodes: The list of elements after which the element needs to be created.
        """
        xmlNode = parentNode.find('{*}' + tagName)
        if (xmlNode is None and createNode) or forceCreate:
            xmlNode = etree.Element(tagName, attrib = {'DEST' : dest.tag} if dest is not None else None)
            AutosarNode._insert_element_after_given_tags(parentNode, xmlNode, create_after_nodes = create_after_nodes)
        return xmlNode


    @staticmethod
    def _insert_element_after_given_tags(parentNode, xmlNode, create_after_nodes = []):
        """
        Inserts the element after given list of tags
        :param xmlNode: The node to be inserted
        :param create_after_nodes: The list nodes after which the element needs to be inserted
        """
        node_inserted = False
        for tag in create_after_nodes:
            nodes = parentNode.findall('{*}' + tag)
            if nodes is not None and len(nodes) > 0:
                parentNode.insert(parentNode.index(nodes[-1]) + 1, xmlNode)
                node_inserted = True
                break
        if node_inserted is False:
            # if not found already in the above list of nodes, it must be the first child element
            parentNode.insert(0, xmlNode)


    @staticmethod
    def _remove_xml_node_if_exists(parentNode, tagName):
        """
        Remove xml node with the tagName if it exists under the parentNode.
        :param parentNode: Parent node under which tagName element exists.
        :param tagName: The tag name to search for.
        """
        for xmlNode in parentNode.findall('{*}' + tagName):
            parentNode.remove(xmlNode)

    @staticmethod
    def _get_node_text(node, tagName):
        value = node.find('{*}' + tagName)
        if value is not None:
            return value.text
        return None

    @staticmethod
    def _export_element_to_file(element, path, overWrite=False):
        """
        Export the element to the given file.
        :param element: the element which needs to be exported.
        :param path: the file path to which the element is exported.
        :param overWrite: Pass True if the new file should overwrite if
                      a file is already present in the given path.
        """
        if os.path.isfile(path) and overWrite is False:
            raise FileExistsError('File {} already exists. If it needs overwriting, then please set True for argument overWrite.'.format(path))

        # Create file
        root = etree.Element('AUTOSAR', nsmap=__autosarNsMap__, attrib=__rootSchemaAttr__)
        arpackages = etree.SubElement(root, 'AR-PACKAGES')
        isPackageableElementToExport = isinstance(element, ARPackage)

        # Identify and add all packages
        packages = []
        AutosarNode.__identify_parentArPackages_until_root(element, packages)
        parentNode = arpackages

        for pack in packages:
            packNode = etree.SubElement(parentNode, 'AR-PACKAGE')
            shortName = etree.SubElement(packNode, 'SHORT-NAME')
            shortName.text = pack.name
            if pack == packages[-1] and isPackageableElementToExport:
                elementsNode = etree.SubElement(packNode, 'ELEMENTS')
                parentNode = elementsNode
            else:
                arPacksNode = etree.SubElement(packNode, 'AR-PACKAGES')
                parentNode = arPacksNode

        parentNode.append(element._node) # Add element
        et = etree.ElementTree(root)
        et.write(path, pretty_print=True, xml_declaration=True,   encoding="utf-8")
        logging.info('File exported successfully at {}.'.format(path))


    @staticmethod
    def __identify_parentArPackages_until_root(element, packages):
        if isinstance(element.get_parent(), ARPackage):
            AutosarNode.__identify_parentArPackages_until_root(element.get_parent(), packages)
            packages.append(element.get_parent())


    def get_parent(self) -> AutosarNode:
        return self._parent


    def get_children(self) -> AutosarNode:
        """
        Get all the child nodes of the current node. This method is supposed to be overridden by all sub-classes.
        """
        return []


    def get_property_values(self) -> dict[str, Any]:
        """
        Get the property and its value for a corresponding node as dict. This method is supposed to be overridden by all sub-classes.
        """
        return {'File' : repr(self.file)}


    def _resolve_references(self):
        """
        This method is supposed to be overridden by all sub-classes.
        """
        pass


    def _update_path(self):
        """
        This method is supposed to be overridden by all sub-classes.
        """
        pass

    def is_atp_splitable(self) -> bool:
        """
        This method is supposed to be overridden by the relevant sub-classes which is atp-splitable.
        """
        return False

    def add_child(self, child: AutosarNode) -> None:
        """
        This method is supposed to be overridden by all sub-classes.
        """
        pass

    def get_unique_hash(self):
        """
        Gets the unique hash value for the object
        """
        return self.path + str(hash(self._node))

    def __repr__(self):
        return (self.__class__.__name__ + '(' + self.path + ')')


    def __hash__(self):
        return hash(self.path)


    def __eq__(self, other):
        return (self.__class__ == other.__class__ and self.path == other.path)


class ARObject(AutosarNode):
    """
    Implicit base class of all classes in meta-model.
    """
    def __init__(self):
        super().__init__()
        self.__checksum = None
        self.__timestamp = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        checksum_value = node.attrib.get('S')
        if checksum_value is not None:
            self.__checksum = datatype_utils.get_string_value(checksum_value)

        timestamp_value = node.attrib.get('T')
        if timestamp_value is not None:
            self.__timestamp = datatype_utils.get_string_value(timestamp_value)

        return self

    def get_checksum(self) -> str:
        return self.__checksum

    def set_checksum(self, value: str) -> None:
        self.__checksum = value
        XDT.mark_attribute_dirty('checksum', self)

    def get_timestamp(self) -> str:
        return self.__timestamp

    def set_timestamp(self, value: str) -> None:
        self.__timestamp = value
        XDT.mark_attribute_dirty('timestamp', self)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['Checksum'] = self.__checksum
        property_values['Timestamp'] = self.__timestamp
        return property_values

    def _update_path(self):
        """
        Updates the path of the ARObject and its children.
        """
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()


    def _save_ARObject(self):
        """
        Saves the content of ARObject node
        """
        if XDT.is_attribute_dirty('checksum', self):
            if self.__checksum is not None:
                self._node.attrib['S'] = str(self.__checksum) if self.__checksum is not None else ''

        if XDT.is_attribute_dirty('timestamp', self):
            if self.__timestamp is not None:
                self._node.attrib['T'] = str(self.__timestamp) if self.__timestamp is not None else ''


class Referrable(ARObject):
    """
    Instances of this class can be referred to by their identifier (while adhering to namespace borders).
    """
    def __init__(self):
        super().__init__()
        self.__shortName = None
        self.__shortNameFragments = {} # using dict to preserve the order of elements

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        shortName_value = AutosarNode._get_node_text(node,'SHORT-NAME')
        if shortName_value is not None:
            self.__shortName = datatype_utils.get_string_value(shortName_value)

        refCounter = 0
        shortNameFragments_nodes = self._node.findall('{*}SHORT-NAME-FRAGMENTS/*')
        for shortNameFragments_node in shortNameFragments_nodes:
            buildshortNameFragments_node = None
            if shortNameFragments_node.find('{*}SHORT-NAME') is None:
                buildshortNameFragments_node = ShortNameFragment()._build(self, shortNameFragments_node, file, '[shortNameFragments_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildshortNameFragments_node = ShortNameFragment()._build(self, shortNameFragments_node, file)
            self.__shortNameFragments[(buildshortNameFragments_node)] = None

        return self

    def get_shortName(self) -> str:
        return self.__shortName

    def set_shortName(self, value: str) -> None:
        self.__shortName = value
        self.name = value
        XDT.mark_attribute_dirty('shortName', self)

    def get_shortNameFragments(self) -> list[ShortNameFragment]:
        return list(self.__shortNameFragments.keys())

    def add_shortNameFragment(self, value: ShortNameFragment) -> None:
        """
        Adds a single value to the shortNameFragments
        """
        if value is not None:
            if isinstance(value, Referrable) and any(v.name == value.name for v in self.__shortNameFragments.keys()):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, ShortNameFragment) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of ShortNameFragment or its sub-classes'.format(value))
            self.__shortNameFragments[value] = None
            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            value._parent = self #set parent
            value.file = self.file
            if value.name is not None:
                value._update_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'ShortNameFragment_@' + str(len(self.get_children()))) #updates the path
            XDT.mark_dirty(value, self, attributesToMakeDirty = ['timestamp', 'checksum'])

    def set_shortNameFragments(self, values: list[ShortNameFragment]) -> None:
        """
        Adds a list of ref value to the shortNameFragments
        """
        for value in values:
            self.add_shortNameFragment(value)

    def remove_shortNameFragment(self, value: ShortNameFragment) -> None:
        """
        Removes a single value from shortNameFragments
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__shortNameFragments.pop(value)
            value._parent = None #No parent
            value._update_path() #resets the path
            value._node.getparent().remove(value._node)

    def remove_shortNameFragments(self, values: list[ShortNameFragment]) -> None:
        """
        Removes a list of value from shortNameFragments
        """
        for value in values:
            self.remove_shortNameFragment(value)

    def new_ShortNameFragment(self, name: str=None) -> ShortNameFragment:
        """
        Creates a new ShortNameFragment under the Referrable.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        ShortNameFragment_obj = ShortNameFragment()
        if isinstance(ShortNameFragment_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        ShortNameFragment_obj.name = name if isinstance(ShortNameFragment_obj, Referrable) else None
        self.add_shortNameFragment(ShortNameFragment_obj)
        if isinstance(ShortNameFragment_obj, Referrable):
            ShortNameFragment_obj.set_shortName(name)
        return ShortNameFragment_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        children.extend(self.__shortNameFragments)
        return children



    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['ShortName'] = self.__shortName
        return property_values

    def _update_path(self):
        """
        Updates the path of the Referrable and its children.
        """
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()


    def _save_Referrable(self):
        """
        Saves the content of Referrable node
        """
        super()._save_ARObject()
        if XDT.is_attribute_dirty('shortName', self):
            if self.__shortName is None:
                AutosarNode._remove_xml_node_if_exists(self._node, 'SHORT-NAME')
            else:
                shortName_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'SHORT-NAME', create_after_nodes = ['T', 'S'] + self._insert_after_tags)
                shortName_xml_node.text = str(self.__shortName)

        if len(self.__shortNameFragments) > 0:
            shortNameFragments_values = AutosarNode._add_or_get_xml_node(self._node, 'SHORT-NAME-FRAGMENTS', create_after_nodes = self._insert_after_tags + ['SHORT-NAME', 'T', 'S'] + self._insert_after_tags)
            for value in self.__shortNameFragments:
                if XDT.is_dirty(value) and value.file == self.file:
                    value._save_contents()
                    if value._node.getparent() is None or value._node.getparent() != shortNameFragments_values:
                        shortNameFragments_values.append(value._node)


class HwDescriptionEntity(Referrable):
    """
    This meta-class represents the ability to describe a hardware entity.
    """
    def __init__(self):
        super().__init__()
        self.__hwType = None
        self.__hwType_as_string = None
        self.__hwCategories = {} # using dict to preserve the order of elements
        self.__hwCategories_as_string = {} # using dict to preserve the order of elements
        self.__hwAttributeValues = {} # using dict to preserve the order of elements

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        refCounter = 0
        hwAttributeValues_nodes = self._node.findall('{*}HW-ATTRIBUTE-VALUES/*')
