class HwAttributeValue(ARObject):
    """
    This metaclass represents the ability to assign a hardware attribute value. Note that v and vt are mutually exclusive.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'HW-ATTRIBUTE-VALUE'
        self._node = etree.Element('HW-ATTRIBUTE-VALUE')
        self.__vt = None
        self.__annotation = None
        self.__hwAttributeDef = None
        self.__hwAttributeDef_as_string = None
        self.__v = None
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        vt_value = AutosarNode._get_node_text(node,'VT')
        if vt_value is not None:
            self.__vt = datatype_utils.get_string_value(vt_value)

        annotation_node = self._node.find('{*}ANNOTATION')
        if annotation_node is not None:
            if annotation_node.find('{*}SHORT-NAME') is None:
                self.__annotation = Annotation()._build(self, annotation_node, file, '[annotation_@]')
            else:
                self.__annotation = Annotation()._build(self, annotation_node, file)

        v_node = self._node.find('{*}V')
        if v_node is not None:
            if v_node.find('{*}SHORT-NAME') is None:
                self.__v = NumericalValueVariationPoint()._build(self, v_node, file, '[v_@]')
            else:
                self.__v = NumericalValueVariationPoint()._build(self, v_node, file)

        variationPoint_node = self._node.find('{*}VARIATION-POINT')
        if variationPoint_node is not None:
            if variationPoint_node.find('{*}SHORT-NAME') is None:
                self.__variationPoint = VariationPoint()._build(self, variationPoint_node, file, '[variationPoint_@]')
            else:
                self.__variationPoint = VariationPoint()._build(self, variationPoint_node, file)

        return self

    def _resolve_references(self):
        super()._resolve_references()
        hwAttributeDef_node = self._node.find('{*}HW-ATTRIBUTE-DEF-REF')
        if hwAttributeDef_node is not None and hwAttributeDef_node.text is not None:
            refText = ''
            refBase = hwAttributeDef_node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + hwAttributeDef_node.text
            self.__hwAttributeDef_as_string = refText
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__hwAttributeDef = ref_value


    def get_vt(self) -> str:
        return self.__vt

    def set_vt(self, value: str) -> None:
        self.__vt = value
        XDT.mark_attribute_dirty('vt', self)

    def get_annotation(self) -> Annotation:
        return self.__annotation

    def set_annotation(self, value: Annotation) -> None:
        """
        Adds a single value to the annotation
        """
        if value is not None:
            if isinstance(value, Annotation) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of Annotation or its sub-classes'.format(value))
            #if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            self.__annotation = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._build_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'Annotation_@' + str(len(self.get_children()))) #updates the path
        elif self.__annotation is not None:
            self.__annotation = None
        XDT.mark_dirty(self.__annotation, self)

    def get_hwAttributeDef(self) -> HwAttributeDef:
        return self.__hwAttributeDef

    def get_hwAttributeDef_as_string(self) -> str:
        return self.__hwAttributeDef_as_string

    def set_hwAttributeDef(self, value: HwAttributeDef) -> None:
        """
        Adds a single value to the hwAttributeDef
        """
        if value is not None:
            if isinstance(value, HwAttributeDef) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of HwAttributeDef or its sub-classes'.format(value))
            if self.__hwAttributeDef is not None:
                self.__hwAttributeDef.referenced_by.remove(self)
            self.__hwAttributeDef = value
            value.referenced_by.add(self)
        elif self.__hwAttributeDef is not None:
            self.__hwAttributeDef.referenced_by.remove(self)
            self.__hwAttributeDef = None
        XDT.mark_dirty(self.__hwAttributeDef, self)

