class HwCategory(ARElement,AtpDefinition):
    """
    This metaclass represents the ability to declare hardware categories and its particular attributes.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'HW-CATEGORY'
        self._node = etree.Element('HW-CATEGORY')
        self.__hwAttributeDefs = {} # using dict to preserve the order of elements

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        refCounter = 0
        hwAttributeDefs_nodes = self._node.findall('{*}HW-ATTRIBUTE-DEFS/*')
        for hwAttributeDefs_node in hwAttributeDefs_nodes:
            buildhwAttributeDefs_node = None
            if hwAttributeDefs_node.find('{*}SHORT-NAME') is None:
                buildhwAttributeDefs_node = HwAttributeDef()._build(self, hwAttributeDefs_node, file, '[hwAttributeDefs_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildhwAttributeDefs_node = HwAttributeDef()._build(self, hwAttributeDefs_node, file)
            self.__hwAttributeDefs[(buildhwAttributeDefs_node)] = None

        return self

    def get_hwAttributeDefs(self) -> list[HwAttributeDef]:
        return list(self.__hwAttributeDefs.keys())

    def add_hwAttributeDef(self, value: HwAttributeDef) -> None:
        """
        Adds a single value to the hwAttributeDefs
        """
        if value is not None:
            if isinstance(value, Referrable) and any(v.name == value.name for v in self.__hwAttributeDefs.keys()):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, HwAttributeDef) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of HwAttributeDef or its sub-classes'.format(value))
            self.__hwAttributeDefs[value] = None
            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            value._parent = self #set parent
            value.file = self.file
            if value.name is not None:
                value._update_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'HwAttributeDef_@' + str(len(self.get_children()))) #updates the path
            XDT.mark_dirty(value, self, attributesToMakeDirty = ['uuid', 'category', 'shortName', 'timestamp', 'checksum'])

    def set_hwAttributeDefs(self, values: list[HwAttributeDef]) -> None:
        """
        Adds a list of ref value to the hwAttributeDefs
        """
        for value in values:
            self.add_hwAttributeDef(value)

    def remove_hwAttributeDef(self, value: HwAttributeDef) -> None:
        """
        Removes a single value from hwAttributeDefs
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__hwAttributeDefs.pop(value)
            value._parent = None #No parent
            value._update_path() #resets the path
            value._node.getparent().remove(value._node)

    def remove_hwAttributeDefs(self, values: list[HwAttributeDef]) -> None:
        """
        Removes a list of value from hwAttributeDefs
        """
        for value in values:
            self.remove_hwAttributeDef(value)

    def new_HwAttributeDef(self, name: str=None) -> HwAttributeDef:
        """
        Creates a new HwAttributeDef under the HwCategory.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        HwAttributeDef_obj = HwAttributeDef()
        if isinstance(HwAttributeDef_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        HwAttributeDef_obj.name = name if isinstance(HwAttributeDef_obj, Referrable) else None
        self.add_hwAttributeDef(HwAttributeDef_obj)
        if isinstance(HwAttributeDef_obj, Referrable):
            HwAttributeDef_obj.set_shortName(name)
        return HwAttributeDef_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        children.extend(self.__hwAttributeDefs)
        return children

    def add_child(self, child: AutosarNode) -> None:
        if child is not None:
            super().add_child(child)
            if isinstance(child, HwAttributeDef):
                self.__hwAttributeDefs[child] = None


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        return property_values

    def _update_path(self):
        """
        Updates the path of the HwCategory and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

    def is_atp_splitable(self) -> bool:
        return True

    def _save_contents(self):
        """
        Saves the content of HwCategory node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_ARElement()
        super()._save_AtpDefinition()
        if len(self.__hwAttributeDefs) > 0:
            hwAttributeDefs_values = AutosarNode._add_or_get_xml_node(self._node, 'HW-ATTRIBUTE-DEFS', create_after_nodes = self._insert_after_tags + ['VARIATION-POINT', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'] + self._insert_after_tags)
            for value in self.__hwAttributeDefs:
                if XDT.is_dirty(value) and value.file == self.file:
                    value._save_contents()
                    if value._node.getparent() is None or value._node.getparent() != hwAttributeDefs_values:
                        hwAttributeDefs_values.append(value._node)


