        refCounter = 0
        swSystemconstantValues_nodes = self._node.findall('{*}SW-SYSTEMCONSTANT-VALUES/*')
        for swSystemconstantValues_node in swSystemconstantValues_nodes:
            buildswSystemconstantValues_node = None
            if swSystemconstantValues_node.find('{*}SHORT-NAME') is None:
                buildswSystemconstantValues_node = SwSystemconstValue()._build(self, swSystemconstantValues_node, file, '[swSystemconstantValues_@' + str(refCounter) + ']')
