        blueprintCondition_node = self._node.find('{*}BLUEPRINT-CONDITION')
        if blueprintCondition_node is not None:
            if blueprintCondition_node.find('{*}SHORT-NAME') is None:
                self.__blueprintCondition = DocumentationBlock()._build(self, blueprintCondition_node, file, '[blueprintCondition_@]')
