            postBuildVariantConditions_values = AutosarNode._add_or_get_xml_node(self._node, 'POST-BUILD-VARIANT-CONDITIONS', create_after_nodes = self._insert_after_tags + ['SW-SYSCOND', 'FORMAL-BLUEPRINT-GENERATOR', 'FORMAL-BLUEPRINT-CONDITION', 'BLUEPRINT-CONDITION', 'DESC', 'SHORT-LABEL', 'T', 'S'] + self._insert_after_tags)
