class AttributeValueVariationPoint(SwSystemconstDependentFormula):
    """
    This class represents the ability to derive the value of the Attribute from a system constant (by SwSystemconstDependentFormula). It also provides a bindingTime.
    """
    def __init__(self):
        super().__init__()
        self.__bindingTime = None
        self.__blueprintValue = None
        self.__sd = None
        self.__shortLabel = None

        self.__mixedtext = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        bindingTime_value = node.attrib.get('BINDING-TIME')
        if bindingTime_value is not None:
            self.__bindingTime = BindingTimeEnum.get(bindingTime_value)

        blueprintValue_value = node.attrib.get('BLUEPRINT-VALUE')
        if blueprintValue_value is not None:
            self.__blueprintValue = datatype_utils.get_string_value(blueprintValue_value)

        sd_value = node.attrib.get('SD')
        if sd_value is not None:
            self.__sd = datatype_utils.get_string_value(sd_value)

        shortLabel_value = node.attrib.get('SHORT-LABEL')
        if shortLabel_value is not None:
            self.__shortLabel = datatype_utils.get_string_value(shortLabel_value)

        return self

    def get_bindingTime(self) -> BindingTimeEnum:
        return self.__bindingTime

    def set_bindingTime(self, value: BindingTimeEnum) -> None:
        self.__bindingTime = value
        XDT.mark_attribute_dirty('bindingTime', self)

    def get_blueprintValue(self) -> str:
        return self.__blueprintValue

    def set_blueprintValue(self, value: str) -> None:
        self.__blueprintValue = value
        XDT.mark_attribute_dirty('blueprintValue', self)

    def get_sd(self) -> str:
        return self.__sd

    def set_sd(self, value: str) -> None:
        self.__sd = value
        XDT.mark_attribute_dirty('sd', self)

    def get_shortLabel(self) -> str:
        return self.__shortLabel

    def set_shortLabel(self, value: str) -> None:
        self.__shortLabel = value
        XDT.mark_attribute_dirty('shortLabel', self)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['BindingTime'] = self.__bindingTime
        property_values['BlueprintValue'] = self.__blueprintValue
        property_values['Sd'] = self.__sd
        property_values['ShortLabel'] = self.__shortLabel
        property_values['Value'] = self.__mixedtext
        return property_values

    def _update_path(self):
        """
        Updates the path of the AttributeValueVariationPoint and its children.
        """
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()


    def _save_AttributeValueVariationPoint(self):
        """
        Saves the content of AttributeValueVariationPoint node
        """
        super()._save_SwSystemconstDependentFormula()
        if XDT.is_attribute_dirty('bindingTime', self):
            if self.__bindingTime is not None:
                self._node.attrib['BINDING-TIME'] = self.__bindingTime.literal if self.__bindingTime is not None else ''

        if XDT.is_attribute_dirty('blueprintValue', self):
            if self.__blueprintValue is not None:
                self._node.attrib['BLUEPRINT-VALUE'] = str(self.__blueprintValue) if self.__blueprintValue is not None else ''

        if XDT.is_attribute_dirty('sd', self):
            if self.__sd is not None:
                self._node.attrib['SD'] = str(self.__sd) if self.__sd is not None else ''

        if XDT.is_attribute_dirty('shortLabel', self):
            if self.__shortLabel is not None:
                self._node.attrib['SHORT-LABEL'] = str(self.__shortLabel) if self.__shortLabel is not None else ''


