class EnumerationMappingTable(PackageableElement):
    """
    This class represents an attribute value variation point for Enumeration attributes., , Note that this class might be used in the extended meta-model only.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'ENUMERATION-MAPPING-TABLE'
        self._node = etree.Element('ENUMERATION-MAPPING-TABLE')
        self.__entries = {} # using dict to preserve the order of elements

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        refCounter = 0
        entries_nodes = self._node.findall('{*}ENTRYS/*')
        for entries_node in entries_nodes:
            buildentries_node = None
            if entries_node.find('{*}SHORT-NAME') is None:
                buildentries_node = EnumerationMappingEntry()._build(self, entries_node, file, '[entries_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildentries_node = EnumerationMappingEntry()._build(self, entries_node, file)
            self.__entries[(buildentries_node)] = None

        return self

    def get_entries(self) -> list[EnumerationMappingEntry]:
        return list(self.__entries.keys())

    def add_entrie(self, value: EnumerationMappingEntry) -> None:
        """
        Adds a single value to the entries
        """
        if value is not None:
            if isinstance(value, Referrable) and any(v.name == value.name for v in self.__entries.keys()):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, EnumerationMappingEntry) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of EnumerationMappingEntry or its sub-classes'.format(value))
            self.__entries[value] = None
            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            value._parent = self #set parent
            value.file = self.file
            if value.name is not None:
                value._update_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'EnumerationMappingEntry_@' + str(len(self.get_children()))) #updates the path
            XDT.mark_dirty(value, self, attributesToMakeDirty = ['timestamp', 'checksum'])

    def set_entries(self, values: list[EnumerationMappingEntry]) -> None:
        """
        Adds a list of ref value to the entries
        """
        for value in values:
            self.add_entrie(value)

    def remove_entrie(self, value: EnumerationMappingEntry) -> None:
        """
        Removes a single value from entries
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__entries.pop(value)
            value._parent = None #No parent
            value._update_path() #resets the path
            value._node.getparent().remove(value._node)

    def remove_entries(self, values: list[EnumerationMappingEntry]) -> None:
        """
        Removes a list of value from entries
        """
        for value in values:
            self.remove_entrie(value)

    def new_Entrie(self, name: str=None) -> EnumerationMappingEntry:
        """
        Creates a new EnumerationMappingEntry under the EnumerationMappingTable.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        EnumerationMappingEntry_obj = EnumerationMappingEntry()
        if isinstance(EnumerationMappingEntry_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        EnumerationMappingEntry_obj.name = name if isinstance(EnumerationMappingEntry_obj, Referrable) else None
        self.add_entrie(EnumerationMappingEntry_obj)
        if isinstance(EnumerationMappingEntry_obj, Referrable):
            EnumerationMappingEntry_obj.set_shortName(name)
        return EnumerationMappingEntry_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        children.extend(self.__entries)
        return children

    def add_child(self, child: AutosarNode) -> None:
        if child is not None:
            super().add_child(child)
            if isinstance(child, EnumerationMappingEntry):
                self.__entries[child] = None


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        return property_values

    def _update_path(self):
        """
        Updates the path of the EnumerationMappingTable and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

    def is_atp_splitable(self) -> bool:
        return True

    def _save_contents(self):
        """
        Saves the content of EnumerationMappingTable node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_PackageableElement()
        if len(self.__entries) > 0:
            entries_values = AutosarNode._add_or_get_xml_node(self._node, 'ENTRYS', create_after_nodes = self._insert_after_tags + ['VARIATION-POINT', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'] + self._insert_after_tags)
            for value in self.__entries:
                if XDT.is_dirty(value) and value.file == self.file:
                    value._node.tag = 'ENTRY'
			    
                    value._save_contents()
                    if value._node.getparent() is None or value._node.getparent() != entries_values:
                        entries_values.append(value._node)


class AtpBlueprint(Identifiable):
    """
    This meta-class represents the ability to act as a Blueprint. As this class is an abstract one, particular blueprint meta-classes inherit from this one.
    """
    def __init__(self):
        super().__init__()
        self.__shortNamePattern = None
        self.__blueprintPolicies = {} # using dict to preserve the order of elements

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        shortNamePattern_value = AutosarNode._get_node_text(node,'SHORT-NAME-PATTERN')
        if shortNamePattern_value is not None:
            self.__shortNamePattern = datatype_utils.get_string_value(shortNamePattern_value)

        refCounter = 0
        blueprintPolicies_obj_dict = {}
        blueprintPolicies_obj_dict['BLUEPRINT-POLICY-LIST'] = 'BlueprintPolicyList'
        blueprintPolicies_obj_dict['BLUEPRINT-POLICY-SINGLE'] = 'BlueprintPolicySingle'
        blueprintPolicies_obj_dict['BLUEPRINT-POLICY-NOT-MODIFIABLE'] = 'BlueprintPolicyNotModifiable'
        blueprintPolicies_nodes = self._node.findall('{*}BLUEPRINT-POLICYS/*')
        for blueprintPolicies_node in blueprintPolicies_nodes:
            buildblueprintPolicies_node = None
            if blueprintPolicies_node.find('{*}SHORT-NAME') is None:
                buildblueprintPolicies_node = __str_to_class__(blueprintPolicies_obj_dict[etree.QName(blueprintPolicies_node).localname])()._build(self, blueprintPolicies_node, file, '[blueprintPolicies_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildblueprintPolicies_node = __str_to_class__(blueprintPolicies_obj_dict[etree.QName(blueprintPolicies_node).localname])()._build(self, blueprintPolicies_node, file)
            self.__blueprintPolicies[buildblueprintPolicies_node] = None

        return self

    def get_shortNamePattern(self) -> str:
        return self.__shortNamePattern

    def set_shortNamePattern(self, value: str) -> None:
        self.__shortNamePattern = value
        XDT.mark_attribute_dirty('shortNamePattern', self)

    def get_blueprintPolicies(self) -> list[BlueprintPolicy]:
        return list(self.__blueprintPolicies.keys())

    def add_blueprintPolicie(self, value: BlueprintPolicy) -> None:
        """
        Adds a single value to the blueprintPolicies
        """
        if value is not None:
            if isinstance(value, Referrable) and any(v.name == value.name for v in self.__blueprintPolicies.keys()):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, BlueprintPolicy) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of BlueprintPolicy or its sub-classes'.format(value))
            self.__blueprintPolicies[value] = None
            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            value._parent = self #set parent
            value.file = self.file
            if value.name is not None:
                value._update_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'BlueprintPolicy_@' + str(len(self.get_children()))) #updates the path
            XDT.mark_dirty(value, self, attributesToMakeDirty = ['timestamp', 'checksum'])

    def set_blueprintPolicies(self, values: list[BlueprintPolicy]) -> None:
        """
        Adds a list of ref value to the blueprintPolicies
        """
        for value in values:
            self.add_blueprintPolicie(value)

    def remove_blueprintPolicie(self, value: BlueprintPolicy) -> None:
        """
        Removes a single value from blueprintPolicies
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__blueprintPolicies.pop(value)
            value._parent = None #No parent
            value._update_path() #resets the path
            value._node.getparent().remove(value._node)

    def remove_blueprintPolicies(self, values: list[BlueprintPolicy]) -> None:
        """
        Removes a list of value from blueprintPolicies
        """
        for value in values:
            self.remove_blueprintPolicie(value)

    def new_BlueprintPolicySingle(self, name: str=None) -> BlueprintPolicySingle:
        """
        Creates a new BlueprintPolicySingle under the AtpBlueprint.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        BlueprintPolicySingle_obj = BlueprintPolicySingle()
        if isinstance(BlueprintPolicySingle_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        BlueprintPolicySingle_obj.name = name if isinstance(BlueprintPolicySingle_obj, Referrable) else None
        self.add_blueprintPolicie(BlueprintPolicySingle_obj)
        if isinstance(BlueprintPolicySingle_obj, Referrable):
            BlueprintPolicySingle_obj.set_shortName(name)
        return BlueprintPolicySingle_obj

