class AclObjectSet(ARElement,AtpBlueprint,AtpBlueprintable):
    """
    This meta class represents the ability to denote a set of objects for which roles and rights (access control lists) shall be defined. It basically can define the objects based on, , * the nature of objects, * the involved blueprints, * the artifact in which the objects are serialized, * the definition of the object (in a definition - value pattern), * individual reference objects
    """
    def __init__(self):
        super().__init__()
        self.tag = 'ACL-OBJECT-SET'
        self._node = etree.Element('ACL-OBJECT-SET')
        self.__aclObjectClass = None
        self.__aclScope = None
        self.__collection = None
        self.__collection_as_string = None
        self.__derivedFromBlueprints = {} # using dict to preserve the order of elements
        self.__derivedFromBlueprints_as_string = {} # using dict to preserve the order of elements
        self.__engineeringObjects = {} # using dict to preserve the order of elements
        self.__objectDefinitions = {} # using dict to preserve the order of elements
        self.__objectDefinitions_as_string = {} # using dict to preserve the order of elements
        self.__objectDefintions = {} # using dict to preserve the order of elements
        self.__objectDefintions_as_string = {} # using dict to preserve the order of elements
        self.__objects = {} # using dict to preserve the order of elements
        self.__objects_as_string = {} # using dict to preserve the order of elements

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        aclObjectClass_value = AutosarNode._get_node_text(node,'ACL-OBJECT-CLASS')
        if aclObjectClass_value is not None:
            self.__aclObjectClass = datatype_utils.get_string_value(aclObjectClass_value)

        aclScope_value = AutosarNode._get_node_text(node,'ACL-SCOPE')
        if aclScope_value is not None:
            self.__aclScope = AclScopeEnum.get(aclScope_value)

        refCounter = 0
        engineeringObjects_nodes = self._node.findall('{*}ENGINEERING-OBJECTS/*')
        for engineeringObjects_node in engineeringObjects_nodes:
            buildengineeringObjects_node = None
            if engineeringObjects_node.find('{*}SHORT-NAME') is None:
                buildengineeringObjects_node = AutosarEngineeringObject()._build(self, engineeringObjects_node, file, '[engineeringObjects_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildengineeringObjects_node = AutosarEngineeringObject()._build(self, engineeringObjects_node, file)
            self.__engineeringObjects[(buildengineeringObjects_node)] = None

        return self

    def _resolve_references(self):
        super()._resolve_references()
        collection_node = self._node.find('{*}COLLECTION-REF')
        if collection_node is not None and collection_node.text is not None:
            refText = ''
            refBase = collection_node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + collection_node.text
            self.__collection_as_string = refText
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__collection = ref_value

        derivedFromBlueprints_nodes = self._node.findall('{*}DERIVED-FROM-BLUEPRINT-REFS/*')
        for node in derivedFromBlueprints_nodes:
            if node.text is None:
                continue
            refText = ''
            refBase = node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + node.text
            self.__derivedFromBlueprints_as_string[refText] = None
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__derivedFromBlueprints[ref_value] = None

        objectDefinitions_nodes = self._node.findall('{*}OBJECT-DEFINITION-REFS/*')
        for node in objectDefinitions_nodes:
            if node.text is None:
                continue
            refText = ''
            refBase = node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + node.text
            self.__objectDefinitions_as_string[refText] = None
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__objectDefinitions[ref_value] = None

        objectDefintions_nodes = self._node.findall('{*}OBJECT-DEFINTION-REFS/*')
        for node in objectDefintions_nodes:
            if node.text is None:
                continue
            refText = ''
            refBase = node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + node.text
            self.__objectDefintions_as_string[refText] = None
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__objectDefintions[ref_value] = None

        objects_nodes = self._node.findall('{*}OBJECT-REFS/*')
        for node in objects_nodes:
            if node.text is None:
                continue
            refText = ''
            refBase = node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + node.text
            self.__objects_as_string[refText] = None
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__objects[ref_value] = None


