class DocumentationContext(MultilanguageReferrable):
    """
    This class represents the ability to denote a context of a so called standalone  documentation. Note that this is an <<atpMixed>>. The contents needs to be considered as ordered.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'DOCUMENTATION-CONTEXT'
        self._node = etree.Element('DOCUMENTATION-CONTEXT')
        self.__feature = None
        self.__identifiable = None
        self.__identifiable_as_string = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        feature_node = self._node.find('{*}FEATURE-IREF')
        if feature_node is not None:
            if feature_node.find('{*}SHORT-NAME') is None:
                self.__feature = AnyInstanceRef()._build(self, feature_node, file, '[feature_@]')
            else:
                self.__feature = AnyInstanceRef()._build(self, feature_node, file)

        return self

    def _resolve_references(self):
        super()._resolve_references()
        identifiable_node = self._node.find('{*}IDENTIFIABLE-REF')
        if identifiable_node is not None and identifiable_node.text is not None:
            refText = ''
            refBase = identifiable_node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + identifiable_node.text
            self.__identifiable_as_string = refText
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__identifiable = ref_value


    def get_feature(self) -> AnyInstanceRef:
        return self.__feature

    def set_feature(self, value: AnyInstanceRef) -> None:
        """
        Adds a single value to the feature
        """
        if value is not None:
            if isinstance(value, AnyInstanceRef) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of AnyInstanceRef or its sub-classes'.format(value))
            #if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            self.__feature = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._build_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'AnyInstanceRef_@' + str(len(self.get_children()))) #updates the path
        elif self.__feature is not None:
            self.__feature = None
        XDT.mark_dirty(self.__feature, self)

    def get_identifiable(self) -> Identifiable:
        return self.__identifiable

    def get_identifiable_as_string(self) -> str:
        return self.__identifiable_as_string

    def set_identifiable(self, value: Identifiable) -> None:
        """
        Adds a single value to the identifiable
        """
        if value is not None:
            if isinstance(value, Identifiable) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of Identifiable or its sub-classes'.format(value))
            if self.__identifiable is not None:
                self.__identifiable.referenced_by.remove(self)
            self.__identifiable = value
            value.referenced_by.add(self)
        elif self.__identifiable is not None:
            self.__identifiable.referenced_by.remove(self)
            self.__identifiable = None
        XDT.mark_dirty(self.__identifiable, self)

    def new_Feature(self, name: str=None) -> AnyInstanceRef:
        """
        Creates a new AnyInstanceRef under the DocumentationContext.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        AnyInstanceRef_obj = AnyInstanceRef()
        if isinstance(AnyInstanceRef_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        AnyInstanceRef_obj.name = name if isinstance(AnyInstanceRef_obj, Referrable) else None
        self.set_feature(AnyInstanceRef_obj)
        if isinstance(AnyInstanceRef_obj, Referrable):
            AnyInstanceRef_obj.set_shortName(name)
        return AnyInstanceRef_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        if self.__feature is not None:
            children.append(self.__feature)
        return children



    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['Identifiable'] = self.__identifiable
        return property_values

    def _update_path(self):
        """
        Updates the path of the DocumentationContext and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()


    def _save_contents(self):
        """
        Saves the content of DocumentationContext node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_MultilanguageReferrable()
        if self.__feature is not None:
            if XDT.is_dirty(self.__feature) and self.__feature.file == self.file:
                self.__feature._node.tag = 'FEATURE-IREF'
                self.__feature._save_contents()
                if self._node.find('{*}FEATURE-IREF') is None:
                    AutosarNode._insert_element_after_given_tags(self._node, self.__feature._node, create_after_nodes = self._insert_after_tags + ['LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])
        else:
            AutosarNode._remove_xml_node_if_exists(self._node, 'FEATURE-IREF')

        if self.__identifiable is None:
            AutosarNode._remove_xml_node_if_exists(self._node, 'IDENTIFIABLE-REF')
        elif XDT.is_dirty(self.__identifiable):
            identifiable_value = AutosarNode._add_or_get_xml_node(self._node, 'IDENTIFIABLE-REF', dest = self.__identifiable, create_after_nodes = self._insert_after_tags + ['FEATURE-IREF', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'] + self._insert_after_tags)
            identifiable_value.text = self.__identifiable.autosar_path
            identifiable_value.attrib['DEST'] = self.__identifiable.tag


class Documentation(ARElement):
    """
    This meta-class represents the ability to handle a so called standalone documentation. Standalone means, that such a documentation is not embedded in another ARElement or identifiable object.  The standalone documentation is an entity of its own which denotes its context by reference to other objects and instances.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'DOCUMENTATION'
        self._node = etree.Element('DOCUMENTATION')
        self.__contexts = {} # using dict to preserve the order of elements
        self.__documentationContent = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        refCounter = 0
        contexts_nodes = self._node.findall('{*}CONTEXTS/*')
        for contexts_node in contexts_nodes:
            buildcontexts_node = None
            if contexts_node.find('{*}SHORT-NAME') is None:
                buildcontexts_node = DocumentationContext()._build(self, contexts_node, file, '[contexts_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildcontexts_node = DocumentationContext()._build(self, contexts_node, file)
            self.__contexts[(buildcontexts_node)] = None

        documentationContent_node = self._node.find('{*}DOCUMENTATION-CONTENT')
        if documentationContent_node is not None:
            if documentationContent_node.find('{*}SHORT-NAME') is None:
                self.__documentationContent = PredefinedChapter()._build(self, documentationContent_node, file, '[documentationContent_@]')
            else:
                self.__documentationContent = PredefinedChapter()._build(self, documentationContent_node, file)

        return self

    def get_contexts(self) -> list[DocumentationContext]:
        return list(self.__contexts.keys())

    def add_context(self, value: DocumentationContext) -> None:
        """
        Adds a single value to the contexts
        """
        if value is not None:
            if isinstance(value, Referrable) and any(v.name == value.name for v in self.__contexts.keys()):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, DocumentationContext) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of DocumentationContext or its sub-classes'.format(value))
            self.__contexts[value] = None
            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            value._parent = self #set parent
            value.file = self.file
            if value.name is not None:
                value._update_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'DocumentationContext_@' + str(len(self.get_children()))) #updates the path
            XDT.mark_dirty(value, self, attributesToMakeDirty = ['shortName', 'timestamp', 'checksum'])

    def set_contexts(self, values: list[DocumentationContext]) -> None:
        """
        Adds a list of ref value to the contexts
        """
        for value in values:
            self.add_context(value)

    def remove_context(self, value: DocumentationContext) -> None:
        """
        Removes a single value from contexts
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__contexts.pop(value)
            value._parent = None #No parent
            value._update_path() #resets the path
            value._node.getparent().remove(value._node)

    def remove_contexts(self, values: list[DocumentationContext]) -> None:
        """
        Removes a list of value from contexts
        """
        for value in values:
            self.remove_context(value)

    def get_documentationContent(self) -> PredefinedChapter:
        return self.__documentationContent

    def set_documentationContent(self, value: PredefinedChapter) -> None:
        """
        Adds a single value to the documentationContent
        """
        if value is not None:
            if isinstance(value, PredefinedChapter) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of PredefinedChapter or its sub-classes'.format(value))
            #if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            self.__documentationContent = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._build_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'PredefinedChapter_@' + str(len(self.get_children()))) #updates the path
        elif self.__documentationContent is not None:
            self.__documentationContent = None
        XDT.mark_dirty(self.__documentationContent, self)

    def new_DocumentationContent(self, name: str=None) -> PredefinedChapter:
        """
        Creates a new PredefinedChapter under the Documentation.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        PredefinedChapter_obj = PredefinedChapter()
        if isinstance(PredefinedChapter_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        PredefinedChapter_obj.name = name if isinstance(PredefinedChapter_obj, Referrable) else None
        self.set_documentationContent(PredefinedChapter_obj)
        if isinstance(PredefinedChapter_obj, Referrable):
            PredefinedChapter_obj.set_shortName(name)
        return PredefinedChapter_obj

    def new_Context(self, name: str=None) -> DocumentationContext:
        """
        Creates a new DocumentationContext under the Documentation.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        DocumentationContext_obj = DocumentationContext()
        if isinstance(DocumentationContext_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        DocumentationContext_obj.name = name if isinstance(DocumentationContext_obj, Referrable) else None
        self.add_context(DocumentationContext_obj)
        if isinstance(DocumentationContext_obj, Referrable):
            DocumentationContext_obj.set_shortName(name)
        return DocumentationContext_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        children.extend(self.__contexts)
        if self.__documentationContent is not None:
            children.append(self.__documentationContent)
        return children

    def add_child(self, child: AutosarNode) -> None:
        if child is not None:
            super().add_child(child)
            if isinstance(child, DocumentationContext):
                self.__contexts[child] = None


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        return property_values

    def _update_path(self):
        """
        Updates the path of the Documentation and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

    def is_atp_splitable(self) -> bool:
        return True

    def _save_contents(self):
        """
        Saves the content of Documentation node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_ARElement()
        if len(self.__contexts) > 0:
            contexts_values = AutosarNode._add_or_get_xml_node(self._node, 'CONTEXTS', create_after_nodes = self._insert_after_tags + ['VARIATION-POINT', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'] + self._insert_after_tags)
            for value in self.__contexts:
                if XDT.is_dirty(value) and value.file == self.file:
                    value._save_contents()
                    if value._node.getparent() is None or value._node.getparent() != contexts_values:
                        contexts_values.append(value._node)

        if self.__documentationContent is not None:
            if XDT.is_dirty(self.__documentationContent) and self.__documentationContent.file == self.file:
                self.__documentationContent._node.tag = 'DOCUMENTATION-CONTENT'
                self.__documentationContent._save_contents()
                if self._node.find('{*}DOCUMENTATION-CONTENT') is None:
                    AutosarNode._insert_element_after_given_tags(self._node, self.__documentationContent._node, create_after_nodes = self._insert_after_tags + ['CONTEXTS', 'VARIATION-POINT', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])
        else:
            AutosarNode._remove_xml_node_if_exists(self._node, 'DOCUMENTATION-CONTENT')


