class Caption(MultilanguageReferrable):
    """
    This meta-class represents the ability to express a caption which is a title, and a shortName.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'CAPTION'
        self._node = etree.Element('CAPTION')
        self.__desc = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        desc_node = self._node.find('{*}DESC')
        if desc_node is not None:
            if desc_node.find('{*}SHORT-NAME') is None:
                self.__desc = MultiLanguageOverviewParagraph()._build(self, desc_node, file, '[desc_@]')
            else:
                self.__desc = MultiLanguageOverviewParagraph()._build(self, desc_node, file)

        return self

    def get_desc(self) -> MultiLanguageOverviewParagraph:
        return self.__desc

    def set_desc(self, value: MultiLanguageOverviewParagraph) -> None:
        """
        Adds a single value to the desc
        """
        if value is not None:
            if isinstance(value, MultiLanguageOverviewParagraph) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of MultiLanguageOverviewParagraph or its sub-classes'.format(value))
            #if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            self.__desc = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._build_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'MultiLanguageOverviewParagraph_@' + str(len(self.get_children()))) #updates the path
        elif self.__desc is not None:
            self.__desc = None
        XDT.mark_dirty(self.__desc, self)

    def new_Desc(self, name: str=None) -> MultiLanguageOverviewParagraph:
        """
        Creates a new MultiLanguageOverviewParagraph under the Caption.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        MultiLanguageOverviewParagraph_obj = MultiLanguageOverviewParagraph()
        if isinstance(MultiLanguageOverviewParagraph_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        MultiLanguageOverviewParagraph_obj.name = name if isinstance(MultiLanguageOverviewParagraph_obj, Referrable) else None
        self.set_desc(MultiLanguageOverviewParagraph_obj)
        if isinstance(MultiLanguageOverviewParagraph_obj, Referrable):
            MultiLanguageOverviewParagraph_obj.set_shortName(name)
        return MultiLanguageOverviewParagraph_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        if self.__desc is not None:
            children.append(self.__desc)
        return children



    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        return property_values

    def _update_path(self):
        """
        Updates the path of the Caption and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()


    def _save_contents(self):
        """
        Saves the content of Caption node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_MultilanguageReferrable()
        if self.__desc is not None:
            if XDT.is_dirty(self.__desc) and self.__desc.file == self.file:
                self.__desc._node.tag = 'DESC'
                self.__desc._save_contents()
                if self._node.find('{*}DESC') is None:
                    AutosarNode._insert_element_after_given_tags(self._node, self.__desc._node, create_after_nodes = self._insert_after_tags + ['LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])
        else:
            AutosarNode._remove_xml_node_if_exists(self._node, 'DESC')


