class TraceableTable(Identifiable,Paginateable,Traceable):
    """
    This meta-class represents the ability to denote a traceable table item such as requirements etc..
    """
    def __init__(self):
        super().__init__()
        self.tag = 'TRACEABLE-TABLE'
        self._node = etree.Element('TRACEABLE-TABLE')
        self.__table = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        table_node = self._node.find('{*}TABLE')
        if table_node is not None:
            if table_node.find('{*}SHORT-NAME') is None:
                self.__table = Table()._build(self, table_node, file, '[table_@]')
            else:
                self.__table = Table()._build(self, table_node, file)

        return self

    def get_table(self) -> Table:
        return self.__table

    def set_table(self, value: Table) -> None:
        """
        Adds a single value to the table
        """
        if value is not None:
            if isinstance(value, Table) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of Table or its sub-classes'.format(value))
            #if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            self.__table = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._build_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'Table_@' + str(len(self.get_children()))) #updates the path
        elif self.__table is not None:
            self.__table = None
        XDT.mark_dirty(self.__table, self)

    def new_Table(self, name: str=None) -> Table:
        """
        Creates a new Table under the TraceableTable.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        Table_obj = Table()
        if isinstance(Table_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        Table_obj.name = name if isinstance(Table_obj, Referrable) else None
        self.set_table(Table_obj)
