class LGraphic(LanguageSpecific):
    """
    This meta-class represents the figure in one particular language.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'L-GRAPHIC'
        self._node = etree.Element('L-GRAPHIC')
        self.__graphic = None
        self.__map = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        graphic_node = self._node.find('{*}GRAPHIC')
        if graphic_node is not None:
            if graphic_node.find('{*}SHORT-NAME') is None:
                self.__graphic = Graphic()._build(self, graphic_node, file, '[graphic_@]')
            else:
                self.__graphic = Graphic()._build(self, graphic_node, file)

        map_node = self._node.find('{*}MAP')
        if map_node is not None:
            if map_node.find('{*}SHORT-NAME') is None:
                self.__map = Map()._build(self, map_node, file, '[map_@]')
            else:
                self.__map = Map()._build(self, map_node, file)

        return self

    def get_graphic(self) -> Graphic:
        return self.__graphic

    def set_graphic(self, value: Graphic) -> None:
        """
        Adds a single value to the graphic
        """
        if value is not None:
            if isinstance(value, Graphic) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of Graphic or its sub-classes'.format(value))
            #if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            self.__graphic = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._build_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'Graphic_@' + str(len(self.get_children()))) #updates the path
        elif self.__graphic is not None:
            self.__graphic = None
        XDT.mark_dirty(self.__graphic, self)

    def get_map(self) -> Map:
        return self.__map

    def set_map(self, value: Map) -> None:
        """
        Adds a single value to the map
        """
        if value is not None:
            if isinstance(value, Map) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of Map or its sub-classes'.format(value))
            #if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            self.__map = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._build_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'Map_@' + str(len(self.get_children()))) #updates the path
        elif self.__map is not None:
            self.__map = None
        XDT.mark_dirty(self.__map, self)

    def new_Graphic(self, name: str=None) -> Graphic:
        """
        Creates a new Graphic under the LGraphic.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        Graphic_obj = Graphic()
        if isinstance(Graphic_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        Graphic_obj.name = name if isinstance(Graphic_obj, Referrable) else None
        self.set_graphic(Graphic_obj)
        if isinstance(Graphic_obj, Referrable):
            Graphic_obj.set_shortName(name)
        return Graphic_obj

    def new_Map(self, name: str=None) -> Map:
        """
        Creates a new Map under the LGraphic.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        Map_obj = Map()
        if isinstance(Map_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        Map_obj.name = name if isinstance(Map_obj, Referrable) else None
        self.set_map(Map_obj)
        if isinstance(Map_obj, Referrable):
            Map_obj.set_shortName(name)
        return Map_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        if self.__graphic is not None:
            children.append(self.__graphic)
        if self.__map is not None:
            children.append(self.__map)
        return children



