class Map(ARObject):
    """
    Image maps enable authors to specify regions of an image or object and assign a specific action to each region (e.g., retrieve a document, run a program, etc.) When the region is activated by the user, the action is executed., , The class follows the html approach and is intended to support interactive documents.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'MAP'
        self._node = etree.Element('MAP')
        self.__class = None
        self.__name = None
        self.__onclick = None
        self.__ondblclick = None
        self.__onkeydown = None
        self.__onkeypress = None
        self.__onkeyup = None
        self.__onmousedown = None
        self.__onmousemove = None
        self.__onmouseout = None
        self.__onmouseover = None
        self.__onmouseup = None
        self.__style = None
        self.__title = None
        self.__areas = {} # using dict to preserve the order of elements

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        class_value = node.attrib.get('CLASS')
        if class_value is not None:
            self.__class = datatype_utils.get_string_value(class_value)

        name_value = node.attrib.get('NAME')
        if name_value is not None:
            self.__name = datatype_utils.get_string_value(name_value)

        onclick_value = node.attrib.get('ONCLICK')
        if onclick_value is not None:
            self.__onclick = datatype_utils.get_string_value(onclick_value)

        ondblclick_value = node.attrib.get('ONDBLCLICK')
        if ondblclick_value is not None:
            self.__ondblclick = datatype_utils.get_string_value(ondblclick_value)

        onkeydown_value = node.attrib.get('ONKEYDOWN')
        if onkeydown_value is not None:
            self.__onkeydown = datatype_utils.get_string_value(onkeydown_value)

        onkeypress_value = node.attrib.get('ONKEYPRESS')
        if onkeypress_value is not None:
            self.__onkeypress = datatype_utils.get_string_value(onkeypress_value)

        onkeyup_value = node.attrib.get('ONKEYUP')
        if onkeyup_value is not None:
            self.__onkeyup = datatype_utils.get_string_value(onkeyup_value)

        onmousedown_value = node.attrib.get('ONMOUSEDOWN')
        if onmousedown_value is not None:
            self.__onmousedown = datatype_utils.get_string_value(onmousedown_value)

        onmousemove_value = node.attrib.get('ONMOUSEMOVE')
        if onmousemove_value is not None:
            self.__onmousemove = datatype_utils.get_string_value(onmousemove_value)

        onmouseout_value = node.attrib.get('ONMOUSEOUT')
        if onmouseout_value is not None:
            self.__onmouseout = datatype_utils.get_string_value(onmouseout_value)

        onmouseover_value = node.attrib.get('ONMOUSEOVER')
        if onmouseover_value is not None:
            self.__onmouseover = datatype_utils.get_string_value(onmouseover_value)

        onmouseup_value = node.attrib.get('ONMOUSEUP')
        if onmouseup_value is not None:
            self.__onmouseup = datatype_utils.get_string_value(onmouseup_value)

        style_value = node.attrib.get('STYLE')
        if style_value is not None:
            self.__style = datatype_utils.get_string_value(style_value)

        title_value = node.attrib.get('TITLE')
        if title_value is not None:
            self.__title = datatype_utils.get_string_value(title_value)

        refCounter = 0
        areas_nodes = self._node.findall('{*}AREA')
        for areas_node in areas_nodes:
            buildareas_node = None
            if areas_node.find('{*}SHORT-NAME') is None:
                buildareas_node = Area()._build(self, areas_node, file, '[areas_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildareas_node = Area()._build(self, areas_node, file)
            self.__areas[(buildareas_node)] = None

        return self

    def get_class(self) -> str:
        return self.__class

    def set_class(self, value: str) -> None:
        self.__class = value
        XDT.mark_attribute_dirty('class', self)

