class DefItem(MultilanguageReferrable,Paginateable):
    """
    This represents an entry in a definition list. The defined item is specified using shortName and longName.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'DEF-ITEM'
        self._node = etree.Element('DEF-ITEM')
        self.__helpEntry = None
        self.__def = None
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        helpEntry_value = node.attrib.get('HELP-ENTRY')
        if helpEntry_value is not None:
            self.__helpEntry = datatype_utils.get_string_value(helpEntry_value)

        def_node = self._node.find('{*}DEF')
        if def_node is not None:
            if def_node.find('{*}SHORT-NAME') is None:
                self.__def = DocumentationBlock()._build(self, def_node, file, '[def_@]')
            else:
                self.__def = DocumentationBlock()._build(self, def_node, file)

        variationPoint_node = self._node.find('{*}VARIATION-POINT')
        if variationPoint_node is not None:
            if variationPoint_node.find('{*}SHORT-NAME') is None:
                self.__variationPoint = VariationPoint()._build(self, variationPoint_node, file, '[variationPoint_@]')
            else:
                self.__variationPoint = VariationPoint()._build(self, variationPoint_node, file)

        return self

    def get_helpEntry(self) -> str:
        return self.__helpEntry

    def set_helpEntry(self, value: str) -> None:
        self.__helpEntry = value
        XDT.mark_attribute_dirty('helpEntry', self)

    def get_def(self) -> DocumentationBlock:
        return self.__def

    def set_def(self, value: DocumentationBlock) -> None:
        """
        Adds a single value to the def
        """
        if value is not None:
            if isinstance(value, DocumentationBlock) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of DocumentationBlock or its sub-classes'.format(value))
            #if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            self.__def = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._build_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'DocumentationBlock_@' + str(len(self.get_children()))) #updates the path
        elif self.__def is not None:
            self.__def = None
        XDT.mark_dirty(self.__def, self)

    def get_variationPoint(self) -> VariationPoint:
        return self.__variationPoint

    def set_variationPoint(self, value: VariationPoint) -> None:
        """
        Adds a single value to the variationPoint
        """
        if value is not None:
            if isinstance(value, VariationPoint) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of VariationPoint or its sub-classes'.format(value))
            #if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            self.__variationPoint = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._build_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'VariationPoint_@' + str(len(self.get_children()))) #updates the path
        elif self.__variationPoint is not None:
            self.__variationPoint = None
        XDT.mark_dirty(self.__variationPoint, self)

    def new_Def(self, name: str=None) -> DocumentationBlock:
        """
        Creates a new DocumentationBlock under the DefItem.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        DocumentationBlock_obj = DocumentationBlock()
        if isinstance(DocumentationBlock_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        DocumentationBlock_obj.name = name if isinstance(DocumentationBlock_obj, Referrable) else None
        self.set_def(DocumentationBlock_obj)
        if isinstance(DocumentationBlock_obj, Referrable):
            DocumentationBlock_obj.set_shortName(name)
        return DocumentationBlock_obj

    def new_VariationPoint(self, name: str=None) -> VariationPoint:
        """
        Creates a new VariationPoint under the DefItem.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        VariationPoint_obj = VariationPoint()
        if isinstance(VariationPoint_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        VariationPoint_obj.name = name if isinstance(VariationPoint_obj, Referrable) else None
        self.set_variationPoint(VariationPoint_obj)
        if isinstance(VariationPoint_obj, Referrable):
            VariationPoint_obj.set_shortName(name)
        return VariationPoint_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        if self.__def is not None:
            children.append(self.__def)
        if self.__variationPoint is not None:
            children.append(self.__variationPoint)
        return children



    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['HelpEntry'] = self.__helpEntry
        return property_values

    def _update_path(self):
        """
        Updates the path of the DefItem and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()


    def _save_contents(self):
        """
        Saves the content of DefItem node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_MultilanguageReferrable()
        super()._save_Paginateable()
        if XDT.is_attribute_dirty('helpEntry', self):
            if self.__helpEntry is not None:
                self._node.attrib['HELP-ENTRY'] = str(self.__helpEntry) if self.__helpEntry is not None else ''

        if self.__def is not None:
            if XDT.is_dirty(self.__def) and self.__def.file == self.file:
                self.__def._node.tag = 'DEF'
                self.__def._save_contents()
                if self._node.find('{*}DEF') is None:
                    AutosarNode._insert_element_after_given_tags(self._node, self.__def._node, create_after_nodes = self._insert_after_tags + ['KEEP-WITH-PREVIOUS', 'BREAK', 'VIEW', 'SI', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])
        else:
            AutosarNode._remove_xml_node_if_exists(self._node, 'DEF')

        if self.__variationPoint is not None:
            if XDT.is_dirty(self.__variationPoint) and self.__variationPoint.file == self.file:
                self.__variationPoint._node.tag = 'VARIATION-POINT'
                self.__variationPoint._save_contents()
                if self._node.find('{*}VARIATION-POINT') is None:
                    AutosarNode._insert_element_after_given_tags(self._node, self.__variationPoint._node, create_after_nodes = self._insert_after_tags + ['DEF', 'KEEP-WITH-PREVIOUS', 'BREAK', 'VIEW', 'SI', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])
        else:
            AutosarNode._remove_xml_node_if_exists(self._node, 'VARIATION-POINT')


class IndentSample(ARObject):
    """
    This represents the ability to specify indentation of a labeled list by providing a sample content. This content can be measured by the rendering system in order to determine the width of indentation.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'INDENT-SAMPLE'
        self._node = etree.Element('INDENT-SAMPLE')
        self.__itemLabelPos = None
        self.__l2s = {} # using dict to preserve the order of elements

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        itemLabelPos_value = node.attrib.get('ITEM-LABEL-POS')
        if itemLabelPos_value is not None:
            self.__itemLabelPos = ItemLabelPosEnum.get(itemLabelPos_value)

        refCounter = 0
        l2s_nodes = self._node.findall('{*}L-2')
        for l2s_node in l2s_nodes:
            buildl2s_node = None
            if l2s_node.find('{*}SHORT-NAME') is None:
                buildl2s_node = LOverviewParagraph()._build(self, l2s_node, file, '[l2s_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildl2s_node = LOverviewParagraph()._build(self, l2s_node, file)
            self.__l2s[(buildl2s_node)] = None

        return self

    def get_itemLabelPos(self) -> ItemLabelPosEnum:
        return self.__itemLabelPos

    def set_itemLabelPos(self, value: ItemLabelPosEnum) -> None:
        self.__itemLabelPos = value
        XDT.mark_attribute_dirty('itemLabelPos', self)

    def get_l2s(self) -> list[LOverviewParagraph]:
        return list(self.__l2s.keys())

    def add_l2(self, value: LOverviewParagraph) -> None:
        """
        Adds a single value to the l2s
        """
        if value is not None:
            if isinstance(value, Referrable) and any(v.name == value.name for v in self.__l2s.keys()):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, LOverviewParagraph) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of LOverviewParagraph or its sub-classes'.format(value))
            self.__l2s[value] = None
            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            value._parent = self #set parent
            value.file = self.file
            if value.name is not None:
                value._update_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'LOverviewParagraph_@' + str(len(self.get_children()))) #updates the path
            XDT.mark_dirty(value, self, attributesToMakeDirty = ['subs', 'sups', 'l', 'timestamp', 'checksum'])

    def set_l2s(self, values: list[LOverviewParagraph]) -> None:
        """
        Adds a list of ref value to the l2s
        """
        for value in values:
            self.add_l2(value)

    def remove_l2(self, value: LOverviewParagraph) -> None:
        """
        Removes a single value from l2s
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__l2s.pop(value)
            value._parent = None #No parent
            value._update_path() #resets the path
            value._node.getparent().remove(value._node)

    def remove_l2s(self, values: list[LOverviewParagraph]) -> None:
        """
        Removes a list of value from l2s
        """
        for value in values:
            self.remove_l2(value)

    def new_L2(self, name: str=None) -> LOverviewParagraph:
        """
        Creates a new LOverviewParagraph under the IndentSample.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        LOverviewParagraph_obj = LOverviewParagraph()
        if isinstance(LOverviewParagraph_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        LOverviewParagraph_obj.name = name if isinstance(LOverviewParagraph_obj, Referrable) else None
        self.add_l2(LOverviewParagraph_obj)
        if isinstance(LOverviewParagraph_obj, Referrable):
            LOverviewParagraph_obj.set_shortName(name)
        return LOverviewParagraph_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        children.extend(self.__l2s)
        return children



    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['ItemLabelPos'] = self.__itemLabelPos
        return property_values

    def _update_path(self):
        """
        Updates the path of the IndentSample and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()


    def _save_contents(self):
        """
        Saves the content of IndentSample node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_ARObject()
        if XDT.is_attribute_dirty('itemLabelPos', self):
            if self.__itemLabelPos is not None:
                self._node.attrib['ITEM-LABEL-POS'] = self.__itemLabelPos.literal if self.__itemLabelPos is not None else ''

        if len(self.__l2s) > 0:
            for value in self.__l2s:
                if XDT.is_dirty(value) and value.file == self.file:
                    value._node.tag = 'L-2'
			    
                    value._save_contents()
                    AutosarNode._insert_element_after_given_tags(self._node, value._node, create_after_nodes = self._insert_after_tags + ['L-2'] + ['T', 'S'])


