class GeneralParameter(Identifiable):
    """
    This represents a parameter in general e.g. an entry in a data sheet.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'GENERAL-PARAMETER'
        self._node = etree.Element('GENERAL-PARAMETER')
        self.__prmChars = {} # using dict to preserve the order of elements

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        refCounter = 0
        prmChars_nodes = self._node.findall('{*}PRM-CHAR')
        for prmChars_node in prmChars_nodes:
            buildprmChars_node = None
            if prmChars_node.find('{*}SHORT-NAME') is None:
                buildprmChars_node = PrmChar()._build(self, prmChars_node, file, '[prmChars_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildprmChars_node = PrmChar()._build(self, prmChars_node, file)
            self.__prmChars[(buildprmChars_node)] = None

        return self

    def get_prmChars(self) -> list[PrmChar]:
        return list(self.__prmChars.keys())

    def add_prmChar(self, value: PrmChar) -> None:
        """
        Adds a single value to the prmChars
        """
        if value is not None:
            if isinstance(value, Referrable) and any(v.name == value.name for v in self.__prmChars.keys()):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, PrmChar) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of PrmChar or its sub-classes'.format(value))
            self.__prmChars[value] = None
            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            value._parent = self #set parent
            value.file = self.file
            if value.name is not None:
                value._update_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'PrmChar_@' + str(len(self.get_children()))) #updates the path
            XDT.mark_dirty(value, self, attributesToMakeDirty = ['timestamp', 'checksum'])

    def set_prmChars(self, values: list[PrmChar]) -> None:
        """
        Adds a list of ref value to the prmChars
        """
        for value in values:
            self.add_prmChar(value)

    def remove_prmChar(self, value: PrmChar) -> None:
        """
        Removes a single value from prmChars
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__prmChars.pop(value)
            value._parent = None #No parent
            value._update_path() #resets the path
            value._node.getparent().remove(value._node)

    def remove_prmChars(self, values: list[PrmChar]) -> None:
        """
        Removes a list of value from prmChars
        """
        for value in values:
            self.remove_prmChar(value)

    def new_PrmChar(self, name: str=None) -> PrmChar:
        """
        Creates a new PrmChar under the GeneralParameter.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        PrmChar_obj = PrmChar()
        if isinstance(PrmChar_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        PrmChar_obj.name = name if isinstance(PrmChar_obj, Referrable) else None
        self.add_prmChar(PrmChar_obj)
        if isinstance(PrmChar_obj, Referrable):
            PrmChar_obj.set_shortName(name)
        return PrmChar_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        children.extend(self.__prmChars)
        return children



    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        return property_values

    def _update_path(self):
        """
        Updates the path of the GeneralParameter and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()


