class ChapterModel(ARObject):
    """
    This is the basic content model of a chapter except the Chapter title. This can be utilized in general chapters as well as in predefined chapters., , A chapter has content on three levels:, , 1. chapter content, , 2. topics, , 3. subchapters
    """
    def __init__(self):
        super().__init__()
        self.tag = 'CHAPTER-MODEL'
        self._node = etree.Element('CHAPTER-MODEL')
        self.__prms = {} # using dict to preserve the order of elements
        self.__topicContents = {} # using dict to preserve the order of elements
        self.__msrQueryTopic1s = {} # using dict to preserve the order of elements
        self.__topic1s = {} # using dict to preserve the order of elements
        self.__chapters = {} # using dict to preserve the order of elements
        self.__msrQueryChapters = {} # using dict to preserve the order of elements

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        refCounter = 0
        prms_nodes = self._node.findall('{*}PRMS')
        for prms_node in prms_nodes:
            buildprms_node = None
            if prms_node.find('{*}SHORT-NAME') is None:
                buildprms_node = Prms()._build(self, prms_node, file, '[prms_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildprms_node = Prms()._build(self, prms_node, file)
            self.__prms[(buildprms_node)] = None

        topicContents_nodes = self._node.findall('{*}TOPIC-CONTENT')
        for topicContents_node in topicContents_nodes:
            buildtopicContents_node = None
            if topicContents_node.find('{*}SHORT-NAME') is None:
                buildtopicContents_node = TopicContentOrMsrQuery()._build(self, topicContents_node, file, '[topicContents_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildtopicContents_node = TopicContentOrMsrQuery()._build(self, topicContents_node, file)
            self.__topicContents[(buildtopicContents_node)] = None

        msrQueryTopic1s_nodes = self._node.findall('{*}MSR-QUERY-TOPIC-1')
        for msrQueryTopic1s_node in msrQueryTopic1s_nodes:
            buildmsrQueryTopic1s_node = None
            if msrQueryTopic1s_node.find('{*}SHORT-NAME') is None:
                buildmsrQueryTopic1s_node = MsrQueryTopic1()._build(self, msrQueryTopic1s_node, file, '[msrQueryTopic1s_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildmsrQueryTopic1s_node = MsrQueryTopic1()._build(self, msrQueryTopic1s_node, file)
            self.__msrQueryTopic1s[(buildmsrQueryTopic1s_node)] = None

        topic1s_nodes = self._node.findall('{*}TOPIC-1')
        for topic1s_node in topic1s_nodes:
            buildtopic1s_node = None
            if topic1s_node.find('{*}SHORT-NAME') is None:
                buildtopic1s_node = Topic1()._build(self, topic1s_node, file, '[topic1s_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildtopic1s_node = Topic1()._build(self, topic1s_node, file)
            self.__topic1s[(buildtopic1s_node)] = None

        chapters_nodes = self._node.findall('{*}CHAPTER')
        for chapters_node in chapters_nodes:
            buildchapters_node = None
            if chapters_node.find('{*}SHORT-NAME') is None:
                buildchapters_node = Chapter()._build(self, chapters_node, file, '[chapters_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildchapters_node = Chapter()._build(self, chapters_node, file)
            self.__chapters[(buildchapters_node)] = None

        msrQueryChapters_nodes = self._node.findall('{*}MSR-QUERY-CHAPTER')
        for msrQueryChapters_node in msrQueryChapters_nodes:
            buildmsrQueryChapters_node = None
            if msrQueryChapters_node.find('{*}SHORT-NAME') is None:
                buildmsrQueryChapters_node = MsrQueryChapter()._build(self, msrQueryChapters_node, file, '[msrQueryChapters_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildmsrQueryChapters_node = MsrQueryChapter()._build(self, msrQueryChapters_node, file)
            self.__msrQueryChapters[(buildmsrQueryChapters_node)] = None

        return self

    def get_prms(self) -> list[Prms]:
        return list(self.__prms.keys())

    def add_prm(self, value: Prms) -> None:
        """
        Adds a single value to the prms
        """
        if value is not None:
            if isinstance(value, Referrable) and any(v.name == value.name for v in self.__prms.keys()):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, Prms) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of Prms or its sub-classes'.format(value))
            self.__prms[value] = None
            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            value._parent = self #set parent
            value.file = self.file
            if value.name is not None:
                value._update_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'Prms_@' + str(len(self.get_children()))) #updates the path
            XDT.mark_dirty(value, self, attributesToMakeDirty = ['keepWithPrevious', 'break', 'view', 'si', 'timestamp', 'checksum'])

    def set_prms(self, values: list[Prms]) -> None:
        """
        Adds a list of ref value to the prms
        """
        for value in values:
            self.add_prm(value)

    def remove_prm(self, value: Prms) -> None:
        """
        Removes a single value from prms
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__prms.pop(value)
            value._parent = None #No parent
            value._update_path() #resets the path
            value._node.getparent().remove(value._node)

    def remove_prms(self, values: list[Prms]) -> None:
        """
        Removes a list of value from prms
        """
        for value in values:
            self.remove_prm(value)

