class WhitespaceControlled(ARObject):
    """
    This meta-class represents the ability to control the white-space handling  e.g. in xml serialization. This is implemented by adding the attribute "space".
    """
    def __init__(self):
        super().__init__()
        self.__xmlSpace = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        xmlSpace_value = node.attrib.get('space')
        if xmlSpace_value is not None:
            self.__xmlSpace = XmlSpaceEnum.get(xmlSpace_value)

        return self

    def get_xmlSpace(self) -> XmlSpaceEnum:
        return self.__xmlSpace

    def set_xmlSpace(self, value: XmlSpaceEnum) -> None:
        self.__xmlSpace = value
        XDT.mark_attribute_dirty('xmlSpace', self)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['XmlSpace'] = self.__xmlSpace
        return property_values

    def _update_path(self):
        """
        Updates the path of the WhitespaceControlled and its children.
        """
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()


    def _save_WhitespaceControlled(self):
        """
        Saves the content of WhitespaceControlled node
        """
        super()._save_ARObject()
        if XDT.is_attribute_dirty('xmlSpace', self):
            if self.__xmlSpace is not None:
                self._node.attrib['space'] = self.__xmlSpace.literal if self.__xmlSpace is not None else ''


