class MixedContentForVerbatim(WhitespaceControlled):
    """
    This is the text model for preformatted (verbatim) text. It mainly consists of attributes which do not change the length on rendering., , This class represents multilingual verbatim. Verbatim, sometimes called preformatted text, means that white-space is maintained. When verbatim is rendered in PDF or Online media, it is rendered using a monospaced font while white-space is obeyed. Blanks are rendered as well as newline characters., , Even if there are inline elements, the length of the data shall not be influenced by formatting.
    """
    def __init__(self):
        super().__init__()
        self.__tts = {} # using dict to preserve the order of elements
        self.__es = {} # using dict to preserve the order of elements
        self.__xrefs = {} # using dict to preserve the order of elements
        self.__brs = {} # using dict to preserve the order of elements

        self.__mixedtext = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        refCounter = 0
        tts_nodes = self._node.findall('{*}TT')
        for tts_node in tts_nodes:
            buildtts_node = None
            if tts_node.find('{*}SHORT-NAME') is None:
                buildtts_node = Tt()._build(self, tts_node, file, '[tts_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildtts_node = Tt()._build(self, tts_node, file)
            self.__tts[(buildtts_node)] = None

        es_nodes = self._node.findall('{*}E')
        for es_node in es_nodes:
            buildes_node = None
            if es_node.find('{*}SHORT-NAME') is None:
                buildes_node = EmphasisText()._build(self, es_node, file, '[es_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildes_node = EmphasisText()._build(self, es_node, file)
            self.__es[(buildes_node)] = None

        xrefs_nodes = self._node.findall('{*}XREF')
        for xrefs_node in xrefs_nodes:
            buildxrefs_node = None
            if xrefs_node.find('{*}SHORT-NAME') is None:
                buildxrefs_node = Xref()._build(self, xrefs_node, file, '[xrefs_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildxrefs_node = Xref()._build(self, xrefs_node, file)
            self.__xrefs[(buildxrefs_node)] = None

        brs_nodes = self._node.findall('{*}BR')
        for brs_node in brs_nodes:
            buildbrs_node = None
            if brs_node.find('{*}SHORT-NAME') is None:
                buildbrs_node = Br()._build(self, brs_node, file, '[brs_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildbrs_node = Br()._build(self, brs_node, file)
            self.__brs[(buildbrs_node)] = None

        return self

    def get_tts(self) -> list[Tt]:
        return list(self.__tts.keys())

    def add_tt(self, value: Tt) -> None:
        """
        Adds a single value to the tts
        """
        if value is not None:
            if isinstance(value, Referrable) and any(v.name == value.name for v in self.__tts.keys()):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, Tt) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of Tt or its sub-classes'.format(value))
