class IndexEntry(ARObject):
    """
    This class represents an index entry.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'INDEX-ENTRY'
        self._node = etree.Element('INDEX-ENTRY')
        self.__sups = None
        self.__subs = None

        self.__mixedtext = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        sups_value = AutosarNode._get_node_text(node,'SUP')
        if sups_value is not None:
            self.__sups = datatype_utils.get_string_value(sups_value)

        subs_value = AutosarNode._get_node_text(node,'SUB')
        if subs_value is not None:
            self.__subs = datatype_utils.get_string_value(subs_value)

        self.__mixedtext = node.text
        return self

    def get_sups(self) -> str:
        return self.__sups

    def set_sups(self, value: str) -> None:
        self.__sups = value
        XDT.mark_attribute_dirty('sups', self)

    def get_subs(self) -> str:
        return self.__subs

    def set_subs(self, value: str) -> None:
        self.__subs = value
        XDT.mark_attribute_dirty('subs', self)

    def get(self) -> str:
        return self.__mixedtext

    def set(self, text: str) -> None:
        self.__mixedtext = text
        if text is not None:
            self._node.text = str(text)
        else:
            self._node.text = ''
        XDT.mark_attribute_dirty('mixedtext', self)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['Sups'] = self.__sups
        property_values['Subs'] = self.__subs
        property_values['Value'] = self.__mixedtext
        return property_values

    def _update_path(self):
        """
        Updates the path of the IndexEntry and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()


    def _save_contents(self):
        """
        Saves the content of IndexEntry node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_ARObject()
        if XDT.is_attribute_dirty('sups', self):
            if self.__sups is None:
                AutosarNode._remove_xml_node_if_exists(self._node, 'SUP')
            else:
                sups_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'SUP', create_after_nodes = ['T', 'S'] + self._insert_after_tags)
                sups_xml_node.text = str(self.__sups)

        if XDT.is_attribute_dirty('subs', self):
            if self.__subs is None:
                AutosarNode._remove_xml_node_if_exists(self._node, 'SUB')
            else:
                subs_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'SUB', create_after_nodes = ['SUP', 'T', 'S'] + self._insert_after_tags)
                subs_xml_node.text = str(self.__subs)


class Std(SingleLanguageReferrable):
    """
    This represents a reference to external standards.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'STD'
        self._node = etree.Element('STD')
        self.__subtitle = None
        self.__state = None
        self.__date = None
        self.__position = None
        self.__url = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        subtitle_value = AutosarNode._get_node_text(node,'SUBTITLE')
        if subtitle_value is not None:
            self.__subtitle = datatype_utils.get_string_value(subtitle_value)

        state_value = AutosarNode._get_node_text(node,'STATE')
        if state_value is not None:
            self.__state = datatype_utils.get_string_value(state_value)

        date_value = AutosarNode._get_node_text(node,'DATE')
        if date_value is not None:
            self.__date = datatype_utils.get_string_value(date_value)

        position_value = AutosarNode._get_node_text(node,'POSITION')
        if position_value is not None:
            self.__position = datatype_utils.get_string_value(position_value)

        url_node = self._node.find('{*}URL')
        if url_node is not None:
            if url_node.find('{*}SHORT-NAME') is None:
                self.__url = Url()._build(self, url_node, file, '[url_@]')
            else:
                self.__url = Url()._build(self, url_node, file)

        return self

    def get_subtitle(self) -> str:
        return self.__subtitle

    def set_subtitle(self, value: str) -> None:
        self.__subtitle = value
        XDT.mark_attribute_dirty('subtitle', self)

    def get_state(self) -> str:
        return self.__state

    def set_state(self, value: str) -> None:
        self.__state = value
        XDT.mark_attribute_dirty('state', self)

    def get_date(self) -> str:
        return self.__date

    def set_date(self, value: str) -> None:
        self.__date = value
        XDT.mark_attribute_dirty('date', self)

    def get_position(self) -> str:
        return self.__position

    def set_position(self, value: str) -> None:
        self.__position = value
        XDT.mark_attribute_dirty('position', self)

    def get_url(self) -> Url:
        return self.__url

    def set_url(self, value: Url) -> None:
        """
        Adds a single value to the url
        """
        if value is not None:
            if isinstance(value, Url) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of Url or its sub-classes'.format(value))
            #if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            self.__url = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._build_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'Url_@' + str(len(self.get_children()))) #updates the path
        elif self.__url is not None:
            self.__url = None
        XDT.mark_dirty(self.__url, self)

    def new_Url(self, name: str=None) -> Url:
        """
        Creates a new Url under the Std.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        Url_obj = Url()
        if isinstance(Url_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        Url_obj.name = name if isinstance(Url_obj, Referrable) else None
        self.set_url(Url_obj)
        if isinstance(Url_obj, Referrable):
            Url_obj.set_shortName(name)
        return Url_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        if self.__url is not None:
            children.append(self.__url)
