class Xref(ARObject):
    """
    This represents a cross-reference within documentation.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'XREF'
        self._node = etree.Element('XREF')
        self.__resolutionPolicy = None
        self.__showContent = None
        self.__showResourceAliasName = None
        self.__showResourceCategory = None
        self.__showResourceLongName = None
        self.__showResourceNumber = None
        self.__showResourcePage = None
        self.__showResourceShortName = None
        self.__showResourceType = None
        self.__showSee = None
        self.__label1 = None
        self.__referrable = None
        self.__referrable_as_string = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        resolutionPolicy_value = node.attrib.get('RESOLUTION-POLICY')
        if resolutionPolicy_value is not None:
            self.__resolutionPolicy = ResolutionPolicyEnum.get(resolutionPolicy_value)

        showContent_value = node.attrib.get('SHOW-CONTENT')
        if showContent_value is not None:
            self.__showContent = ShowContentEnum.get(showContent_value)

        showResourceAliasName_value = node.attrib.get('SHOW-RESOURCE-ALIAS-NAME')
        if showResourceAliasName_value is not None:
            self.__showResourceAliasName = ShowResourceAliasNameEnum.get(showResourceAliasName_value)

        showResourceCategory_value = node.attrib.get('SHOW-RESOURCE-CATEGORY')
        if showResourceCategory_value is not None:
            self.__showResourceCategory = ShowResourceCategoryEnum.get(showResourceCategory_value)

        showResourceLongName_value = node.attrib.get('SHOW-RESOURCE-LONG-NAME')
        if showResourceLongName_value is not None:
            self.__showResourceLongName = ShowResourceLongNameEnum.get(showResourceLongName_value)

        showResourceNumber_value = node.attrib.get('SHOW-RESOURCE-NUMBER')
        if showResourceNumber_value is not None:
            self.__showResourceNumber = ShowResourceNumberEnum.get(showResourceNumber_value)

        showResourcePage_value = node.attrib.get('SHOW-RESOURCE-PAGE')
        if showResourcePage_value is not None:
            self.__showResourcePage = ShowResourcePageEnum.get(showResourcePage_value)

        showResourceShortName_value = node.attrib.get('SHOW-RESOURCE-SHORT-NAME')
        if showResourceShortName_value is not None:
            self.__showResourceShortName = ShowResourceShortNameEnum.get(showResourceShortName_value)

        showResourceType_value = node.attrib.get('SHOW-RESOURCE-TYPE')
        if showResourceType_value is not None:
            self.__showResourceType = ShowResourceTypeEnum.get(showResourceType_value)

        showSee_value = node.attrib.get('SHOW-SEE')
        if showSee_value is not None:
            self.__showSee = ShowSeeEnum.get(showSee_value)

        label1_node = self._node.find('{*}LABEL-1')
        if label1_node is not None:
            if label1_node.find('{*}SHORT-NAME') is None:
                self.__label1 = SingleLanguageLongName()._build(self, label1_node, file, '[label1_@]')
            else:
                self.__label1 = SingleLanguageLongName()._build(self, label1_node, file)

        return self

    def _resolve_references(self):
        super()._resolve_references()
        referrable_node = self._node.find('{*}REFERRABLE-REF')
        if referrable_node is not None and referrable_node.text is not None:
            refText = ''
            refBase = referrable_node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + referrable_node.text
            self.__referrable_as_string = refText
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__referrable = ref_value


