class EmphasisText(ARObject):
    """
    This is an emphasized text. As a compromise it contains some rendering oriented attributes such as color and font.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'EMPHASIS-TEXT'
        self._node = etree.Element('EMPHASIS-TEXT')
        self.__color = None
        self.__font = None
        self.__subs = None
        self.__sups = None
        self.__type = None
        self.__tts = {} # using dict to preserve the order of elements

        self.__mixedtext = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        color_value = node.attrib.get('COLOR')
        if color_value is not None:
            self.__color = datatype_utils.get_string_value(color_value)

        font_value = node.attrib.get('FONT')
        if font_value is not None:
            self.__font = EEnumFont.get(font_value)

        subs_value = AutosarNode._get_node_text(node,'SUB')
        if subs_value is not None:
            self.__subs = datatype_utils.get_string_value(subs_value)

        sups_value = AutosarNode._get_node_text(node,'SUP')
        if sups_value is not None:
            self.__sups = datatype_utils.get_string_value(sups_value)

        type_value = node.attrib.get('TYPE')
        if type_value is not None:
            self.__type = EEnum.get(type_value)

        refCounter = 0
        tts_nodes = self._node.findall('{*}TT')
        for tts_node in tts_nodes:
            buildtts_node = None
            if tts_node.find('{*}SHORT-NAME') is None:
                buildtts_node = Tt()._build(self, tts_node, file, '[tts_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildtts_node = Tt()._build(self, tts_node, file)
            self.__tts[(buildtts_node)] = None

        self.__mixedtext = node.text
        return self

    def get_color(self) -> str:
        return self.__color

    def set_color(self, value: str) -> None:
        self.__color = value
        XDT.mark_attribute_dirty('color', self)

    def get_font(self) -> EEnumFont:
        return self.__font

    def set_font(self, value: EEnumFont) -> None:
        self.__font = value
        XDT.mark_attribute_dirty('font', self)

    def get_subs(self) -> str:
        return self.__subs

    def set_subs(self, value: str) -> None:
        self.__subs = value
        XDT.mark_attribute_dirty('subs', self)

    def get_sups(self) -> str:
        return self.__sups

    def set_sups(self, value: str) -> None:
        self.__sups = value
        XDT.mark_attribute_dirty('sups', self)

    def get_type(self) -> EEnum:
        return self.__type

    def set_type(self, value: EEnum) -> None:
        self.__type = value
        XDT.mark_attribute_dirty('type', self)

    def get_tts(self) -> list[Tt]:
        return list(self.__tts.keys())

    def add_tt(self, value: Tt) -> None:
        """
        Adds a single value to the tts
        """
        if value is not None:
            if isinstance(value, Referrable) and any(v.name == value.name for v in self.__tts.keys()):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, Tt) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of Tt or its sub-classes'.format(value))
            self.__tts[value] = None
            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            value._parent = self #set parent
            value.file = self.file
            if value.name is not None:
                value._update_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'Tt_@' + str(len(self.get_children()))) #updates the path
            XDT.mark_dirty(value, self, attributesToMakeDirty = ['timestamp', 'checksum'])

    def set_tts(self, values: list[Tt]) -> None:
        """
        Adds a list of ref value to the tts
        """
        for value in values:
            self.add_tt(value)

    def remove_tt(self, value: Tt) -> None:
        """
        Removes a single value from tts
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__tts.pop(value)
            value._parent = None #No parent
            value._update_path() #resets the path
            value._node.getparent().remove(value._node)

    def remove_tts(self, values: list[Tt]) -> None:
        """
        Removes a list of value from tts
        """
        for value in values:
            self.remove_tt(value)

    def new_Tt(self, name: str=None) -> Tt:
        """
        Creates a new Tt under the EmphasisText.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        Tt_obj = Tt()
        if isinstance(Tt_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        Tt_obj.name = name if isinstance(Tt_obj, Referrable) else None
        self.add_tt(Tt_obj)
        if isinstance(Tt_obj, Referrable):
            Tt_obj.set_shortName(name)
        return Tt_obj

    def get(self) -> str:
        return self.__mixedtext

    def set(self, text: str) -> None:
        self.__mixedtext = text
        if text is not None:
            self._node.text = str(text)
        else:
            self._node.text = ''
        XDT.mark_attribute_dirty('mixedtext', self)

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        children.extend(self.__tts)
        return children



    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['Color'] = self.__color
        property_values['Font'] = self.__font
        property_values['Subs'] = self.__subs
        property_values['Sups'] = self.__sups
        property_values['Type'] = self.__type
        property_values['Value'] = self.__mixedtext
        return property_values

    def _update_path(self):
        """
        Updates the path of the EmphasisText and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()


    def _save_contents(self):
        """
        Saves the content of EmphasisText node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_ARObject()
        if XDT.is_attribute_dirty('color', self):
            if self.__color is not None:
                self._node.attrib['COLOR'] = str(self.__color) if self.__color is not None else ''

        if XDT.is_attribute_dirty('font', self):
            if self.__font is not None:
                self._node.attrib['FONT'] = self.__font.literal if self.__font is not None else ''

        if XDT.is_attribute_dirty('subs', self):
            if self.__subs is None:
                AutosarNode._remove_xml_node_if_exists(self._node, 'SUB')
            else:
                subs_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'SUB', create_after_nodes = ['T', 'S'] + self._insert_after_tags)
                subs_xml_node.text = str(self.__subs)

        if XDT.is_attribute_dirty('sups', self):
            if self.__sups is None:
                AutosarNode._remove_xml_node_if_exists(self._node, 'SUP')
            else:
                sups_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'SUP', create_after_nodes = ['SUB', 'T', 'S'] + self._insert_after_tags)
                sups_xml_node.text = str(self.__sups)

        if XDT.is_attribute_dirty('type', self):
            if self.__type is not None:
                self._node.attrib['TYPE'] = self.__type.literal if self.__type is not None else ''

        if len(self.__tts) > 0:
            for value in self.__tts:
                if XDT.is_dirty(value) and value.file == self.file:
                    value._node.tag = 'TT'
			    
                    value._save_contents()
                    AutosarNode._insert_element_after_given_tags(self._node, value._node, create_after_nodes = self._insert_after_tags + ['TT'] + ['SUP', 'SUB', 'T', 'S'])


