class ARPackage(CollectableElement,AtpBlueprint,AtpBlueprintable):
    """
    AUTOSAR package, allowing to create top level packages to structure the contained ARElements., , ARPackages are open sets. This means that in a file based description system multiple files can be used to partially describe the contents of a package., , This is an extended version of MSR's SW-SYSTEM.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'AR-PACKAGE'
        self._node = etree.Element('AR-PACKAGE')
        self.__referenceBases = {} # using dict to preserve the order of elements
        self.__elements = {} # using dict to preserve the order of elements
        self.__arPackages = {} # using dict to preserve the order of elements
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        refCounter = 0
        referenceBases_nodes = self._node.findall('{*}REFERENCE-BASES/*')
        for referenceBases_node in referenceBases_nodes:
            buildreferenceBases_node = None
            if referenceBases_node.find('{*}SHORT-NAME') is None:
                buildreferenceBases_node = ReferenceBase()._build(self, referenceBases_node, file, '[referenceBases_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildreferenceBases_node = ReferenceBase()._build(self, referenceBases_node, file)
            self.__referenceBases[(buildreferenceBases_node)] = None

