class ReferenceBase(ARObject):
    """
    This meta-class establishes a basis for relative references. Reference bases are identified by the shortLabel which shall be unique in the current package.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'REFERENCE-BASE'
        self._node = etree.Element('REFERENCE-BASE')
        self.__shortLabel = None
        self.__isDefault = None
        self.__isGlobal = None
        self.__baseIsThisPackage = None
        self.__globalElements = None
        self.__globalInPackages = {} # using dict to preserve the order of elements
        self.__globalInPackages_as_string = {} # using dict to preserve the order of elements
        self.__package = None
