class SdgAggregationWithVariation(SdgAttribute,SdgElementWithGid,AbstractVariationRestriction):
    """
    Describes that the Sdg may contain another Sdg. The gid of the nested Sdg is defined by subSdg. , , Represents 'sdg'.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'SDG-AGGREGATION-WITH-VARIATION'
        self._node = etree.Element('SDG-AGGREGATION-WITH-VARIATION')
        self.__subSdg = None
        self.__subSdg_as_string = None


    def _resolve_references(self):
        super()._resolve_references()
        subSdg_node = self._node.find('{*}SUB-SDG-REF')
        if subSdg_node is not None and subSdg_node.text is not None:
            refText = ''
            refBase = subSdg_node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + subSdg_node.text
            self.__subSdg_as_string = refText
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__subSdg = ref_value


    def get_subSdg(self) -> SdgClass:
        return self.__subSdg

    def get_subSdg_as_string(self) -> str:
        return self.__subSdg_as_string

    def set_subSdg(self, value: SdgClass) -> None:
        """
        Adds a single value to the subSdg
        """
        if value is not None:
            if isinstance(value, SdgClass) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of SdgClass or its sub-classes'.format(value))
            if self.__subSdg is not None:
                self.__subSdg.referenced_by.remove(self)
            self.__subSdg = value
            value.referenced_by.add(self)
        elif self.__subSdg is not None:
            self.__subSdg.referenced_by.remove(self)
            self.__subSdg = None
        XDT.mark_dirty(self.__subSdg, self)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['SubSdg'] = self.__subSdg
        return property_values

    def _update_path(self):
        """
        Updates the path of the SdgAggregationWithVariation and its children.
        """
        self._build_path()
