    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        value_obj_dict = {}
        value_obj_dict['APPLICATION-RULE-BASED-VALUE-SPECIFICATION'] = 'ApplicationRuleBasedValueSpecification'
        value_obj_dict['COMPOSITE-RULE-BASED-VALUE-SPECIFICATION'] = 'CompositeRuleBasedValueSpecification'
