class PortPrototypeBlueprintMapping(AtpBlueprintMapping):
    """
    This meta-class represents the ability to map a PortPrototypeBlueprint to a PortProtoype of which one acts as the blueprint for the other.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'PORT-PROTOTYPE-BLUEPRINT-MAPPING'
        self._node = etree.Element('PORT-PROTOTYPE-BLUEPRINT-MAPPING')
        self.__portPrototypeBlueprint = None
        self.__portPrototypeBlueprint_as_string = None
        self.__derivedPortPrototype = None
        self.__derivedPortPrototype_as_string = None


    def _resolve_references(self):
        super()._resolve_references()
        portPrototypeBlueprint_node = self._node.find('{*}PORT-PROTOTYPE-BLUEPRINT-REF')
        if portPrototypeBlueprint_node is not None and portPrototypeBlueprint_node.text is not None:
            refText = ''
            refBase = portPrototypeBlueprint_node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + portPrototypeBlueprint_node.text
            self.__portPrototypeBlueprint_as_string = refText
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
