class BlueprintFormula(SwSystemconstDependentFormula):
    """
    This class express the extension of the Formula Language to provide formalized blueprint-Value resp. blueprintCondition.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'BLUEPRINT-FORMULA'
        self._node = etree.Element('BLUEPRINT-FORMULA')
        self.__ecucQueries = {} # using dict to preserve the order of elements
        self.__ecucQueries_as_string = {} # using dict to preserve the order of elements
        self.__ecucs = {} # using dict to preserve the order of elements
        self.__ecucs_as_string = {} # using dict to preserve the order of elements
        self.__verbatims = {} # using dict to preserve the order of elements

        self.__mixedtext = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        refCounter = 0
        verbatims_nodes = self._node.findall('{*}VERBATIM')
        for verbatims_node in verbatims_nodes:
            buildverbatims_node = None
            if verbatims_node.find('{*}SHORT-NAME') is None:
                buildverbatims_node = MultiLanguageVerbatim()._build(self, verbatims_node, file, '[verbatims_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildverbatims_node = MultiLanguageVerbatim()._build(self, verbatims_node, file)
            self.__verbatims[(buildverbatims_node)] = None

        self.__mixedtext = node.text
        return self

    def _resolve_references(self):
        super()._resolve_references()
        ecucQueries_nodes = self._node.findall('{*}ECUC-QUERY-REF')
        for node in ecucQueries_nodes:
            if node.text is None:
                continue
            refText = ''
            refBase = node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + node.text
            self.__ecucQueries_as_string[refText] = None
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__ecucQueries[ref_value] = None

        ecucs_nodes = self._node.findall('{*}ECUC-REF')
        for node in ecucs_nodes:
            if node.text is None:
                continue
            refText = ''
            refBase = node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + node.text
            self.__ecucs_as_string[refText] = None
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__ecucs[ref_value] = None


    def get_ecucQueries(self) -> list[EcucQuery]:
        return list(self.__ecucQueries.keys())

    def get_ecucQueries_as_string(self) -> str:
        return list(self.__ecucQueries_as_string.keys())

    def add_ecucQuerie(self, value: EcucQuery) -> None:
        """
        Adds a single value to the ecucQueries
        """
        if value is not None:
            if isinstance(value, Referrable) and any(v.name == value.name for v in self.__ecucQueries.keys()):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, EcucQuery) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of EcucQuery or its sub-classes'.format(value))
            self.__ecucQueries[value] = None
            value.referenced_by.add(self)
            XDT.mark_dirty(value, self)

    def set_ecucQueries(self, values: list[EcucQuery]) -> None:
        """
        Adds a list of ref value to the ecucQueries
        """
        for value in values:
            self.add_ecucQuerie(value)

    def remove_ecucQuerie(self, value: EcucQuery) -> None:
        """
        Removes a single value from ecucQueries
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__ecucQueries.pop(value)
            value.referenced_by.remove(self)

    def remove_ecucQueries(self, values: list[EcucQuery]) -> None:
        """
        Removes a list of value from ecucQueries
        """
        for value in values:
            self.remove_ecucQuerie(value)

    def get_ecucs(self) -> list[EcucDefinitionElement]:
        return list(self.__ecucs.keys())

    def get_ecucs_as_string(self) -> str:
        return list(self.__ecucs_as_string.keys())

    def add_ecuc(self, value: EcucDefinitionElement) -> None:
        """
        Adds a single value to the ecucs
        """
