class AttributeTailoring(DataFormatElementScope):
    """
    Tailoring of Attributes
    """
    def __init__(self):
        super().__init__()
        self.__multiplicityRestriction = None
        self.__variationRestriction = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        multiplicityRestriction_node = self._node.find('{*}MULTIPLICITY-RESTRICTION')
        if multiplicityRestriction_node is not None:
            if multiplicityRestriction_node.find('{*}SHORT-NAME') is None:
                self.__multiplicityRestriction = MultiplicityRestrictionWithSeverity()._build(self, multiplicityRestriction_node, file, '[multiplicityRestriction_@]')
            else:
                self.__multiplicityRestriction = MultiplicityRestrictionWithSeverity()._build(self, multiplicityRestriction_node, file)

        variationRestriction_node = self._node.find('{*}VARIATION-RESTRICTION')
        if variationRestriction_node is not None:
            if variationRestriction_node.find('{*}SHORT-NAME') is None:
                self.__variationRestriction = VariationRestrictionWithSeverity()._build(self, variationRestriction_node, file, '[variationRestriction_@]')
            else:
                self.__variationRestriction = VariationRestrictionWithSeverity()._build(self, variationRestriction_node, file)

        return self

    def get_multiplicityRestriction(self) -> MultiplicityRestrictionWithSeverity:
        return self.__multiplicityRestriction

    def set_multiplicityRestriction(self, value: MultiplicityRestrictionWithSeverity) -> None:
        """
        Adds a single value to the multiplicityRestriction
        """
        if value is not None:
            if isinstance(value, MultiplicityRestrictionWithSeverity) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of MultiplicityRestrictionWithSeverity or its sub-classes'.format(value))
            #if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            self.__multiplicityRestriction = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._build_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'MultiplicityRestrictionWithSeverity_@' + str(len(self.get_children()))) #updates the path
        elif self.__multiplicityRestriction is not None:
            self.__multiplicityRestriction = None
        XDT.mark_dirty(self.__multiplicityRestriction, self)

    def get_variationRestriction(self) -> VariationRestrictionWithSeverity:
        return self.__variationRestriction

