class SdgTailoring(DataFormatElementScope,RestrictionWithSeverity):
    """
    Describes if the referenced Sdg may be attached to the current class.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'SDG-TAILORING'
        self._node = etree.Element('SDG-TAILORING')
        self.__sdgClass = None
        self.__sdgClass_as_string = None


    def _resolve_references(self):
        super()._resolve_references()
        sdgClass_node = self._node.find('{*}SDG-CLASS-REF')
        if sdgClass_node is not None and sdgClass_node.text is not None:
            refText = ''
            refBase = sdgClass_node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + sdgClass_node.text
            self.__sdgClass_as_string = refText
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__sdgClass = ref_value


    def get_sdgClass(self) -> SdgClass:
        return self.__sdgClass

    def get_sdgClass_as_string(self) -> str:
        return self.__sdgClass_as_string

