class ValueList(ARObject):
    """
    This is a generic list of numerical values.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'VALUE-LIST'
        self._node = etree.Element('VALUE-LIST')
        self.__vs = None
        self.__vfs = {} # using dict to preserve the order of elements

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        vs_value = AutosarNode._get_node_text(node,'V')
        if vs_value is not None:
            self.__vs = datatype_utils.get_string_value(vs_value)

        refCounter = 0
        vfs_nodes = self._node.findall('{*}VF')
        for vfs_node in vfs_nodes:
            buildvfs_node = None
            if vfs_node.find('{*}SHORT-NAME') is None:
                buildvfs_node = NumericalValueVariationPoint()._build(self, vfs_node, file, '[vfs_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildvfs_node = NumericalValueVariationPoint()._build(self, vfs_node, file)
            self.__vfs[(buildvfs_node)] = None

        return self

    def get_vs(self) -> str:
        return self.__vs

    def set_vs(self, value: str) -> None:
        self.__vs = value
        XDT.mark_attribute_dirty('vs', self)

    def get_vfs(self) -> list[NumericalValueVariationPoint]:
        return list(self.__vfs.keys())

    def add_vf(self, value: NumericalValueVariationPoint) -> None:
        """
        Adds a single value to the vfs
        """
        if value is not None:
            if isinstance(value, Referrable) and any(v.name == value.name for v in self.__vfs.keys()):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, NumericalValueVariationPoint) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of NumericalValueVariationPoint or its sub-classes'.format(value))
            self.__vfs[value] = None
            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            value._parent = self #set parent
            value.file = self.file
            if value.name is not None:
                value._update_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'NumericalValueVariationPoint_@' + str(len(self.get_children()))) #updates the path
            XDT.mark_dirty(value, self, attributesToMakeDirty = ['shortLabel', 'sd', 'blueprintValue', 'bindingTime', 'timestamp', 'checksum'])

    def set_vfs(self, values: list[NumericalValueVariationPoint]) -> None:
        """
        Adds a list of ref value to the vfs
        """
        for value in values:
            self.add_vf(value)

    def remove_vf(self, value: NumericalValueVariationPoint) -> None:
        """
        Removes a single value from vfs
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__vfs.pop(value)
            value._parent = None #No parent
            value._update_path() #resets the path
            value._node.getparent().remove(value._node)

    def remove_vfs(self, values: list[NumericalValueVariationPoint]) -> None:
        """
        Removes a list of value from vfs
        """
        for value in values:
            self.remove_vf(value)

    def new_Vf(self, name: str=None) -> NumericalValueVariationPoint:
        """
        Creates a new NumericalValueVariationPoint under the ValueList.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        NumericalValueVariationPoint_obj = NumericalValueVariationPoint()
        if isinstance(NumericalValueVariationPoint_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        NumericalValueVariationPoint_obj.name = name if isinstance(NumericalValueVariationPoint_obj, Referrable) else None
        self.add_vf(NumericalValueVariationPoint_obj)
        if isinstance(NumericalValueVariationPoint_obj, Referrable):
            NumericalValueVariationPoint_obj.set_shortName(name)
        return NumericalValueVariationPoint_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        children.extend(self.__vfs)
        return children



    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['Vs'] = self.__vs
        return property_values

    def _update_path(self):
        """
        Updates the path of the ValueList and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()


    def _save_contents(self):
        """
        Saves the content of ValueList node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_ARObject()
        if len(self.__vfs) > 0:
            for value in self.__vfs:
                if XDT.is_dirty(value) and value.file == self.file:
                    value._node.tag = 'VF'
			    
                    value._save_contents()
                    AutosarNode._insert_element_after_given_tags(self._node, value._node, create_after_nodes = self._insert_after_tags + ['VF'] + ['T', 'S'])

        if XDT.is_attribute_dirty('vs', self):
            if self.__vs is None:
                AutosarNode._remove_xml_node_if_exists(self._node, 'V')
            else:
                vs_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'V', create_after_nodes = ['VF', 'T', 'S'] + self._insert_after_tags)
                vs_xml_node.text = str(self.__vs)


