class RuleBasedValueSpecification(ARObject):
    """
    This meta-class is used to support a rule-based initialization approach for data types with an array-nature (ApplicationArrayDataType and ImplementationDataType of category ARRAY) or a compound ApplicationPrimitiveDataType (which also boils down to an array-nature).
    """
    def __init__(self):
        super().__init__()
        self.tag = 'RULE-BASED-VALUE-SPECIFICATION'
        self._node = etree.Element('RULE-BASED-VALUE-SPECIFICATION')
        self.__rule = None
        self.__maxSizeToFill = None
        self.__arguments = {} # using dict to preserve the order of elements

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        rule_value = AutosarNode._get_node_text(node,'RULE')
        if rule_value is not None:
            self.__rule = datatype_utils.get_string_value(rule_value)

        maxSizeToFill_value = AutosarNode._get_node_text(node,'MAX-SIZE-TO-FILL')
        if maxSizeToFill_value is not None:
            self.__maxSizeToFill = datatype_utils.get_int_value(maxSizeToFill_value)

        refCounter = 0
        arguments_nodes = self._node.findall('{*}ARGUMENTSS/*')
        for arguments_node in arguments_nodes:
            buildarguments_node = None
            if arguments_node.find('{*}SHORT-NAME') is None:
                buildarguments_node = RuleArguments()._build(self, arguments_node, file, '[arguments_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildarguments_node = RuleArguments()._build(self, arguments_node, file)
            self.__arguments[(buildarguments_node)] = None

        return self

    def get_rule(self) -> str:
        return self.__rule

    def set_rule(self, value: str) -> None:
        self.__rule = value
        XDT.mark_attribute_dirty('rule', self)

    def get_maxSizeToFill(self) -> int:
        return self.__maxSizeToFill

    def set_maxSizeToFill(self, value: int) -> None:
        self.__maxSizeToFill = value
        XDT.mark_attribute_dirty('maxSizeToFill', self)

    def get_arguments(self) -> list[RuleArguments]:
        return list(self.__arguments.keys())

    def add_argument(self, value: RuleArguments) -> None:
        """
        Adds a single value to the arguments
        """
        if value is not None:
            if isinstance(value, Referrable) and any(v.name == value.name for v in self.__arguments.keys()):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, RuleArguments) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of RuleArguments or its sub-classes'.format(value))
            self.__arguments[value] = None
            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            value._parent = self #set parent
            value.file = self.file
            if value.name is not None:
                value._update_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'RuleArguments_@' + str(len(self.get_children()))) #updates the path
            XDT.mark_dirty(value, self, attributesToMakeDirty = ['timestamp', 'checksum'])

    def set_arguments(self, values: list[RuleArguments]) -> None:
        """
        Adds a list of ref value to the arguments
        """
        for value in values:
            self.add_argument(value)

    def remove_argument(self, value: RuleArguments) -> None:
        """
        Removes a single value from arguments
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__arguments.pop(value)
            value._parent = None #No parent
            value._update_path() #resets the path
            value._node.getparent().remove(value._node)

    def remove_arguments(self, values: list[RuleArguments]) -> None:
        """
        Removes a list of value from arguments
        """
        for value in values:
            self.remove_argument(value)

    def new_Argument(self, name: str=None) -> RuleArguments:
        """
        Creates a new RuleArguments under the RuleBasedValueSpecification.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        RuleArguments_obj = RuleArguments()
        if isinstance(RuleArguments_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        RuleArguments_obj.name = name if isinstance(RuleArguments_obj, Referrable) else None
        self.add_argument(RuleArguments_obj)
        if isinstance(RuleArguments_obj, Referrable):
            RuleArguments_obj.set_shortName(name)
        return RuleArguments_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        children.extend(self.__arguments)
        return children



    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['Rule'] = self.__rule
        property_values['MaxSizeToFill'] = self.__maxSizeToFill
        return property_values

