class ConstantReference(ValueSpecification):
    """
    Instead of defining this value inline, a constant is referenced.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'CONSTANT-REFERENCE'
        self._node = etree.Element('CONSTANT-REFERENCE')
        self.__constant = None
        self.__constant_as_string = None


    def _resolve_references(self):
        super()._resolve_references()
        constant_node = self._node.find('{*}CONSTANT-REF')
        if constant_node is not None and constant_node.text is not None:
            refText = ''
            refBase = constant_node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + constant_node.text
            self.__constant_as_string = refText
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__constant = ref_value


    def get_constant(self) -> ConstantSpecification:
        return self.__constant

    def get_constant_as_string(self) -> str:
        return self.__constant_as_string

    def set_constant(self, value: ConstantSpecification) -> None:
        """
        Adds a single value to the constant
        """
        if value is not None:
            if isinstance(value, ConstantSpecification) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of ConstantSpecification or its sub-classes'.format(value))
            if self.__constant is not None:
                self.__constant.referenced_by.remove(self)
            self.__constant = value
            value.referenced_by.add(self)
        elif self.__constant is not None:
            self.__constant.referenced_by.remove(self)
            self.__constant = None
        XDT.mark_dirty(self.__constant, self)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['Constant'] = self.__constant
        return property_values

    def _update_path(self):
        """
        Updates the path of the ConstantReference and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()


    def _save_contents(self):
        """
        Saves the content of ConstantReference node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_ValueSpecification()
        if self.__constant is None:
            AutosarNode._remove_xml_node_if_exists(self._node, 'CONSTANT-REF')
        elif XDT.is_dirty(self.__constant):
            constant_value = AutosarNode._add_or_get_xml_node(self._node, 'CONSTANT-REF', dest = self.__constant, create_after_nodes = self._insert_after_tags + ['VARIATION-POINT', 'SHORT-LABEL', 'T', 'S'] + self._insert_after_tags)
            constant_value.text = self.__constant.autosar_path
            constant_value.attrib['DEST'] = self.__constant.tag


