class McDataInstance(Identifiable):
    """
    Describes the specific properties of one data instance in order to support measurement and/or calibration of this data instance., , The most important attributes are:, * Its shortName is copied from the ECU Flat map (if applicable) and will be used as identifier and for display by the MC system., * The category is copied from the corresponding data type (ApplicationDataType if defined, otherwise ImplementationDataType) as far as applicable., * The symbol is the one used in the programming language. It will be used to find out the actual memory address by the final generation tool with the help of linker generated information., , It is assumed that in the M1 model this part and all the aggregated and referred elements (with the exception of the Flat Map and the references from ImplementationElementInParameterInstanceRef and McAccessDetails) are completely generated from "upstream" information. This means, that even if an element like e.g. a CompuMethod is only used via reference here, it will be copied into the M1 artifact which holds the complete McSupportData for a given Implementation.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'MC-DATA-INSTANCE'
        self._node = etree.Element('MC-DATA-INSTANCE')
        self.__arraySize = None
        self.__displayIdentifier = None
        self.__role = None
        self.__symbol = None
        self.__flatMapEntry = None
        self.__flatMapEntry_as_string = None
        self.__instanceInMemory = None
        self.__mcDataAccessDetails = None
        self.__mcDataAssignments = {} # using dict to preserve the order of elements
        self.__resultingProperties = None
        self.__resultingRptSwPrototypingAccess = None
        self.__rptImplPolicy = None
        self.__subElements = {} # using dict to preserve the order of elements
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        arraySize_value = AutosarNode._get_node_text(node,'ARRAY-SIZE')
        if arraySize_value is not None:
            self.__arraySize = datatype_utils.get_int_value(arraySize_value)

        displayIdentifier_value = AutosarNode._get_node_text(node,'DISPLAY-IDENTIFIER')
        if displayIdentifier_value is not None:
            self.__displayIdentifier = datatype_utils.get_string_value(displayIdentifier_value)

        role_value = AutosarNode._get_node_text(node,'ROLE')
        if role_value is not None:
            self.__role = datatype_utils.get_string_value(role_value)

        symbol_value = AutosarNode._get_node_text(node,'SYMBOL')
        if symbol_value is not None:
            self.__symbol = datatype_utils.get_string_value(symbol_value)

        refCounter = 0
        instanceInMemory_node = self._node.find('{*}INSTANCE-IN-MEMORY')
        if instanceInMemory_node is not None:
            if instanceInMemory_node.find('{*}SHORT-NAME') is None:
                self.__instanceInMemory = ImplementationElementInParameterInstanceRef()._build(self, instanceInMemory_node, file, '[instanceInMemory_@]')
            else:
                self.__instanceInMemory = ImplementationElementInParameterInstanceRef()._build(self, instanceInMemory_node, file)

        mcDataAccessDetails_node = self._node.find('{*}MC-DATA-ACCESS-DETAILS')
        if mcDataAccessDetails_node is not None:
            if mcDataAccessDetails_node.find('{*}SHORT-NAME') is None:
                self.__mcDataAccessDetails = McDataAccessDetails()._build(self, mcDataAccessDetails_node, file, '[mcDataAccessDetails_@]')
            else:
                self.__mcDataAccessDetails = McDataAccessDetails()._build(self, mcDataAccessDetails_node, file)

        mcDataAssignments_nodes = self._node.findall('{*}MC-DATA-ASSIGNMENTS/*')
        for mcDataAssignments_node in mcDataAssignments_nodes:
            buildmcDataAssignments_node = None
            if mcDataAssignments_node.find('{*}SHORT-NAME') is None:
                buildmcDataAssignments_node = RoleBasedMcDataAssignment()._build(self, mcDataAssignments_node, file, '[mcDataAssignments_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildmcDataAssignments_node = RoleBasedMcDataAssignment()._build(self, mcDataAssignments_node, file)
            self.__mcDataAssignments[(buildmcDataAssignments_node)] = None

        resultingProperties_node = self._node.find('{*}RESULTING-PROPERTIES')
        if resultingProperties_node is not None:
            if resultingProperties_node.find('{*}SHORT-NAME') is None:
                self.__resultingProperties = SwDataDefProps()._build(self, resultingProperties_node, file, '[resultingProperties_@]')
            else:
                self.__resultingProperties = SwDataDefProps()._build(self, resultingProperties_node, file)

        resultingRptSwPrototypingAccess_node = self._node.find('{*}RESULTING-RPT-SW-PROTOTYPING-ACCESS')
        if resultingRptSwPrototypingAccess_node is not None:
            if resultingRptSwPrototypingAccess_node.find('{*}SHORT-NAME') is None:
                self.__resultingRptSwPrototypingAccess = RptSwPrototypingAccess()._build(self, resultingRptSwPrototypingAccess_node, file, '[resultingRptSwPrototypingAccess_@]')
            else:
                self.__resultingRptSwPrototypingAccess = RptSwPrototypingAccess()._build(self, resultingRptSwPrototypingAccess_node, file)

        rptImplPolicy_node = self._node.find('{*}RPT-IMPL-POLICY')
        if rptImplPolicy_node is not None:
            if rptImplPolicy_node.find('{*}SHORT-NAME') is None:
                self.__rptImplPolicy = RptImplPolicy()._build(self, rptImplPolicy_node, file, '[rptImplPolicy_@]')
            else:
                self.__rptImplPolicy = RptImplPolicy()._build(self, rptImplPolicy_node, file)

        subElements_nodes = self._node.findall('{*}SUB-ELEMENTS/*')
        for subElements_node in subElements_nodes:
            buildsubElements_node = None
            if subElements_node.find('{*}SHORT-NAME') is None:
                buildsubElements_node = McDataInstance()._build(self, subElements_node, file, '[subElements_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildsubElements_node = McDataInstance()._build(self, subElements_node, file)
            self.__subElements[(buildsubElements_node)] = None

        variationPoint_node = self._node.find('{*}VARIATION-POINT')
        if variationPoint_node is not None:
            if variationPoint_node.find('{*}SHORT-NAME') is None:
                self.__variationPoint = VariationPoint()._build(self, variationPoint_node, file, '[variationPoint_@]')
            else:
                self.__variationPoint = VariationPoint()._build(self, variationPoint_node, file)

        return self

    def _resolve_references(self):
        super()._resolve_references()
        flatMapEntry_node = self._node.find('{*}FLAT-MAP-ENTRY-REF')
        if flatMapEntry_node is not None and flatMapEntry_node.text is not None:
            refText = ''
            refBase = flatMapEntry_node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + flatMapEntry_node.text
            self.__flatMapEntry_as_string = refText
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__flatMapEntry = ref_value


