class MemorySection(Identifiable):
    """
    Provides a description of an abstract memory section used in the Implementation for code or data. It shall be declared by the Implementation Description of the module or component, which actually allocates the memory in its code. This means in case of data prototypes which are allocated by the RTE, that the generated Implementation Description of the RTE shall contain the corresponding MemorySections., , The attribute "symbol" (if symbol is missing: "shortName") defines the module or component specific section name used in the code. For details see the document "Specification of Memory Mapping"., Typically the section name is build according the pattern:, , <SwAddrMethod shortName>[_<further specialization nominator>][_<alignment>] , where, * '''[<SwAddrMethod shortName>]''' is the shortName of the referenced SwAddrMethod, * '''[_<further specialization nominator>]''' is an optional infix to indicate the specialization in the case that several MemorySections for different purpose of the same Implementation Description referring to the same or equally named SwAddrMethods. , * '''[_<alignment>]''' is the alignment attributes value and is only applicable in the case that the memoryAllocationKeywordPolicy value of the referenced SwAddrMethod is set to addrMethodShortNameAndAlignment , , MemorySection used to Implement the code of RunnableEntitys and BswSchedulableEntitys shall have a symbol (if missing: shortName) identical to the referred SwAddrMethod to conform to the generated RTE header files.   , , In addition to the section name described above, a prefix is used in the corresponding macro code in order to define a name space. This prefix is by default given by the shortName of the BswModuleDescription resp. the SwComponentType. It can be superseded by  the prefix attribute.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'MEMORY-SECTION'
        self._node = etree.Element('MEMORY-SECTION')
        self.__alignment = None
        self.__memClassSymbol = None
        self.__options = None
        self.__size = None
        self.__symbol = None
        self.__executableEntities = {} # using dict to preserve the order of elements
        self.__executableEntities_as_string = {} # using dict to preserve the order of elements
        self.__prefix = None
        self.__prefix_as_string = None
        self.__swAddrmethod = None
        self.__swAddrmethod_as_string = None
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        alignment_value = AutosarNode._get_node_text(node,'ALIGNMENT')
        if alignment_value is not None:
            self.__alignment = datatype_utils.get_string_value(alignment_value)

        memClassSymbol_value = AutosarNode._get_node_text(node,'MEM-CLASS-SYMBOL')
        if memClassSymbol_value is not None:
            self.__memClassSymbol = datatype_utils.get_string_value(memClassSymbol_value)

        options_value = AutosarNode._get_node_text(node,'OPTION')
        if options_value is not None:
            self.__options = datatype_utils.get_string_value(options_value)

        size_value = AutosarNode._get_node_text(node,'SIZE')
        if size_value is not None:
            self.__size = datatype_utils.get_int_value(size_value)

        symbol_value = AutosarNode._get_node_text(node,'SYMBOL')
        if symbol_value is not None:
            self.__symbol = datatype_utils.get_string_value(symbol_value)

        variationPoint_node = self._node.find('{*}VARIATION-POINT')
        if variationPoint_node is not None:
            if variationPoint_node.find('{*}SHORT-NAME') is None:
                self.__variationPoint = VariationPoint()._build(self, variationPoint_node, file, '[variationPoint_@]')
            else:
                self.__variationPoint = VariationPoint()._build(self, variationPoint_node, file)

        return self

    def _resolve_references(self):
        super()._resolve_references()
        executableEntities_nodes = self._node.findall('{*}EXECUTABLE-ENTITY-REFS/*')
        for node in executableEntities_nodes:
            if node.text is None:
                continue
            refText = ''
            refBase = node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + node.text
            self.__executableEntities_as_string[refText] = None
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__executableEntities[ref_value] = None

        prefix_node = self._node.find('{*}PREFIX-REF')
        if prefix_node is not None and prefix_node.text is not None:
            refText = ''
            refBase = prefix_node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + prefix_node.text
            self.__prefix_as_string = refText
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__prefix = ref_value

        swAddrmethod_node = self._node.find('{*}SW-ADDRMETHOD-REF')
        if swAddrmethod_node is not None and swAddrmethod_node.text is not None:
            refText = ''
            refBase = swAddrmethod_node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + swAddrmethod_node.text
            self.__swAddrmethod_as_string = refText
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__swAddrmethod = ref_value


    def get_alignment(self) -> str:
        return self.__alignment

    def set_alignment(self, value: str) -> None:
        self.__alignment = value
        XDT.mark_attribute_dirty('alignment', self)

    def get_memClassSymbol(self) -> str:
        return self.__memClassSymbol

    def set_memClassSymbol(self, value: str) -> None:
        self.__memClassSymbol = value
        XDT.mark_attribute_dirty('memClassSymbol', self)

    def get_options(self) -> str:
        return self.__options

    def set_options(self, value: str) -> None:
        self.__options = value
        XDT.mark_attribute_dirty('options', self)

    def get_size(self) -> int:
        return self.__size

    def set_size(self, value: int) -> None:
        self.__size = value
        XDT.mark_attribute_dirty('size', self)

    def get_symbol(self) -> str:
        return self.__symbol

    def set_symbol(self, value: str) -> None:
        self.__symbol = value
        XDT.mark_attribute_dirty('symbol', self)

    def get_executableEntities(self) -> list[ExecutableEntity]:
        return list(self.__executableEntities.keys())

    def get_executableEntities_as_string(self) -> str:
        return list(self.__executableEntities_as_string.keys())

    def add_executableEntitie(self, value: ExecutableEntity) -> None:
        """
        Adds a single value to the executableEntities
        """
        if value is not None:
            if isinstance(value, Referrable) and any(v.name == value.name for v in self.__executableEntities.keys()):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, ExecutableEntity) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of ExecutableEntity or its sub-classes'.format(value))
            self.__executableEntities[value] = None
            value.referenced_by.add(self)
            XDT.mark_dirty(value, self)

    def set_executableEntities(self, values: list[ExecutableEntity]) -> None:
        """
        Adds a list of ref value to the executableEntities
        """
        for value in values:
            self.add_executableEntitie(value)

    def remove_executableEntitie(self, value: ExecutableEntity) -> None:
        """
        Removes a single value from executableEntities
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__executableEntities.pop(value)
            value.referenced_by.remove(self)

    def remove_executableEntities(self, values: list[ExecutableEntity]) -> None:
        """
        Removes a list of value from executableEntities
        """
        for value in values:
            self.remove_executableEntitie(value)

    def get_prefix(self) -> SectionNamePrefix:
        return self.__prefix

    def get_prefix_as_string(self) -> str:
        return self.__prefix_as_string

    def set_prefix(self, value: SectionNamePrefix) -> None:
        """
        Adds a single value to the prefix
        """
        if value is not None:
            if isinstance(value, SectionNamePrefix) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of SectionNamePrefix or its sub-classes'.format(value))
            if self.__prefix is not None:
                self.__prefix.referenced_by.remove(self)
            self.__prefix = value
            value.referenced_by.add(self)
        elif self.__prefix is not None:
            self.__prefix.referenced_by.remove(self)
            self.__prefix = None
        XDT.mark_dirty(self.__prefix, self)

    def get_swAddrmethod(self) -> SwAddrMethod:
        return self.__swAddrmethod

    def get_swAddrmethod_as_string(self) -> str:
        return self.__swAddrmethod_as_string

    def set_swAddrmethod(self, value: SwAddrMethod) -> None:
        """
        Adds a single value to the swAddrmethod
        """
        if value is not None:
            if isinstance(value, SwAddrMethod) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of SwAddrMethod or its sub-classes'.format(value))
            if self.__swAddrmethod is not None:
                self.__swAddrmethod.referenced_by.remove(self)
            self.__swAddrmethod = value
            value.referenced_by.add(self)
        elif self.__swAddrmethod is not None:
            self.__swAddrmethod.referenced_by.remove(self)
            self.__swAddrmethod = None
        XDT.mark_dirty(self.__swAddrmethod, self)

    def get_variationPoint(self) -> VariationPoint:
        return self.__variationPoint

    def set_variationPoint(self, value: VariationPoint) -> None:
        """
        Adds a single value to the variationPoint
        """
        if value is not None:
            if isinstance(value, VariationPoint) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of VariationPoint or its sub-classes'.format(value))
            #if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            self.__variationPoint = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._build_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'VariationPoint_@' + str(len(self.get_children()))) #updates the path
        elif self.__variationPoint is not None:
            self.__variationPoint = None
        XDT.mark_dirty(self.__variationPoint, self)

    def new_VariationPoint(self, name: str=None) -> VariationPoint:
        """
        Creates a new VariationPoint under the MemorySection.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        VariationPoint_obj = VariationPoint()
        if isinstance(VariationPoint_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        VariationPoint_obj.name = name if isinstance(VariationPoint_obj, Referrable) else None
        self.set_variationPoint(VariationPoint_obj)
        if isinstance(VariationPoint_obj, Referrable):
            VariationPoint_obj.set_shortName(name)
        return VariationPoint_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        if self.__variationPoint is not None:
            children.append(self.__variationPoint)
        return children



    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['Alignment'] = self.__alignment
        property_values['MemClassSymbol'] = self.__memClassSymbol
        property_values['Options'] = self.__options
        property_values['Size'] = self.__size
        property_values['Symbol'] = self.__symbol
        property_values['ExecutableEntities'] = self.__executableEntities
        property_values['Prefix'] = self.__prefix
        property_values['SwAddrmethod'] = self.__swAddrmethod
        return property_values

    def _update_path(self):
        """
        Updates the path of the MemorySection and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

    def is_atp_splitable(self) -> bool:
        return True

    def _save_contents(self):
        """
        Saves the content of MemorySection node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_Identifiable()
        if XDT.is_attribute_dirty('alignment', self):
            if self.__alignment is None:
                AutosarNode._remove_xml_node_if_exists(self._node, 'ALIGNMENT')
            else:
                alignment_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'ALIGNMENT', create_after_nodes = ['UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'] + self._insert_after_tags)
                alignment_xml_node.text = str(self.__alignment)

        if len(self.__executableEntities) > 0:
            AutosarNode._remove_xml_node_if_exists(self._node, 'EXECUTABLE-ENTITY-REFS')
