class SectionNamePrefix(ImplementationProps):
    """
    A prefix to be used for generated code artifacts defining a memory section name in the source code of the using module or SWC.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'SECTION-NAME-PREFIX'
        self._node = etree.Element('SECTION-NAME-PREFIX')
