class PhysConstrs(ARObject):
    """
    This meta-class represents the ability to express physical constraints. Therefore it has (in opposite to InternalConstrs) a reference to a Unit.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'PHYS-CONSTRS'
        self._node = etree.Element('PHYS-CONSTRS')
        self.__maxGradient = None
        self.__maxDiff = None
        self.__monotony = None
        self.__lowerLimit = None
        self.__upperLimit = None
        self.__scaleConstrs = {} # using dict to preserve the order of elements
        self.__unit = None
        self.__unit_as_string = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        maxGradient_value = AutosarNode._get_node_text(node,'MAX-GRADIENT')
        if maxGradient_value is not None:
            self.__maxGradient = datatype_utils.get_string_value(maxGradient_value)

        maxDiff_value = AutosarNode._get_node_text(node,'MAX-DIFF')
        if maxDiff_value is not None:
            self.__maxDiff = datatype_utils.get_string_value(maxDiff_value)

        monotony_value = AutosarNode._get_node_text(node,'MONOTONY')
        if monotony_value is not None:
            self.__monotony = MonotonyEnum.get(monotony_value)

        refCounter = 0
        lowerLimit_node = self._node.find('{*}LOWER-LIMIT')
        if lowerLimit_node is not None:
            if lowerLimit_node.find('{*}SHORT-NAME') is None:
                self.__lowerLimit = LimitValueVariationPoint()._build(self, lowerLimit_node, file, '[lowerLimit_@]')
            else:
                self.__lowerLimit = LimitValueVariationPoint()._build(self, lowerLimit_node, file)

        upperLimit_node = self._node.find('{*}UPPER-LIMIT')
        if upperLimit_node is not None:
            if upperLimit_node.find('{*}SHORT-NAME') is None:
                self.__upperLimit = LimitValueVariationPoint()._build(self, upperLimit_node, file, '[upperLimit_@]')
            else:
                self.__upperLimit = LimitValueVariationPoint()._build(self, upperLimit_node, file)

        scaleConstrs_nodes = self._node.findall('{*}SCALE-CONSTRS/*')
        for scaleConstrs_node in scaleConstrs_nodes:
            buildscaleConstrs_node = None
            if scaleConstrs_node.find('{*}SHORT-NAME') is None:
                buildscaleConstrs_node = ScaleConstr()._build(self, scaleConstrs_node, file, '[scaleConstrs_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildscaleConstrs_node = ScaleConstr()._build(self, scaleConstrs_node, file)
            self.__scaleConstrs[(buildscaleConstrs_node)] = None

        return self

    def _resolve_references(self):
        super()._resolve_references()
        unit_node = self._node.find('{*}UNIT-REF')
        if unit_node is not None and unit_node.text is not None:
            refText = ''
            refBase = unit_node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + unit_node.text
            self.__unit_as_string = refText
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__unit = ref_value


