class SwValues(ARObject):
    """
    This meta-class represents a list of values. These values can either be the input values of a curve (abscissa values) or the associated values (ordinate values). , , In case of multidimensional structures, the values are ordered such that the lowest index runs the fastest. In particular for maps and cuboids etc. the resulting long value list can be subsectioned using ValueGroup. But the processing needs to be done as if vg is not there., , Note that numerical values and textual values should not be mixed.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'SW-VALUES'
        self._node = etree.Element('SW-VALUES')
        self.__vts = None
        self.__vs = None
        self.__vtfs = {} # using dict to preserve the order of elements
        self.__vfs = {} # using dict to preserve the order of elements
        self.__vgs = {} # using dict to preserve the order of elements

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        vts_value = AutosarNode._get_node_text(node,'VT')
        if vts_value is not None:
            self.__vts = datatype_utils.get_string_value(vts_value)

        vs_value = AutosarNode._get_node_text(node,'V')
        if vs_value is not None:
            self.__vs = datatype_utils.get_string_value(vs_value)

        refCounter = 0
        vtfs_nodes = self._node.findall('{*}VTF')
        for vtfs_node in vtfs_nodes:
            buildvtfs_node = None
            if vtfs_node.find('{*}SHORT-NAME') is None:
                buildvtfs_node = NumericalOrText()._build(self, vtfs_node, file, '[vtfs_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildvtfs_node = NumericalOrText()._build(self, vtfs_node, file)
            self.__vtfs[(buildvtfs_node)] = None

        vfs_nodes = self._node.findall('{*}VF')
        for vfs_node in vfs_nodes:
            buildvfs_node = None
            if vfs_node.find('{*}SHORT-NAME') is None:
                buildvfs_node = NumericalValueVariationPoint()._build(self, vfs_node, file, '[vfs_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildvfs_node = NumericalValueVariationPoint()._build(self, vfs_node, file)
            self.__vfs[(buildvfs_node)] = None

        vgs_nodes = self._node.findall('{*}VG')
        for vgs_node in vgs_nodes:
            buildvgs_node = None
            if vgs_node.find('{*}SHORT-NAME') is None:
                buildvgs_node = ValueGroup()._build(self, vgs_node, file, '[vgs_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildvgs_node = ValueGroup()._build(self, vgs_node, file)
            self.__vgs[(buildvgs_node)] = None

        return self

    def get_vts(self) -> str:
        return self.__vts

