class TDEventVfb(TimingDescriptionEvent):
    """
    This is the abstract parent class to describe timing events at Virtual Functional Bus (VFB) level.
    """
    def __init__(self):
        super().__init__()
        self.__component = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        component_node = self._node.find('{*}COMPONENT-IREF')
        if component_node is not None:
            if component_node.find('{*}SHORT-NAME') is None:
                self.__component = ComponentInCompositionInstanceRef()._build(self, component_node, file, '[component_@]')
            else:
                self.__component = ComponentInCompositionInstanceRef()._build(self, component_node, file)

        return self

    def get_component(self) -> ComponentInCompositionInstanceRef:
        return self.__component

    def set_component(self, value: ComponentInCompositionInstanceRef) -> None:
        """
        Adds a single value to the component
        """
        if value is not None:
            if isinstance(value, ComponentInCompositionInstanceRef) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of ComponentInCompositionInstanceRef or its sub-classes'.format(value))
            #if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            self.__component = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._build_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'ComponentInCompositionInstanceRef_@' + str(len(self.get_children()))) #updates the path
        elif self.__component is not None:
            self.__component = None
        XDT.mark_dirty(self.__component, self)

    def new_Component(self, name: str=None) -> ComponentInCompositionInstanceRef:
        """
        Creates a new ComponentInCompositionInstanceRef under the TDEventVfb.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        ComponentInCompositionInstanceRef_obj = ComponentInCompositionInstanceRef()
        if isinstance(ComponentInCompositionInstanceRef_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        ComponentInCompositionInstanceRef_obj.name = name if isinstance(ComponentInCompositionInstanceRef_obj, Referrable) else None
        self.set_component(ComponentInCompositionInstanceRef_obj)
        if isinstance(ComponentInCompositionInstanceRef_obj, Referrable):
            ComponentInCompositionInstanceRef_obj.set_shortName(name)
        return ComponentInCompositionInstanceRef_obj

