class AtomicSwComponentType(SwComponentType):
    """
    An atomic software component is atomic in the sense that it cannot be further decomposed and distributed across multiple ECUs.
    """
    def __init__(self):
        super().__init__()
        self.__internalBehaviors = {} # using dict to preserve the order of elements
        self.__symbolProps = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        refCounter = 0
        internalBehaviors_nodes = self._node.findall('{*}INTERNAL-BEHAVIORS/*')
        for internalBehaviors_node in internalBehaviors_nodes:
            buildinternalBehaviors_node = None
            if internalBehaviors_node.find('{*}SHORT-NAME') is None:
                buildinternalBehaviors_node = SwcInternalBehavior()._build(self, internalBehaviors_node, file, '[internalBehaviors_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildinternalBehaviors_node = SwcInternalBehavior()._build(self, internalBehaviors_node, file)
            self.__internalBehaviors[(buildinternalBehaviors_node)] = None

        symbolProps_node = self._node.find('{*}SYMBOL-PROPS')
        if symbolProps_node is not None:
            if symbolProps_node.find('{*}SHORT-NAME') is None:
                self.__symbolProps = SymbolProps()._build(self, symbolProps_node, file, '[symbolProps_@]')
            else:
                self.__symbolProps = SymbolProps()._build(self, symbolProps_node, file)

        return self

    def get_internalBehaviors(self) -> list[SwcInternalBehavior]:
        return list(self.__internalBehaviors.keys())

    def add_internalBehavior(self, value: SwcInternalBehavior) -> None:
        """
        Adds a single value to the internalBehaviors
        """
        if value is not None:
            if isinstance(value, Referrable) and any(v.name == value.name for v in self.__internalBehaviors.keys()):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, SwcInternalBehavior) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of SwcInternalBehavior or its sub-classes'.format(value))
            self.__internalBehaviors[value] = None
            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            value._parent = self #set parent
            value.file = self.file
            if value.name is not None:
                value._update_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'SwcInternalBehavior_@' + str(len(self.get_children()))) #updates the path
            XDT.mark_dirty(value, self, attributesToMakeDirty = ['uuid', 'category', 'shortName', 'timestamp', 'checksum'])

    def set_internalBehaviors(self, values: list[SwcInternalBehavior]) -> None:
        """
        Adds a list of ref value to the internalBehaviors
        """
        for value in values:
            self.add_internalBehavior(value)

    def remove_internalBehavior(self, value: SwcInternalBehavior) -> None:
        """
        Removes a single value from internalBehaviors
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__internalBehaviors.pop(value)
            value._parent = None #No parent
            value._update_path() #resets the path
            value._node.getparent().remove(value._node)

    def remove_internalBehaviors(self, values: list[SwcInternalBehavior]) -> None:
        """
        Removes a list of value from internalBehaviors
        """
        for value in values:
            self.remove_internalBehavior(value)

    def get_symbolProps(self) -> SymbolProps:
        return self.__symbolProps

    def set_symbolProps(self, value: SymbolProps) -> None:
        """
        Adds a single value to the symbolProps
        """
        if value is not None:
            if isinstance(value, SymbolProps) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of SymbolProps or its sub-classes'.format(value))
            #if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            self.__symbolProps = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._build_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'SymbolProps_@' + str(len(self.get_children()))) #updates the path
        elif self.__symbolProps is not None:
            self.__symbolProps = None
        XDT.mark_dirty(self.__symbolProps, self)

    def new_SymbolProps(self, name: str=None) -> SymbolProps:
        """
        Creates a new SymbolProps under the AtomicSwComponentType.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        SymbolProps_obj = SymbolProps()
        if isinstance(SymbolProps_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        SymbolProps_obj.name = name if isinstance(SymbolProps_obj, Referrable) else None
        self.set_symbolProps(SymbolProps_obj)
        if isinstance(SymbolProps_obj, Referrable):
            SymbolProps_obj.set_shortName(name)
        return SymbolProps_obj

