class CompuNominatorDenominator(ARObject):
    """
    This class represents the ability to express a polynomial either as Nominator or as Denominator.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'COMPU-NOMINATOR-DENOMINATOR'
        self._node = etree.Element('COMPU-NOMINATOR-DENOMINATOR')
        self.__vs = {} # using dict to preserve the order of elements

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        refCounter = 0
        vs_nodes = self._node.findall('{*}V')
        for vs_node in vs_nodes:
            buildvs_node = None
            if vs_node.find('{*}SHORT-NAME') is None:
                buildvs_node = NumericalValueVariationPoint()._build(self, vs_node, file, '[vs_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildvs_node = NumericalValueVariationPoint()._build(self, vs_node, file)
            self.__vs[(buildvs_node)] = None

        return self

    def get_vs(self) -> list[NumericalValueVariationPoint]:
        return list(self.__vs.keys())

    def add_v(self, value: NumericalValueVariationPoint) -> None:
        """
        Adds a single value to the vs
        """
        if value is not None:
            if isinstance(value, Referrable) and any(v.name == value.name for v in self.__vs.keys()):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, NumericalValueVariationPoint) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of NumericalValueVariationPoint or its sub-classes'.format(value))
            self.__vs[value] = None
            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            value._parent = self #set parent
            value.file = self.file
            if value.name is not None:
                value._update_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'NumericalValueVariationPoint_@' + str(len(self.get_children()))) #updates the path
            XDT.mark_dirty(value, self, attributesToMakeDirty = ['shortLabel', 'sd', 'blueprintValue', 'bindingTime', 'timestamp', 'checksum'])

    def set_vs(self, values: list[NumericalValueVariationPoint]) -> None:
        """
        Adds a list of ref value to the vs
        """
        for value in values:
            self.add_v(value)

    def remove_v(self, value: NumericalValueVariationPoint) -> None:
        """
        Removes a single value from vs
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__vs.pop(value)
            value._parent = None #No parent
            value._update_path() #resets the path
            value._node.getparent().remove(value._node)

    def remove_vs(self, values: list[NumericalValueVariationPoint]) -> None:
        """
        Removes a list of value from vs
        """
        for value in values:
            self.remove_v(value)

    def new_V(self, name: str=None) -> NumericalValueVariationPoint:
        """
        Creates a new NumericalValueVariationPoint under the CompuNominatorDenominator.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        NumericalValueVariationPoint_obj = NumericalValueVariationPoint()
        if isinstance(NumericalValueVariationPoint_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        NumericalValueVariationPoint_obj.name = name if isinstance(NumericalValueVariationPoint_obj, Referrable) else None
        self.add_v(NumericalValueVariationPoint_obj)
        if isinstance(NumericalValueVariationPoint_obj, Referrable):
            NumericalValueVariationPoint_obj.set_shortName(name)
        return NumericalValueVariationPoint_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        children.extend(self.__vs)
        return children



    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        return property_values

    def _update_path(self):
        """
        Updates the path of the CompuNominatorDenominator and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()


    def _save_contents(self):
        """
        Saves the content of CompuNominatorDenominator node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_ARObject()
        if len(self.__vs) > 0:
            for value in self.__vs:
                if XDT.is_dirty(value) and value.file == self.file:
                    value._node.tag = 'V'
			    
                    value._save_contents()
                    AutosarNode._insert_element_after_given_tags(self._node, value._node, create_after_nodes = self._insert_after_tags + ['V'] + ['T', 'S'])


