class Unit(ARElement):
    """
    This is a physical measurement unit. All units that might be defined should stem from SI units. In order to convert one unit into another factor and offset are defined. , , For the calculation from SI-unit to the defined unit the factor (factorSiToUnit ) and the offset, (offsetSiToUnit ) are applied as follows:, ,      x  [{unit}]  :=  y * [{siUnit}] * factorSiToUnit [[unit]/{siUnit}] + offsetSiToUnit [{unit}]  , , For the calculation from a unit to SI-unit the reciprocal of the factor (factorSiToUnit ) and the negation of the offset (offsetSiToUnit ) are applied. ,  ,     y {siUnit} := (x*{unit} - offsetSiToUnit [{unit}]) / (factorSiToUnit [[unit]/{siUnit}]
    """
    def __init__(self):
        super().__init__()
        self.tag = 'UNIT'
        self._node = etree.Element('UNIT')
        self.__factorSiToUnit = None
        self.__offsetSiToUnit = None
        self.__displayName = None
        self.__physicalDimension = None
        self.__physicalDimension_as_string = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        factorSiToUnit_value = AutosarNode._get_node_text(node,'FACTOR-SI-TO-UNIT')
        if factorSiToUnit_value is not None:
            self.__factorSiToUnit = datatype_utils.get_float_value(factorSiToUnit_value)

        offsetSiToUnit_value = AutosarNode._get_node_text(node,'OFFSET-SI-TO-UNIT')
        if offsetSiToUnit_value is not None:
            self.__offsetSiToUnit = datatype_utils.get_float_value(offsetSiToUnit_value)

        displayName_node = self._node.find('{*}DISPLAY-NAME')
        if displayName_node is not None:
            if displayName_node.find('{*}SHORT-NAME') is None:
                self.__displayName = SingleLanguageUnitNames()._build(self, displayName_node, file, '[displayName_@]')
            else:
                self.__displayName = SingleLanguageUnitNames()._build(self, displayName_node, file)

        return self

    def _resolve_references(self):
        super()._resolve_references()
        physicalDimension_node = self._node.find('{*}PHYSICAL-DIMENSION-REF')
        if physicalDimension_node is not None and physicalDimension_node.text is not None:
            refText = ''
            refBase = physicalDimension_node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + physicalDimension_node.text
            self.__physicalDimension_as_string = refText
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__physicalDimension = ref_value


    def get_factorSiToUnit(self) -> float:
        return self.__factorSiToUnit

    def set_factorSiToUnit(self, value: float) -> None:
        self.__factorSiToUnit = value
        XDT.mark_attribute_dirty('factorSiToUnit', self)

    def get_offsetSiToUnit(self) -> float:
        return self.__offsetSiToUnit

    def set_offsetSiToUnit(self, value: float) -> None:
        self.__offsetSiToUnit = value
        XDT.mark_attribute_dirty('offsetSiToUnit', self)

    def get_displayName(self) -> SingleLanguageUnitNames:
        return self.__displayName

    def set_displayName(self, value: SingleLanguageUnitNames) -> None:
        """
        Adds a single value to the displayName
        """
        if value is not None:
            if isinstance(value, SingleLanguageUnitNames) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of SingleLanguageUnitNames or its sub-classes'.format(value))
            #if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

