class SwcExclusiveAreaPolicy(ARObject):
    """
    Options how to generate the ExclusiveArea related APIs. If no SwcExclusiveAreaPolicy is specified for an ExclusiveArea the default values apply.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'SWC-EXCLUSIVE-AREA-POLICY'
        self._node = etree.Element('SWC-EXCLUSIVE-AREA-POLICY')
        self.__apiPrinciple = None
        self.__exclusiveArea = None
        self.__exclusiveArea_as_string = None
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        apiPrinciple_value = AutosarNode._get_node_text(node,'API-PRINCIPLE')
        if apiPrinciple_value is not None:
            self.__apiPrinciple = ApiPrincipleEnum.get(apiPrinciple_value)

        variationPoint_node = self._node.find('{*}VARIATION-POINT')
        if variationPoint_node is not None:
            if variationPoint_node.find('{*}SHORT-NAME') is None:
                self.__variationPoint = VariationPoint()._build(self, variationPoint_node, file, '[variationPoint_@]')
            else:
                self.__variationPoint = VariationPoint()._build(self, variationPoint_node, file)

        return self

    def _resolve_references(self):
        super()._resolve_references()
        exclusiveArea_node = self._node.find('{*}EXCLUSIVE-AREA-REF')
        if exclusiveArea_node is not None and exclusiveArea_node.text is not None:
            refText = ''
            refBase = exclusiveArea_node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + exclusiveArea_node.text
            self.__exclusiveArea_as_string = refText
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__exclusiveArea = ref_value


    def get_apiPrinciple(self) -> ApiPrincipleEnum:
        return self.__apiPrinciple

    def set_apiPrinciple(self, value: ApiPrincipleEnum) -> None:
        self.__apiPrinciple = value
        XDT.mark_attribute_dirty('apiPrinciple', self)

    def get_exclusiveArea(self) -> ExclusiveArea:
        return self.__exclusiveArea

    def get_exclusiveArea_as_string(self) -> str:
        return self.__exclusiveArea_as_string

    def set_exclusiveArea(self, value: ExclusiveArea) -> None:
        """
        Adds a single value to the exclusiveArea
        """
        if value is not None:
            if isinstance(value, ExclusiveArea) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of ExclusiveArea or its sub-classes'.format(value))
            if self.__exclusiveArea is not None:
                self.__exclusiveArea.referenced_by.remove(self)
            self.__exclusiveArea = value
            value.referenced_by.add(self)
        elif self.__exclusiveArea is not None:
            self.__exclusiveArea.referenced_by.remove(self)
            self.__exclusiveArea = None
        XDT.mark_dirty(self.__exclusiveArea, self)

    def get_variationPoint(self) -> VariationPoint:
        return self.__variationPoint

    def set_variationPoint(self, value: VariationPoint) -> None:
        """
        Adds a single value to the variationPoint
        """
        if value is not None:
            if isinstance(value, VariationPoint) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of VariationPoint or its sub-classes'.format(value))
            #if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            self.__variationPoint = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._build_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'VariationPoint_@' + str(len(self.get_children()))) #updates the path
        elif self.__variationPoint is not None:
            self.__variationPoint = None
        XDT.mark_dirty(self.__variationPoint, self)

    def new_VariationPoint(self, name: str=None) -> VariationPoint:
        """
        Creates a new VariationPoint under the SwcExclusiveAreaPolicy.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        VariationPoint_obj = VariationPoint()
        if isinstance(VariationPoint_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        VariationPoint_obj.name = name if isinstance(VariationPoint_obj, Referrable) else None
        self.set_variationPoint(VariationPoint_obj)
        if isinstance(VariationPoint_obj, Referrable):
            VariationPoint_obj.set_shortName(name)
        return VariationPoint_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        if self.__variationPoint is not None:
            children.append(self.__variationPoint)
        return children



    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['ApiPrinciple'] = self.__apiPrinciple
        property_values['ExclusiveArea'] = self.__exclusiveArea
        return property_values

    def _update_path(self):
        """
        Updates the path of the SwcExclusiveAreaPolicy and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

    def is_atp_splitable(self) -> bool:
        return True

    def _save_contents(self):
        """
        Saves the content of SwcExclusiveAreaPolicy node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_ARObject()
        if XDT.is_attribute_dirty('apiPrinciple', self):
            if self.__apiPrinciple is None:
                AutosarNode._remove_xml_node_if_exists(self._node, 'API-PRINCIPLE')
            else:
                apiPrinciple_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'API-PRINCIPLE', create_after_nodes = ['T', 'S'] + self._insert_after_tags)
                apiPrinciple_xml_node.text = self.__apiPrinciple.literal

        if self.__exclusiveArea is None:
            AutosarNode._remove_xml_node_if_exists(self._node, 'EXCLUSIVE-AREA-REF')
        elif XDT.is_dirty(self.__exclusiveArea):
            exclusiveArea_value = AutosarNode._add_or_get_xml_node(self._node, 'EXCLUSIVE-AREA-REF', dest = self.__exclusiveArea, create_after_nodes = self._insert_after_tags + ['API-PRINCIPLE', 'T', 'S'] + self._insert_after_tags)
            exclusiveArea_value.text = self.__exclusiveArea.autosar_path
            exclusiveArea_value.attrib['DEST'] = self.__exclusiveArea.tag

        if self.__variationPoint is not None:
            if XDT.is_dirty(self.__variationPoint) and self.__variationPoint.file == self.file:
                self.__variationPoint._node.tag = 'VARIATION-POINT'
                self.__variationPoint._save_contents()
                if self._node.find('{*}VARIATION-POINT') is None:
                    AutosarNode._insert_element_after_given_tags(self._node, self.__variationPoint._node, create_after_nodes = self._insert_after_tags + ['EXCLUSIVE-AREA-REF', 'API-PRINCIPLE', 'T', 'S'])
        else:
            AutosarNode._remove_xml_node_if_exists(self._node, 'VARIATION-POINT')


class AbstractAccessPoint(AtpStructureElement):
    """
    Abstract class indicating an access point from an ExecutableEntity.
    """
    def __init__(self):
        super().__init__()
        self.__returnValueProvision = None

