class RoleBasedPortAssignment(ARObject):
    """
    This class specifies an assignment of a role to a particular service port (RPortPrototype or PPortPrototype) of an AtomicSwComponentType. With this assignment, the role of the service port can be mapped to a specific ServiceNeeds element, so that a tool is able to create the correct connector.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'ROLE-BASED-PORT-ASSIGNMENT'
        self._node = etree.Element('ROLE-BASED-PORT-ASSIGNMENT')
        self.__role = None
        self.__portPrototype = None
        self.__portPrototype_as_string = None
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        role_value = AutosarNode._get_node_text(node,'ROLE')
        if role_value is not None:
            self.__role = datatype_utils.get_string_value(role_value)

        variationPoint_node = self._node.find('{*}VARIATION-POINT')
        if variationPoint_node is not None:
            if variationPoint_node.find('{*}SHORT-NAME') is None:
                self.__variationPoint = VariationPoint()._build(self, variationPoint_node, file, '[variationPoint_@]')
            else:
                self.__variationPoint = VariationPoint()._build(self, variationPoint_node, file)

        return self

    def _resolve_references(self):
        super()._resolve_references()
        portPrototype_node = self._node.find('{*}PORT-PROTOTYPE-REF')
        if portPrototype_node is not None and portPrototype_node.text is not None:
            refText = ''
            refBase = portPrototype_node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + portPrototype_node.text
            self.__portPrototype_as_string = refText
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__portPrototype = ref_value


    def get_role(self) -> str:
        return self.__role

    def set_role(self, value: str) -> None:
        self.__role = value
        XDT.mark_attribute_dirty('role', self)

    def get_portPrototype(self) -> PortPrototype:
        return self.__portPrototype

    def get_portPrototype_as_string(self) -> str:
        return self.__portPrototype_as_string

    def set_portPrototype(self, value: PortPrototype) -> None:
        """
        Adds a single value to the portPrototype
        """
        if value is not None:
            if isinstance(value, PortPrototype) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of PortPrototype or its sub-classes'.format(value))
            if self.__portPrototype is not None:
                self.__portPrototype.referenced_by.remove(self)
            self.__portPrototype = value
            value.referenced_by.add(self)
        elif self.__portPrototype is not None:
            self.__portPrototype.referenced_by.remove(self)
            self.__portPrototype = None
        XDT.mark_dirty(self.__portPrototype, self)

    def get_variationPoint(self) -> VariationPoint:
        return self.__variationPoint

    def set_variationPoint(self, value: VariationPoint) -> None:
        """
        Adds a single value to the variationPoint
        """
        if value is not None:
            if isinstance(value, VariationPoint) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of VariationPoint or its sub-classes'.format(value))
            #if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            self.__variationPoint = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._build_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'VariationPoint_@' + str(len(self.get_children()))) #updates the path
        elif self.__variationPoint is not None:
            self.__variationPoint = None
        XDT.mark_dirty(self.__variationPoint, self)

    def new_VariationPoint(self, name: str=None) -> VariationPoint:
        """
        Creates a new VariationPoint under the RoleBasedPortAssignment.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        VariationPoint_obj = VariationPoint()
        if isinstance(VariationPoint_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        VariationPoint_obj.name = name if isinstance(VariationPoint_obj, Referrable) else None
        self.set_variationPoint(VariationPoint_obj)
        if isinstance(VariationPoint_obj, Referrable):
            VariationPoint_obj.set_shortName(name)
        return VariationPoint_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        if self.__variationPoint is not None:
            children.append(self.__variationPoint)
        return children



    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['Role'] = self.__role
        property_values['PortPrototype'] = self.__portPrototype
        return property_values

    def _update_path(self):
        """
        Updates the path of the RoleBasedPortAssignment and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

    def is_atp_splitable(self) -> bool:
        return True

    def _save_contents(self):
        """
        Saves the content of RoleBasedPortAssignment node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_ARObject()
        if self.__portPrototype is None:
            AutosarNode._remove_xml_node_if_exists(self._node, 'PORT-PROTOTYPE-REF')
        elif XDT.is_dirty(self.__portPrototype):
            portPrototype_value = AutosarNode._add_or_get_xml_node(self._node, 'PORT-PROTOTYPE-REF', dest = self.__portPrototype, create_after_nodes = self._insert_after_tags + ['T', 'S'] + self._insert_after_tags)
            portPrototype_value.text = self.__portPrototype.autosar_path
            portPrototype_value.attrib['DEST'] = self.__portPrototype.tag

        if XDT.is_attribute_dirty('role', self):
            if self.__role is None:
                AutosarNode._remove_xml_node_if_exists(self._node, 'ROLE')
            else:
                role_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'ROLE', create_after_nodes = ['PORT-PROTOTYPE-REF', 'T', 'S'] + self._insert_after_tags)
                role_xml_node.text = str(self.__role)

        if self.__variationPoint is not None:
            if XDT.is_dirty(self.__variationPoint) and self.__variationPoint.file == self.file:
                self.__variationPoint._node.tag = 'VARIATION-POINT'
                self.__variationPoint._save_contents()
                if self._node.find('{*}VARIATION-POINT') is None:
                    AutosarNode._insert_element_after_given_tags(self._node, self.__variationPoint._node, create_after_nodes = self._insert_after_tags + ['ROLE', 'PORT-PROTOTYPE-REF', 'T', 'S'])
        else:
            AutosarNode._remove_xml_node_if_exists(self._node, 'VARIATION-POINT')


class SwcServiceDependency(AtpStructureElement,ServiceDependency):
    """
    Specialization of ServiceDependency in the context of an SwcInternalBehavior. It allows to associate ports, port groups and (in special cases) data defined for an atomic software component  to a given ServiceNeeds element.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'SWC-SERVICE-DEPENDENCY'
        self._node = etree.Element('SWC-SERVICE-DEPENDENCY')
        self.__assignedDatas = {} # using dict to preserve the order of elements
        self.__assignedPorts = {} # using dict to preserve the order of elements
        self.__representedPortGroup = None
        self.__representedPortGroup_as_string = None
        self.__serviceNeeds = None
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        refCounter = 0
        assignedDatas_nodes = self._node.findall('{*}ASSIGNED-DATAS/*')
        for assignedDatas_node in assignedDatas_nodes:
            buildassignedDatas_node = None
            if assignedDatas_node.find('{*}SHORT-NAME') is None:
                buildassignedDatas_node = RoleBasedDataAssignment()._build(self, assignedDatas_node, file, '[assignedDatas_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildassignedDatas_node = RoleBasedDataAssignment()._build(self, assignedDatas_node, file)
            self.__assignedDatas[(buildassignedDatas_node)] = None

        assignedPorts_nodes = self._node.findall('{*}ASSIGNED-PORTS/*')
        for assignedPorts_node in assignedPorts_nodes:
            buildassignedPorts_node = None
            if assignedPorts_node.find('{*}SHORT-NAME') is None:
                buildassignedPorts_node = RoleBasedPortAssignment()._build(self, assignedPorts_node, file, '[assignedPorts_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildassignedPorts_node = RoleBasedPortAssignment()._build(self, assignedPorts_node, file)
            self.__assignedPorts[(buildassignedPorts_node)] = None

        serviceNeeds_obj_dict = {}
        serviceNeeds_obj_dict['BSW-MGR-NEEDS'] = 'BswMgrNeeds'
        serviceNeeds_obj_dict['COM-MGR-USER-NEEDS'] = 'ComMgrUserNeeds'
        serviceNeeds_obj_dict['CRYPTO-KEY-MANAGEMENT-NEEDS'] = 'CryptoKeyManagementNeeds'
        serviceNeeds_obj_dict['CRYPTO-SERVICE-JOB-NEEDS'] = 'CryptoServiceJobNeeds'
        serviceNeeds_obj_dict['CRYPTO-SERVICE-NEEDS'] = 'CryptoServiceNeeds'
        serviceNeeds_obj_dict['DIAGNOSTIC-COMMUNICATION-MANAGER-NEEDS'] = 'DiagnosticCommunicationManagerNeeds'
        serviceNeeds_obj_dict['DIAGNOSTIC-COMPONENT-NEEDS'] = 'DiagnosticComponentNeeds'
        serviceNeeds_obj_dict['DIAGNOSTIC-CONTROL-NEEDS'] = 'DiagnosticControlNeeds'
        serviceNeeds_obj_dict['DIAGNOSTIC-ENABLE-CONDITION-NEEDS'] = 'DiagnosticEnableConditionNeeds'
        serviceNeeds_obj_dict['DIAGNOSTIC-EVENT-INFO-NEEDS'] = 'DiagnosticEventInfoNeeds'
        serviceNeeds_obj_dict['DIAGNOSTIC-EVENT-MANAGER-NEEDS'] = 'DiagnosticEventManagerNeeds'
        serviceNeeds_obj_dict['DIAGNOSTIC-EVENT-NEEDS'] = 'DiagnosticEventNeeds'
        serviceNeeds_obj_dict['DIAGNOSTIC-IO-CONTROL-NEEDS'] = 'DiagnosticIoControlNeeds'
        serviceNeeds_obj_dict['DIAGNOSTIC-VALUE-NEEDS'] = 'DiagnosticValueNeeds'
