        serviceNeeds_obj_dict['J-1939-RM-INCOMING-REQUEST-SERVICE-NEEDS'] = 'J1939RmIncomingRequestServiceNeeds'
        serviceNeeds_obj_dict['J-1939-RM-OUTGOING-REQUEST-SERVICE-NEEDS'] = 'J1939RmOutgoingRequestServiceNeeds'
