        serviceNeeds_obj_dict['SECURE-ON-BOARD-COMMUNICATION-NEEDS'] = 'SecureOnBoardCommunicationNeeds'
        serviceNeeds_obj_dict['SUPERVISED-ENTITY-CHECKPOINT-NEEDS'] = 'SupervisedEntityCheckpointNeeds'
        serviceNeeds_obj_dict['SUPERVISED-ENTITY-NEEDS'] = 'SupervisedEntityNeeds'
        serviceNeeds_obj_dict['SYNC-TIME-BASE-MGR-USER-NEEDS'] = 'SyncTimeBaseMgrUserNeeds'
