class IncludedModeDeclarationGroupSet(ARObject):
    """
    An IncludedModeDeclarationGroupSet declares that a set of ModeDeclarationGroups used by the software component for its implementation and consequently these ModeDeclarationGroups become part of the contract.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'INCLUDED-MODE-DECLARATION-GROUP-SET'
        self._node = etree.Element('INCLUDED-MODE-DECLARATION-GROUP-SET')
        self.__prefix = None
        self.__modeDeclarationGroups = {} # using dict to preserve the order of elements
        self.__modeDeclarationGroups_as_string = {} # using dict to preserve the order of elements

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        prefix_value = AutosarNode._get_node_text(node,'PREFIX')
        if prefix_value is not None:
            self.__prefix = datatype_utils.get_string_value(prefix_value)

        return self

    def _resolve_references(self):
        super()._resolve_references()
        modeDeclarationGroups_nodes = self._node.findall('{*}MODE-DECLARATION-GROUP-REFS/*')
        for node in modeDeclarationGroups_nodes:
            if node.text is None:
                continue
