class PortInterface(ARElement,AtpBlueprint,AtpBlueprintable,AtpType):
    """
    Abstract base class for an interface that is either provided or required by a port of a  software component.
    """
    def __init__(self):
        super().__init__()
        self.__isService = None
        self.__serviceKind = None
        self.__namespaces = {} # using dict to preserve the order of elements

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        isService_value = AutosarNode._get_node_text(node,'IS-SERVICE')
        if isService_value is not None:
            self.__isService = datatype_utils.get_bool_value(isService_value)

        serviceKind_value = AutosarNode._get_node_text(node,'SERVICE-KIND')
        if serviceKind_value is not None:
            self.__serviceKind = ServiceProviderEnum.get(serviceKind_value)

        refCounter = 0
        namespaces_nodes = self._node.findall('{*}NAMESPACES/*')
        for namespaces_node in namespaces_nodes:
            buildnamespaces_node = None
            if namespaces_node.find('{*}SHORT-NAME') is None:
                buildnamespaces_node = SymbolProps()._build(self, namespaces_node, file, '[namespaces_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildnamespaces_node = SymbolProps()._build(self, namespaces_node, file)
            self.__namespaces[(buildnamespaces_node)] = None

        return self

    def get_isService(self) -> bool:
        return self.__isService

    def set_isService(self, value: bool) -> None:
        self.__isService = value
        XDT.mark_attribute_dirty('isService', self)

    def get_serviceKind(self) -> ServiceProviderEnum:
        return self.__serviceKind

    def set_serviceKind(self, value: ServiceProviderEnum) -> None:
        self.__serviceKind = value
        XDT.mark_attribute_dirty('serviceKind', self)

    def get_namespaces(self) -> list[SymbolProps]:
        return list(self.__namespaces.keys())

    def add_namespace(self, value: SymbolProps) -> None:
        """
        Adds a single value to the namespaces
        """
        if value is not None:
            if isinstance(value, Referrable) and any(v.name == value.name for v in self.__namespaces.keys()):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, SymbolProps) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of SymbolProps or its sub-classes'.format(value))
            self.__namespaces[value] = None
            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

