class EcucCommonAttributes(EcucDefinitionElement):
    """
    Attributes used by Configuration Parameters as well as References.
    """
    def __init__(self):
        super().__init__()
        self.__origin = None
        self.__postBuildVariantMultiplicity = None
        self.__postBuildVariantValue = None
        self.__requiresIndex = None
        self.__configurationClassAffection = None
        self.__implementationConfigClass = {} # using dict to preserve the order of elements
        self.__multiplicityConfigClass = {} # using dict to preserve the order of elements
        self.__valueConfigClass = {} # using dict to preserve the order of elements

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        origin_value = AutosarNode._get_node_text(node,'ORIGIN')
        if origin_value is not None:
            self.__origin = datatype_utils.get_string_value(origin_value)

        postBuildVariantMultiplicity_value = AutosarNode._get_node_text(node,'POST-BUILD-VARIANT-MULTIPLICITY')
        if postBuildVariantMultiplicity_value is not None:
            self.__postBuildVariantMultiplicity = datatype_utils.get_bool_value(postBuildVariantMultiplicity_value)

        postBuildVariantValue_value = AutosarNode._get_node_text(node,'POST-BUILD-VARIANT-VALUE')
        if postBuildVariantValue_value is not None:
            self.__postBuildVariantValue = datatype_utils.get_bool_value(postBuildVariantValue_value)

        requiresIndex_value = AutosarNode._get_node_text(node,'REQUIRES-INDEX')
        if requiresIndex_value is not None:
            self.__requiresIndex = datatype_utils.get_bool_value(requiresIndex_value)

        refCounter = 0
        configurationClassAffection_node = self._node.find('{*}CONFIGURATION-CLASS-AFFECTION')
        if configurationClassAffection_node is not None:
            if configurationClassAffection_node.find('{*}SHORT-NAME') is None:
                self.__configurationClassAffection = EcucConfigurationClassAffection()._build(self, configurationClassAffection_node, file, '[configurationClassAffection_@]')
            else:
                self.__configurationClassAffection = EcucConfigurationClassAffection()._build(self, configurationClassAffection_node, file)

        implementationConfigClass_nodes = self._node.findall('{*}IMPLEMENTATION-CONFIG-CLASSES/*')
        for implementationConfigClass_node in implementationConfigClass_nodes:
            buildimplementationConfigClass_node = None
            if implementationConfigClass_node.find('{*}SHORT-NAME') is None:
                buildimplementationConfigClass_node = EcucImplementationConfigurationClass()._build(self, implementationConfigClass_node, file, '[implementationConfigClass_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildimplementationConfigClass_node = EcucImplementationConfigurationClass()._build(self, implementationConfigClass_node, file)
            self.__implementationConfigClass[(buildimplementationConfigClass_node)] = None

        multiplicityConfigClass_nodes = self._node.findall('{*}MULTIPLICITY-CONFIG-CLASSES/*')
