class EcucChoiceReferenceDef(EcucAbstractInternalReferenceDef):
    """
    Specify alternative references where in the ECU Configuration description only one of the specified references will actually be used.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'ECUC-CHOICE-REFERENCE-DEF'
        self._node = etree.Element('ECUC-CHOICE-REFERENCE-DEF')
        self.__destinations = {} # using dict to preserve the order of elements
        self.__destinations_as_string = {} # using dict to preserve the order of elements


    def _resolve_references(self):
        super()._resolve_references()
        destinations_nodes = self._node.findall('{*}DESTINATION-REFS/*')
        for node in destinations_nodes:
            if node.text is None:
                continue
            refText = ''
            refBase = node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + node.text
            self.__destinations_as_string[refText] = None
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__destinations[ref_value] = None


    def get_destinations(self) -> list[EcucContainerDef]:
        return list(self.__destinations.keys())

    def get_destinations_as_string(self) -> str:
        return list(self.__destinations_as_string.keys())

    def add_destination(self, value: EcucContainerDef) -> None:
        """
        Adds a single value to the destinations
        """
        if value is not None:
            if isinstance(value, Referrable) and any(v.name == value.name for v in self.__destinations.keys()):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, EcucContainerDef) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of EcucContainerDef or its sub-classes'.format(value))
            self.__destinations[value] = None
            value.referenced_by.add(self)
            XDT.mark_dirty(value, self)

    def set_destinations(self, values: list[EcucContainerDef]) -> None:
        """
        Adds a list of ref value to the destinations
        """
        for value in values:
            self.add_destination(value)

    def remove_destination(self, value: EcucContainerDef) -> None:
        """
        Removes a single value from destinations
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__destinations.pop(value)
            value.referenced_by.remove(self)

    def remove_destinations(self, values: list[EcucContainerDef]) -> None:
        """
        Removes a list of value from destinations
        """
        for value in values:
            self.remove_destination(value)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['Destinations'] = self.__destinations
        return property_values

    def _update_path(self):
        """
        Updates the path of the EcucChoiceReferenceDef and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

    def is_atp_splitable(self) -> bool:
        return True

    def _save_contents(self):
        """
        Saves the content of EcucChoiceReferenceDef node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_EcucAbstractInternalReferenceDef()
        if len(self.__destinations) > 0:
            AutosarNode._remove_xml_node_if_exists(self._node, 'DESTINATION-REFS')
        if len(self.__destinations) > 0:
            destinations_values = AutosarNode._add_or_get_xml_node(self._node, 'DESTINATION-REFS', create_after_nodes = self._insert_after_tags + ['REQUIRES-SYMBOLIC-NAME-VALUE', 'VALUE-CONFIG-CLASSES', 'REQUIRES-INDEX', 'POST-BUILD-VARIANT-VALUE', 'POST-BUILD-VARIANT-MULTIPLICITY', 'ORIGIN', 'MULTIPLICITY-CONFIG-CLASSES', 'IMPLEMENTATION-CONFIG-CLASSES', 'CONFIGURATION-CLASS-AFFECTION', 'SCOPE', 'UPPER-MULTIPLICITY-INFINITE', 'UPPER-MULTIPLICITY', 'LOWER-MULTIPLICITY', 'ECUC-COND', 'ECUC-VALIDATION-CONDS', 'RELATED-TRACE-ITEM-REF', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'] + self._insert_after_tags)
            for value in self.__destinations:
                destinations_value = AutosarNode._add_or_get_xml_node(destinations_values, 'DESTINATION-REF', dest = value, create_after_nodes = ['DESTINATION-REF'], forceCreate = True)
                destinations_value.text = value.autosar_path
                destinations_value.attrib['DEST'] = value.tag


