class EcucModuleDef(ARElement,AtpBlueprint,AtpBlueprintable,EcucDefinitionElement):
    """
    Used as the top-level element for configuration definition for Software Modules, including BSW and RTE as well as ECU Infrastructure.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'ECUC-MODULE-DEF'
        self._node = etree.Element('ECUC-MODULE-DEF')
        self.__apiServicePrefix = None
        self.__postBuildVariantSupport = None
        self.__supportedConfigVariants = None
        self.__refinedModuleDef = None
        self.__refinedModuleDef_as_string = None
        self.__containers = {} # using dict to preserve the order of elements

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        apiServicePrefix_value = AutosarNode._get_node_text(node,'API-SERVICE-PREFIX')
        if apiServicePrefix_value is not None:
            self.__apiServicePrefix = datatype_utils.get_string_value(apiServicePrefix_value)

        postBuildVariantSupport_value = AutosarNode._get_node_text(node,'POST-BUILD-VARIANT-SUPPORT')
        if postBuildVariantSupport_value is not None:
            self.__postBuildVariantSupport = datatype_utils.get_bool_value(postBuildVariantSupport_value)

        supportedConfigVariants_value = node.text
        if supportedConfigVariants_value is not None:
            self.__supportedConfigVariants = EcucConfigurationVariantEnum.get(supportedConfigVariants_value)

        refCounter = 0
        containers_obj_dict = {}
        containers_obj_dict['ECUC-CHOICE-CONTAINER-DEF'] = 'EcucChoiceContainerDef'
        containers_obj_dict['ECUC-PARAM-CONF-CONTAINER-DEF'] = 'EcucParamConfContainerDef'
        containers_nodes = self._node.findall('{*}CONTAINERS/*')
        for containers_node in containers_nodes:
            buildcontainers_node = None
            if containers_node.find('{*}SHORT-NAME') is None:
                buildcontainers_node = __str_to_class__(containers_obj_dict[etree.QName(containers_node).localname])()._build(self, containers_node, file, '[containers_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildcontainers_node = __str_to_class__(containers_obj_dict[etree.QName(containers_node).localname])()._build(self, containers_node, file)
            self.__containers[buildcontainers_node] = None

        return self

    def _resolve_references(self):
        super()._resolve_references()
        refinedModuleDef_node = self._node.find('{*}REFINED-MODULE-DEF-REF')
        if refinedModuleDef_node is not None and refinedModuleDef_node.text is not None:
            refText = ''
            refBase = refinedModuleDef_node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + refinedModuleDef_node.text
            self.__refinedModuleDef_as_string = refText
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
