                    AutosarNode._insert_element_after_given_tags(self._node, self.__ident._node, create_after_nodes = self._insert_after_tags + ['SYMBOLIC-NAME-PROPS', 'ASSIGNED-DATA-TYPES', 'T', 'S'])
