class RoleBasedBswModuleEntryAssignment(ARObject):
    """
    This class specifies an assignment of a role to a particular BswModuleEntry (usually a configurable callback). , , With this assignment, the role of the callback is mapped to a specific ServiceNeeds element, so that a tool is able to create appropriate configuration values for the module that implements the AUTOSAR Service.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'ROLE-BASED-BSW-MODULE-ENTRY-ASSIGNMENT'
        self._node = etree.Element('ROLE-BASED-BSW-MODULE-ENTRY-ASSIGNMENT')
        self.__role = None
        self.__assignedEntry = None
        self.__assignedEntry_as_string = None
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        role_value = AutosarNode._get_node_text(node,'ROLE')
        if role_value is not None:
            self.__role = datatype_utils.get_string_value(role_value)

        variationPoint_node = self._node.find('{*}VARIATION-POINT')
        if variationPoint_node is not None:
            if variationPoint_node.find('{*}SHORT-NAME') is None:
                self.__variationPoint = VariationPoint()._build(self, variationPoint_node, file, '[variationPoint_@]')
            else:
                self.__variationPoint = VariationPoint()._build(self, variationPoint_node, file)

        return self

    def _resolve_references(self):
        super()._resolve_references()
        assignedEntry_node = self._node.find('{*}ASSIGNED-ENTRY-REF')
        if assignedEntry_node is not None and assignedEntry_node.text is not None:
            refText = ''
            refBase = assignedEntry_node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + assignedEntry_node.text
            self.__assignedEntry_as_string = refText
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__assignedEntry = ref_value


    def get_role(self) -> str:
        return self.__role

    def set_role(self, value: str) -> None:
        self.__role = value
        XDT.mark_attribute_dirty('role', self)

    def get_assignedEntry(self) -> BswModuleEntry:
        return self.__assignedEntry

    def get_assignedEntry_as_string(self) -> str:
        return self.__assignedEntry_as_string

    def set_assignedEntry(self, value: BswModuleEntry) -> None:
        """
        Adds a single value to the assignedEntry
        """
        if value is not None:
            if isinstance(value, BswModuleEntry) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of BswModuleEntry or its sub-classes'.format(value))
            if self.__assignedEntry is not None:
                self.__assignedEntry.referenced_by.remove(self)
            self.__assignedEntry = value
            value.referenced_by.add(self)
        elif self.__assignedEntry is not None:
            self.__assignedEntry.referenced_by.remove(self)
            self.__assignedEntry = None
        XDT.mark_dirty(self.__assignedEntry, self)

    def get_variationPoint(self) -> VariationPoint:
        return self.__variationPoint

    def set_variationPoint(self, value: VariationPoint) -> None:
        """
        Adds a single value to the variationPoint
        """
        if value is not None:
            if isinstance(value, VariationPoint) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of VariationPoint or its sub-classes'.format(value))
            #if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            self.__variationPoint = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._build_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'VariationPoint_@' + str(len(self.get_children()))) #updates the path
        elif self.__variationPoint is not None:
            self.__variationPoint = None
        XDT.mark_dirty(self.__variationPoint, self)

    def new_VariationPoint(self, name: str=None) -> VariationPoint:
        """
        Creates a new VariationPoint under the RoleBasedBswModuleEntryAssignment.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        VariationPoint_obj = VariationPoint()
        if isinstance(VariationPoint_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        VariationPoint_obj.name = name if isinstance(VariationPoint_obj, Referrable) else None
        self.set_variationPoint(VariationPoint_obj)
        if isinstance(VariationPoint_obj, Referrable):
            VariationPoint_obj.set_shortName(name)
        return VariationPoint_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        if self.__variationPoint is not None:
            children.append(self.__variationPoint)
        return children



    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['Role'] = self.__role
        property_values['AssignedEntry'] = self.__assignedEntry
        return property_values

    def _update_path(self):
        """
        Updates the path of the RoleBasedBswModuleEntryAssignment and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

    def is_atp_splitable(self) -> bool:
        return True

    def _save_contents(self):
        """
        Saves the content of RoleBasedBswModuleEntryAssignment node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_ARObject()
        if self.__assignedEntry is None:
            AutosarNode._remove_xml_node_if_exists(self._node, 'ASSIGNED-ENTRY-REF')
        elif XDT.is_dirty(self.__assignedEntry):
            assignedEntry_value = AutosarNode._add_or_get_xml_node(self._node, 'ASSIGNED-ENTRY-REF', dest = self.__assignedEntry, create_after_nodes = self._insert_after_tags + ['T', 'S'] + self._insert_after_tags)
            assignedEntry_value.text = self.__assignedEntry.autosar_path
            assignedEntry_value.attrib['DEST'] = self.__assignedEntry.tag

        if XDT.is_attribute_dirty('role', self):
            if self.__role is None:
                AutosarNode._remove_xml_node_if_exists(self._node, 'ROLE')
            else:
                role_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'ROLE', create_after_nodes = ['ASSIGNED-ENTRY-REF', 'T', 'S'] + self._insert_after_tags)
                role_xml_node.text = str(self.__role)

        if self.__variationPoint is not None:
            if XDT.is_dirty(self.__variationPoint) and self.__variationPoint.file == self.file:
                self.__variationPoint._node.tag = 'VARIATION-POINT'
                self.__variationPoint._save_contents()
                if self._node.find('{*}VARIATION-POINT') is None:
                    AutosarNode._insert_element_after_given_tags(self._node, self.__variationPoint._node, create_after_nodes = self._insert_after_tags + ['ROLE', 'ASSIGNED-ENTRY-REF', 'T', 'S'])
        else:
            AutosarNode._remove_xml_node_if_exists(self._node, 'VARIATION-POINT')


class BswModeReceiverPolicy(ARObject):
    """
    Specifies the details for the reception of a mode switch for the referred mode group.
    """
