class BswModeSwitchEvent(BswScheduleEvent):
    """
    A BswEvent resulting from a mode switch.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'BSW-MODE-SWITCH-EVENT'
        self._node = etree.Element('BSW-MODE-SWITCH-EVENT')
        self.__activation = None
        self.__modes = {} # using dict to preserve the order of elements

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        activation_value = AutosarNode._get_node_text(node,'ACTIVATION')
        if activation_value is not None:
            self.__activation = ModeActivationKind.get(activation_value)

        refCounter = 0
        modes_nodes = self._node.findall('{*}MODE-IREFS/*')
        for modes_node in modes_nodes:
            buildmodes_node = None
            if modes_node.find('{*}SHORT-NAME') is None:
                buildmodes_node = ModeInBswModuleDescriptionInstanceRef()._build(self, modes_node, file, '[modes_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildmodes_node = ModeInBswModuleDescriptionInstanceRef()._build(self, modes_node, file)
            self.__modes[(buildmodes_node)] = None

        return self

    def get_activation(self) -> ModeActivationKind:
        return self.__activation

    def set_activation(self, value: ModeActivationKind) -> None:
        self.__activation = value
        XDT.mark_attribute_dirty('activation', self)

    def get_modes(self) -> list[ModeInBswModuleDescriptionInstanceRef]:
        return list(self.__modes.keys())

    def add_mode(self, value: ModeInBswModuleDescriptionInstanceRef) -> None:
        """
        Adds a single value to the modes
        """
        if value is not None:
            if isinstance(value, Referrable) and any(v.name == value.name for v in self.__modes.keys()):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, ModeInBswModuleDescriptionInstanceRef) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of ModeInBswModuleDescriptionInstanceRef or its sub-classes'.format(value))
            self.__modes[value] = None
            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            value._parent = self #set parent
            value.file = self.file
            if value.name is not None:
                value._update_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'ModeInBswModuleDescriptionInstanceRef_@' + str(len(self.get_children()))) #updates the path
            XDT.mark_dirty(value, self, attributesToMakeDirty = ['timestamp', 'checksum'])

    def set_modes(self, values: list[ModeInBswModuleDescriptionInstanceRef]) -> None:
        """
        Adds a list of ref value to the modes
        """
        for value in values:
            self.add_mode(value)

    def remove_mode(self, value: ModeInBswModuleDescriptionInstanceRef) -> None:
        """
        Removes a single value from modes
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__modes.pop(value)
            value._parent = None #No parent
            value._update_path() #resets the path
            value._node.getparent().remove(value._node)

