class ClientIdDefinitionSet(ARElement):
    """
    Set of Client Identifiers that are used for inter-ECU client-server communication in the System.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'CLIENT-ID-DEFINITION-SET'
        self._node = etree.Element('CLIENT-ID-DEFINITION-SET')
        self.__clientIdDefinitions = {} # using dict to preserve the order of elements

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        refCounter = 0
        clientIdDefinitions_nodes = self._node.findall('{*}CLIENT-ID-DEFINITIONS/*')
        for clientIdDefinitions_node in clientIdDefinitions_nodes:
            buildclientIdDefinitions_node = None
            if clientIdDefinitions_node.find('{*}SHORT-NAME') is None:
                buildclientIdDefinitions_node = ClientIdDefinition()._build(self, clientIdDefinitions_node, file, '[clientIdDefinitions_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildclientIdDefinitions_node = ClientIdDefinition()._build(self, clientIdDefinitions_node, file)
            self.__clientIdDefinitions[(buildclientIdDefinitions_node)] = None

        return self

    def get_clientIdDefinitions(self) -> list[ClientIdDefinition]:
        return list(self.__clientIdDefinitions.keys())

    def add_clientIdDefinition(self, value: ClientIdDefinition) -> None:
        """
        Adds a single value to the clientIdDefinitions
        """
        if value is not None:
            if isinstance(value, Referrable) and any(v.name == value.name for v in self.__clientIdDefinitions.keys()):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, ClientIdDefinition) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of ClientIdDefinition or its sub-classes'.format(value))
            self.__clientIdDefinitions[value] = None
