class StaticSocketConnection(Identifiable):
    """
    Definition of static SocketConnection between the Socket that is defined by the aggregating SocketAddress and the remoteAddress.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'STATIC-SOCKET-CONNECTION'
        self._node = etree.Element('STATIC-SOCKET-CONNECTION')
        self.__tcpRole = None
        self.__iPduIdentifiers = {} # using dict to preserve the order of elements
        self.__remoteAddress = {} # using dict to preserve the order of elements
