class SocketConnectionBundle(Referrable):
    """
    This elements groups SocketConnections, i.e. specifies socket connections belonging to the bundle and describes properties which are common for all socket connections in the bundle.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'SOCKET-CONNECTION-BUNDLE'
        self._node = etree.Element('SOCKET-CONNECTION-BUNDLE')
        self.__differentiatedServiceField = None
        self.__flowLabel = None
        self.__pathMtuDiscoveryEnabled = None
        self.__udpChecksumHandling = None
        self.__bundledConnections = {} # using dict to preserve the order of elements
        self.__pdus = {} # using dict to preserve the order of elements
        self.__serverPort = None
        self.__serverPort_as_string = None
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        differentiatedServiceField_value = AutosarNode._get_node_text(node,'DIFFERENTIATED-SERVICE-FIELD')
        if differentiatedServiceField_value is not None:
            self.__differentiatedServiceField = datatype_utils.get_int_value(differentiatedServiceField_value)

        flowLabel_value = AutosarNode._get_node_text(node,'FLOW-LABEL')
        if flowLabel_value is not None:
            self.__flowLabel = datatype_utils.get_int_value(flowLabel_value)

        pathMtuDiscoveryEnabled_value = AutosarNode._get_node_text(node,'PATH-MTU-DISCOVERY-ENABLED')
        if pathMtuDiscoveryEnabled_value is not None:
            self.__pathMtuDiscoveryEnabled = datatype_utils.get_bool_value(pathMtuDiscoveryEnabled_value)

        udpChecksumHandling_value = AutosarNode._get_node_text(node,'UDP-CHECKSUM-HANDLING')
        if udpChecksumHandling_value is not None:
            self.__udpChecksumHandling = UdpChecksumCalculationEnum.get(udpChecksumHandling_value)

        refCounter = 0
        bundledConnections_nodes = self._node.findall('{*}BUNDLED-CONNECTIONS/*')
        for bundledConnections_node in bundledConnections_nodes:
            buildbundledConnections_node = None
            if bundledConnections_node.find('{*}SHORT-NAME') is None:
                buildbundledConnections_node = SocketConnection()._build(self, bundledConnections_node, file, '[bundledConnections_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildbundledConnections_node = SocketConnection()._build(self, bundledConnections_node, file)
            self.__bundledConnections[(buildbundledConnections_node)] = None

        pdus_nodes = self._node.findall('{*}PDUS/*')
        for pdus_node in pdus_nodes:
            buildpdus_node = None
            if pdus_node.find('{*}SHORT-NAME') is None:
                buildpdus_node = SocketConnectionIpduIdentifier()._build(self, pdus_node, file, '[pdus_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildpdus_node = SocketConnectionIpduIdentifier()._build(self, pdus_node, file)
            self.__pdus[(buildpdus_node)] = None

        variationPoint_node = self._node.find('{*}VARIATION-POINT')
        if variationPoint_node is not None:
            if variationPoint_node.find('{*}SHORT-NAME') is None:
                self.__variationPoint = VariationPoint()._build(self, variationPoint_node, file, '[variationPoint_@]')
            else:
                self.__variationPoint = VariationPoint()._build(self, variationPoint_node, file)

        return self

    def _resolve_references(self):
        super()._resolve_references()
        serverPort_node = self._node.find('{*}SERVER-PORT-REF')
