class CouplingPort(Identifiable):
    """
    A CouplingPort is used to connect a CouplingElement with an EcuInstance or two CouplingElements with each other via a CouplingPortConnection. Optionally, the CouplingPort may also have a reference to a macMulticastGroup and a defaultVLAN.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'COUPLING-PORT'
        self._node = etree.Element('COUPLING-PORT')
        self.__connectionNegotiationBehavior = None
        self.__couplingPortRole = None
        self.__couplingPortSpeed = None
        self.__macLayerType = None
        self.__physicalLayerType = None
        self.__receiveActivity = None
        self.__couplingPortDetails = None
        self.__defaultVlan = None
        self.__defaultVlan_as_string = None
        self.__macMulticastAddress = {} # using dict to preserve the order of elements
        self.__macMulticastAddress_as_string = {} # using dict to preserve the order of elements
        self.__plcaProps = None
        self.__pncMappings = {} # using dict to preserve the order of elements
        self.__pncMappings_as_string = {} # using dict to preserve the order of elements
        self.__vlanMemberships = {} # using dict to preserve the order of elements
        self.__vlanModifier = None
        self.__vlanModifier_as_string = None
        self.__wakeupSleepOnDatalineConfig = None
        self.__wakeupSleepOnDatalineConfig_as_string = None
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        connectionNegotiationBehavior_value = AutosarNode._get_node_text(node,'CONNECTION-NEGOTIATION-BEHAVIOR')
        if connectionNegotiationBehavior_value is not None:
            self.__connectionNegotiationBehavior = EthernetConnectionNegotiationEnum.get(connectionNegotiationBehavior_value)

        couplingPortRole_value = AutosarNode._get_node_text(node,'COUPLING-PORT-ROLE')
        if couplingPortRole_value is not None:
            self.__couplingPortRole = CouplingPortRoleEnum.get(couplingPortRole_value)

        couplingPortSpeed_value = AutosarNode._get_node_text(node,'COUPLING-PORT-SPEED')
        if couplingPortSpeed_value is not None:
            self.__couplingPortSpeed = datatype_utils.get_int_value(couplingPortSpeed_value)

        macLayerType_value = AutosarNode._get_node_text(node,'MAC-LAYER-TYPE')
        if macLayerType_value is not None:
            self.__macLayerType = EthernetMacLayerTypeEnum.get(macLayerType_value)

        physicalLayerType_value = AutosarNode._get_node_text(node,'PHYSICAL-LAYER-TYPE')
        if physicalLayerType_value is not None:
            self.__physicalLayerType = EthernetPhysicalLayerTypeEnum.get(physicalLayerType_value)

        receiveActivity_value = AutosarNode._get_node_text(node,'RECEIVE-ACTIVITY')
        if receiveActivity_value is not None:
            self.__receiveActivity = EthernetSwitchVlanIngressTagEnum.get(receiveActivity_value)

        refCounter = 0
        couplingPortDetails_node = self._node.find('{*}COUPLING-PORT-DETAILS')
        if couplingPortDetails_node is not None:
            if couplingPortDetails_node.find('{*}SHORT-NAME') is None:
                self.__couplingPortDetails = CouplingPortDetails()._build(self, couplingPortDetails_node, file, '[couplingPortDetails_@]')
            else:
                self.__couplingPortDetails = CouplingPortDetails()._build(self, couplingPortDetails_node, file)

        plcaProps_node = self._node.find('{*}PLCA-PROPS')
        if plcaProps_node is not None:
            if plcaProps_node.find('{*}SHORT-NAME') is None:
                self.__plcaProps = PlcaProps()._build(self, plcaProps_node, file, '[plcaProps_@]')
            else:
                self.__plcaProps = PlcaProps()._build(self, plcaProps_node, file)

        vlanMemberships_nodes = self._node.findall('{*}VLAN-MEMBERSHIPS/*')
        for vlanMemberships_node in vlanMemberships_nodes:
            buildvlanMemberships_node = None
            if vlanMemberships_node.find('{*}SHORT-NAME') is None:
                buildvlanMemberships_node = VlanMembership()._build(self, vlanMemberships_node, file, '[vlanMemberships_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildvlanMemberships_node = VlanMembership()._build(self, vlanMemberships_node, file)
            self.__vlanMemberships[(buildvlanMemberships_node)] = None

        variationPoint_node = self._node.find('{*}VARIATION-POINT')
        if variationPoint_node is not None:
            if variationPoint_node.find('{*}SHORT-NAME') is None:
                self.__variationPoint = VariationPoint()._build(self, variationPoint_node, file, '[variationPoint_@]')
            else:
                self.__variationPoint = VariationPoint()._build(self, variationPoint_node, file)

        return self

    def _resolve_references(self):
        super()._resolve_references()
        defaultVlan_node = self._node.find('{*}DEFAULT-VLAN-REF')
        if defaultVlan_node is not None and defaultVlan_node.text is not None:
            refText = ''
            refBase = defaultVlan_node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + defaultVlan_node.text
            self.__defaultVlan_as_string = refText
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__defaultVlan = ref_value

        macMulticastAddress_nodes = self._node.findall('{*}MAC-MULTICAST-ADDRESS-REFS/*')
        for node in macMulticastAddress_nodes:
            if node.text is None:
                continue
            refText = ''
            refBase = node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + node.text
            self.__macMulticastAddress_as_string[refText] = None
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__macMulticastAddress[ref_value] = None

        pncMappings_nodes = self._node.findall('{*}PNC-MAPPING-REFS/*')
        for node in pncMappings_nodes:
            if node.text is None:
                continue
            refText = ''
            refBase = node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + node.text
            self.__pncMappings_as_string[refText] = None
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__pncMappings[ref_value] = None

        vlanModifier_node = self._node.find('{*}VLAN-MODIFIER-REF')
        if vlanModifier_node is not None and vlanModifier_node.text is not None:
            refText = ''
            refBase = vlanModifier_node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + vlanModifier_node.text
            self.__vlanModifier_as_string = refText
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__vlanModifier = ref_value

        wakeupSleepOnDatalineConfig_node = self._node.find('{*}WAKEUP-SLEEP-ON-DATALINE-CONFIG-REF')
        if wakeupSleepOnDatalineConfig_node is not None and wakeupSleepOnDatalineConfig_node.text is not None:
            refText = ''
            refBase = wakeupSleepOnDatalineConfig_node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + wakeupSleepOnDatalineConfig_node.text
            self.__wakeupSleepOnDatalineConfig_as_string = refText
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__wakeupSleepOnDatalineConfig = ref_value


