class CouplingElement(FibexElement):
    """
    A CouplingElement is used to connect EcuInstances to the VLAN of an EthernetCluster. CouplingElements can reach from a simple hub to a complex managed switch or even devices with functionalities in higher layers. A CouplingElement that is not related to an EcuInstance occurs as a dedicated single device.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'COUPLING-ELEMENT'
        self._node = etree.Element('COUPLING-ELEMENT')
        self.__couplingType = None
        self.__communicationCluster = None
        self.__communicationCluster_as_string = None
        self.__couplingPorts = {} # using dict to preserve the order of elements
        self.__ecuInstance = None
        self.__ecuInstance_as_string = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        couplingType_value = AutosarNode._get_node_text(node,'COUPLING-TYPE')
        if couplingType_value is not None:
            self.__couplingType = CouplingElementEnum.get(couplingType_value)

        refCounter = 0
        couplingPorts_nodes = self._node.findall('{*}COUPLING-PORTS/*')
        for couplingPorts_node in couplingPorts_nodes:
            buildcouplingPorts_node = None
            if couplingPorts_node.find('{*}SHORT-NAME') is None:
                buildcouplingPorts_node = CouplingPort()._build(self, couplingPorts_node, file, '[couplingPorts_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildcouplingPorts_node = CouplingPort()._build(self, couplingPorts_node, file)
            self.__couplingPorts[(buildcouplingPorts_node)] = None

        return self

    def _resolve_references(self):
        super()._resolve_references()
        communicationCluster_node = self._node.find('{*}COMMUNICATION-CLUSTER-REF')
        if communicationCluster_node is not None and communicationCluster_node.text is not None:
            refText = ''
            refBase = communicationCluster_node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + communicationCluster_node.text
            self.__communicationCluster_as_string = refText
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__communicationCluster = ref_value

        ecuInstance_node = self._node.find('{*}ECU-INSTANCE-REF')
        if ecuInstance_node is not None and ecuInstance_node.text is not None:
            refText = ''
            refBase = ecuInstance_node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + ecuInstance_node.text
            self.__ecuInstance_as_string = refText
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__ecuInstance = ref_value


