class FlexrayFifoConfiguration(ARObject):
    """
    One First In First Out (FIFO) queued receive structure, defining the admittance criteria to the FIFO, and mandating the ability to admit messages into the FIFO based on Message Id filtering criteria.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'FLEXRAY-FIFO-CONFIGURATION'
        self._node = etree.Element('FLEXRAY-FIFO-CONFIGURATION')
        self.__admitWithoutMessageId = None
        self.__baseCycle = None
        self.__cycleRepetition = None
        self.__fifoDepth = None
        self.__msgIdMask = None
        self.__msgIdMatch = None
        self.__channel = None
        self.__channel_as_string = None
        self.__fifoRanges = {} # using dict to preserve the order of elements

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        admitWithoutMessageId_value = AutosarNode._get_node_text(node,'ADMIT-WITHOUT-MESSAGE-ID')
        if admitWithoutMessageId_value is not None:
            self.__admitWithoutMessageId = datatype_utils.get_bool_value(admitWithoutMessageId_value)

        baseCycle_value = AutosarNode._get_node_text(node,'BASE-CYCLE')
        if baseCycle_value is not None:
            self.__baseCycle = datatype_utils.get_int_value(baseCycle_value)

        cycleRepetition_value = AutosarNode._get_node_text(node,'CYCLE-REPETITION')
        if cycleRepetition_value is not None:
            self.__cycleRepetition = datatype_utils.get_int_value(cycleRepetition_value)

        fifoDepth_value = AutosarNode._get_node_text(node,'FIFO-DEPTH')
        if fifoDepth_value is not None:
            self.__fifoDepth = datatype_utils.get_int_value(fifoDepth_value)

        msgIdMask_value = AutosarNode._get_node_text(node,'MSG-ID-MASK')
        if msgIdMask_value is not None:
            self.__msgIdMask = datatype_utils.get_int_value(msgIdMask_value)

        msgIdMatch_value = AutosarNode._get_node_text(node,'MSG-ID-MATCH')
        if msgIdMatch_value is not None:
            self.__msgIdMatch = datatype_utils.get_int_value(msgIdMatch_value)

        refCounter = 0
        fifoRanges_nodes = self._node.findall('{*}FIFO-RANGES/*')
        for fifoRanges_node in fifoRanges_nodes:
            buildfifoRanges_node = None
            if fifoRanges_node.find('{*}SHORT-NAME') is None:
                buildfifoRanges_node = FlexrayFifoRange()._build(self, fifoRanges_node, file, '[fifoRanges_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildfifoRanges_node = FlexrayFifoRange()._build(self, fifoRanges_node, file)
            self.__fifoRanges[(buildfifoRanges_node)] = None

        return self

    def _resolve_references(self):
        super()._resolve_references()
        channel_node = self._node.find('{*}CHANNEL-REF')
        if channel_node is not None and channel_node.text is not None:
            refText = ''
            refBase = channel_node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + channel_node.text
            self.__channel_as_string = refText
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__channel = ref_value


