class LinScheduleTable(Identifiable):
    """
    The master task (in the master node) transmits frame headers based on a schedule table. The schedule table specifies the identifiers for each header and the interval between the start of a frame and the start of the following frame.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'LIN-SCHEDULE-TABLE'
        self._node = etree.Element('LIN-SCHEDULE-TABLE')
        self.__resumePosition = None
        self.__runMode = None
        self.__tableEntries = {} # using dict to preserve the order of elements
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        resumePosition_value = AutosarNode._get_node_text(node,'RESUME-POSITION')
        if resumePosition_value is not None:
            self.__resumePosition = ResumePosition.get(resumePosition_value)

        runMode_value = AutosarNode._get_node_text(node,'RUN-MODE')
        if runMode_value is not None:
            self.__runMode = RunMode.get(runMode_value)

        refCounter = 0
        tableEntries_obj_dict = {}
        tableEntries_obj_dict['APPLICATION-ENTRY'] = 'ApplicationEntry'
        tableEntries_obj_dict['ASSIGN-FRAME-ID'] = 'AssignFrameId'
        tableEntries_obj_dict['ASSIGN-FRAME-ID-RANGE'] = 'AssignFrameIdRange'
        tableEntries_obj_dict['ASSIGN-NAD'] = 'AssignNad'
        tableEntries_obj_dict['CONDITIONAL-CHANGE-NAD'] = 'ConditionalChangeNad'
        tableEntries_obj_dict['DATA-DUMP-ENTRY'] = 'DataDumpEntry'
        tableEntries_obj_dict['SAVE-CONFIGURATION-ENTRY'] = 'SaveConfigurationEntry'
        tableEntries_obj_dict['UNASSIGN-FRAME-ID'] = 'UnassignFrameId'
        tableEntries_obj_dict['FREE-FORMAT'] = 'FreeFormat'
        tableEntries_nodes = self._node.findall('{*}TABLE-ENTRYS/*')
        for tableEntries_node in tableEntries_nodes:
            buildtableEntries_node = None
            if tableEntries_node.find('{*}SHORT-NAME') is None:
                buildtableEntries_node = __str_to_class__(tableEntries_obj_dict[etree.QName(tableEntries_node).localname])()._build(self, tableEntries_node, file, '[tableEntries_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildtableEntries_node = __str_to_class__(tableEntries_obj_dict[etree.QName(tableEntries_node).localname])()._build(self, tableEntries_node, file)
            self.__tableEntries[buildtableEntries_node] = None

        variationPoint_node = self._node.find('{*}VARIATION-POINT')
        if variationPoint_node is not None:
            if variationPoint_node.find('{*}SHORT-NAME') is None:
                self.__variationPoint = VariationPoint()._build(self, variationPoint_node, file, '[variationPoint_@]')
            else:
                self.__variationPoint = VariationPoint()._build(self, variationPoint_node, file)

        return self

    def get_resumePosition(self) -> ResumePosition:
        return self.__resumePosition

    def set_resumePosition(self, value: ResumePosition) -> None:
        self.__resumePosition = value
        XDT.mark_attribute_dirty('resumePosition', self)

    def get_runMode(self) -> RunMode:
        return self.__runMode

    def set_runMode(self, value: RunMode) -> None:
        self.__runMode = value
        XDT.mark_attribute_dirty('runMode', self)

    def get_tableEntries(self) -> list[ScheduleTableEntry]:
        return list(self.__tableEntries.keys())

    def add_tableEntrie(self, value: ScheduleTableEntry) -> None:
        """
        Adds a single value to the tableEntries
        """
        if value is not None:
            if isinstance(value, Referrable) and any(v.name == value.name for v in self.__tableEntries.keys()):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, ScheduleTableEntry) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of ScheduleTableEntry or its sub-classes'.format(value))
            self.__tableEntries[value] = None
            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            value._parent = self #set parent
            value.file = self.file
            if value.name is not None:
                value._update_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'ScheduleTableEntry_@' + str(len(self.get_children()))) #updates the path
            XDT.mark_dirty(value, self, attributesToMakeDirty = ['timestamp', 'checksum'])

    def set_tableEntries(self, values: list[ScheduleTableEntry]) -> None:
        """
        Adds a list of ref value to the tableEntries
        """
        for value in values:
            self.add_tableEntrie(value)

    def remove_tableEntrie(self, value: ScheduleTableEntry) -> None:
        """
        Removes a single value from tableEntries
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__tableEntries.pop(value)
            value._parent = None #No parent
            value._update_path() #resets the path
            value._node.getparent().remove(value._node)

    def remove_tableEntries(self, values: list[ScheduleTableEntry]) -> None:
        """
        Removes a list of value from tableEntries
        """
        for value in values:
            self.remove_tableEntrie(value)

    def get_variationPoint(self) -> VariationPoint:
        return self.__variationPoint

    def set_variationPoint(self, value: VariationPoint) -> None:
        """
        Adds a single value to the variationPoint
        """
        if value is not None:
            if isinstance(value, VariationPoint) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of VariationPoint or its sub-classes'.format(value))
            #if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            self.__variationPoint = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._build_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'VariationPoint_@' + str(len(self.get_children()))) #updates the path
