class LinSlave(LinCommunicationController):
    """
    Describing the properties of the referring ecu as a LIN slave.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'LIN-SLAVE'
        self._node = etree.Element('LIN-SLAVE')
        self.__linSlaveVariants = {} # using dict to preserve the order of elements

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        refCounter = 0
        linSlaveVariants_nodes = self._node.findall('{*}LIN-SLAVE-VARIANTS/*')
        for linSlaveVariants_node in linSlaveVariants_nodes:
            buildlinSlaveVariants_node = None
            if linSlaveVariants_node.find('{*}SHORT-NAME') is None:
                buildlinSlaveVariants_node = LinSlaveConditional()._build(self, linSlaveVariants_node, file, '[linSlaveVariants_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildlinSlaveVariants_node = LinSlaveConditional()._build(self, linSlaveVariants_node, file)
            self.__linSlaveVariants[(buildlinSlaveVariants_node)] = None

        return self

    def get_linSlaveVariants(self) -> list[LinSlaveConditional]:
        return list(self.__linSlaveVariants.keys())

    def add_linSlaveVariant(self, value: LinSlaveConditional) -> None:
        """
        Adds a single value to the linSlaveVariants
        """
        if value is not None:
            if isinstance(value, Referrable) and any(v.name == value.name for v in self.__linSlaveVariants.keys()):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, LinSlaveConditional) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of LinSlaveConditional or its sub-classes'.format(value))
            self.__linSlaveVariants[value] = None
            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            value._parent = self #set parent
            value.file = self.file
            if value.name is not None:
                value._update_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'LinSlaveConditional_@' + str(len(self.get_children()))) #updates the path
            XDT.mark_dirty(value, self, attributesToMakeDirty = ['variantId', 'supplierId', 'saveConfiguration', 'nasTimeout', 'initialNad', 'functionId', 'configuredNad', 'assignNad', 'protocolVersion', 'wakeUpByControllerSupported', 'timestamp', 'checksum'])

    def set_linSlaveVariants(self, values: list[LinSlaveConditional]) -> None:
        """
        Adds a list of ref value to the linSlaveVariants
        """
        for value in values:
            self.add_linSlaveVariant(value)

    def remove_linSlaveVariant(self, value: LinSlaveConditional) -> None:
        """
        Removes a single value from linSlaveVariants
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__linSlaveVariants.pop(value)
            value._parent = None #No parent
            value._update_path() #resets the path
            value._node.getparent().remove(value._node)

    def remove_linSlaveVariants(self, values: list[LinSlaveConditional]) -> None:
        """
        Removes a list of value from linSlaveVariants
        """
        for value in values:
            self.remove_linSlaveVariant(value)

    def new_LinSlaveVariant(self, name: str=None) -> LinSlaveConditional:
        """
        Creates a new LinSlaveConditional under the LinSlave.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        LinSlaveConditional_obj = LinSlaveConditional()
        if isinstance(LinSlaveConditional_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        LinSlaveConditional_obj.name = name if isinstance(LinSlaveConditional_obj, Referrable) else None
        self.add_linSlaveVariant(LinSlaveConditional_obj)
        if isinstance(LinSlaveConditional_obj, Referrable):
            LinSlaveConditional_obj.set_shortName(name)
        return LinSlaveConditional_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        children.extend(self.__linSlaveVariants)
        return children



    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        return property_values

    def _update_path(self):
        """
        Updates the path of the LinSlave and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()


    def _save_contents(self):
        """
        Saves the content of LinSlave node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_LinCommunicationController()
        if len(self.__linSlaveVariants) > 0:
            linSlaveVariants_values = AutosarNode._add_or_get_xml_node(self._node, 'LIN-SLAVE-VARIANTS', create_after_nodes = self._insert_after_tags + ['VARIATION-POINT', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'] + self._insert_after_tags)
            for value in self.__linSlaveVariants:
                if XDT.is_dirty(value) and value.file == self.file:
                    value._save_contents()
                    if value._node.getparent() is None or value._node.getparent() != linSlaveVariants_values:
                        linSlaveVariants_values.append(value._node)


