class Gateway(FibexElement):
    """
    A gateway is an ECU that is connected to two or more clusters (channels, but not redundant), and performs a frame, Pdu or signal mapping between them.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'GATEWAY'
        self._node = etree.Element('GATEWAY')
        self.__ecu = None
        self.__ecu_as_string = None
        self.__frameMappings = {} # using dict to preserve the order of elements
        self.__iPduMappings = {} # using dict to preserve the order of elements
        self.__signalMappings = {} # using dict to preserve the order of elements

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        refCounter = 0
        frameMappings_nodes = self._node.findall('{*}FRAME-MAPPINGS/*')
        for frameMappings_node in frameMappings_nodes:
            buildframeMappings_node = None
            if frameMappings_node.find('{*}SHORT-NAME') is None:
                buildframeMappings_node = FrameMapping()._build(self, frameMappings_node, file, '[frameMappings_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildframeMappings_node = FrameMapping()._build(self, frameMappings_node, file)
            self.__frameMappings[(buildframeMappings_node)] = None

        iPduMappings_nodes = self._node.findall('{*}I-PDU-MAPPINGS/*')
        for iPduMappings_node in iPduMappings_nodes:
            buildiPduMappings_node = None
            if iPduMappings_node.find('{*}SHORT-NAME') is None:
                buildiPduMappings_node = IPduMapping()._build(self, iPduMappings_node, file, '[iPduMappings_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildiPduMappings_node = IPduMapping()._build(self, iPduMappings_node, file)
            self.__iPduMappings[(buildiPduMappings_node)] = None

        signalMappings_nodes = self._node.findall('{*}SIGNAL-MAPPINGS/*')
        for signalMappings_node in signalMappings_nodes:
            buildsignalMappings_node = None
            if signalMappings_node.find('{*}SHORT-NAME') is None:
                buildsignalMappings_node = ISignalMapping()._build(self, signalMappings_node, file, '[signalMappings_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildsignalMappings_node = ISignalMapping()._build(self, signalMappings_node, file)
            self.__signalMappings[(buildsignalMappings_node)] = None

        return self

    def _resolve_references(self):
        super()._resolve_references()
        ecu_node = self._node.find('{*}ECU-REF')
        if ecu_node is not None and ecu_node.text is not None:
            refText = ''
            refBase = ecu_node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + ecu_node.text
            self.__ecu_as_string = refText
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__ecu = ref_value


