class PduMappingDefaultValue(ARObject):
    """
    Default Value which will be distributed if no I-Pdu has been received since last sending.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'PDU-MAPPING-DEFAULT-VALUE'
        self._node = etree.Element('PDU-MAPPING-DEFAULT-VALUE')
        self.__defaultValueElements = {} # using dict to preserve the order of elements

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        refCounter = 0
        defaultValueElements_nodes = self._node.findall('{*}DEFAULT-VALUE-ELEMENTS/*')
        for defaultValueElements_node in defaultValueElements_nodes:
            builddefaultValueElements_node = None
            if defaultValueElements_node.find('{*}SHORT-NAME') is None:
                builddefaultValueElements_node = DefaultValueElement()._build(self, defaultValueElements_node, file, '[defaultValueElements_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                builddefaultValueElements_node = DefaultValueElement()._build(self, defaultValueElements_node, file)
            self.__defaultValueElements[(builddefaultValueElements_node)] = None

        return self

    def get_defaultValueElements(self) -> list[DefaultValueElement]:
        return list(self.__defaultValueElements.keys())

    def add_defaultValueElement(self, value: DefaultValueElement) -> None:
        """
        Adds a single value to the defaultValueElements
        """
        if value is not None:
            if isinstance(value, Referrable) and any(v.name == value.name for v in self.__defaultValueElements.keys()):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, DefaultValueElement) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of DefaultValueElement or its sub-classes'.format(value))
            self.__defaultValueElements[value] = None
            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            value._parent = self #set parent
            value.file = self.file
            if value.name is not None:
                value._update_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'DefaultValueElement_@' + str(len(self.get_children()))) #updates the path
            XDT.mark_dirty(value, self, attributesToMakeDirty = ['timestamp', 'checksum'])

    def set_defaultValueElements(self, values: list[DefaultValueElement]) -> None:
        """
        Adds a list of ref value to the defaultValueElements
        """
        for value in values:
            self.add_defaultValueElement(value)

    def remove_defaultValueElement(self, value: DefaultValueElement) -> None:
        """
        Removes a single value from defaultValueElements
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__defaultValueElements.pop(value)
            value._parent = None #No parent
            value._update_path() #resets the path
            value._node.getparent().remove(value._node)

    def remove_defaultValueElements(self, values: list[DefaultValueElement]) -> None:
        """
        Removes a list of value from defaultValueElements
        """
        for value in values:
            self.remove_defaultValueElement(value)

    def new_DefaultValueElement(self, name: str=None) -> DefaultValueElement:
        """
        Creates a new DefaultValueElement under the PduMappingDefaultValue.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        DefaultValueElement_obj = DefaultValueElement()
        if isinstance(DefaultValueElement_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        DefaultValueElement_obj.name = name if isinstance(DefaultValueElement_obj, Referrable) else None
        self.add_defaultValueElement(DefaultValueElement_obj)
        if isinstance(DefaultValueElement_obj, Referrable):
            DefaultValueElement_obj.set_shortName(name)
        return DefaultValueElement_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        children.extend(self.__defaultValueElements)
        return children



    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        return property_values

    def _update_path(self):
        """
        Updates the path of the PduMappingDefaultValue and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()


    def _save_contents(self):
        """
        Saves the content of PduMappingDefaultValue node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_ARObject()
        if len(self.__defaultValueElements) > 0:
            defaultValueElements_values = AutosarNode._add_or_get_xml_node(self._node, 'DEFAULT-VALUE-ELEMENTS', create_after_nodes = self._insert_after_tags + ['T', 'S'] + self._insert_after_tags)
            for value in self.__defaultValueElements:
                if XDT.is_dirty(value) and value.file == self.file:
                    value._save_contents()
                    if value._node.getparent() is None or value._node.getparent() != defaultValueElements_values:
                        defaultValueElements_values.append(value._node)


