class SignalIPduReplication(ARObject):
    """
    PduReplication is a form of redundancy where the data content of one ISignalIPdu (source) is transmitted inside a set of replica ISignalIPdus. These ISignalIPdus (copies) have different Pdu IDs, identical PduCounters, identical data content and are transmitted with the same frequency.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'SIGNAL-I-PDU-REPLICATION'
        self._node = etree.Element('SIGNAL-I-PDU-REPLICATION')
        self.__pduReplicationVoting = None
        self.__replicaPdus = {} # using dict to preserve the order of elements
        self.__replicaPdus_as_string = {} # using dict to preserve the order of elements
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        pduReplicationVoting_value = AutosarNode._get_node_text(node,'PDU-REPLICATION-VOTING')
        if pduReplicationVoting_value is not None:
            self.__pduReplicationVoting = datatype_utils.get_int_value(pduReplicationVoting_value)

        variationPoint_node = self._node.find('{*}VARIATION-POINT')
        if variationPoint_node is not None:
            if variationPoint_node.find('{*}SHORT-NAME') is None:
                self.__variationPoint = VariationPoint()._build(self, variationPoint_node, file, '[variationPoint_@]')
            else:
                self.__variationPoint = VariationPoint()._build(self, variationPoint_node, file)

        return self

    def _resolve_references(self):
        super()._resolve_references()
        replicaPdus_nodes = self._node.findall('{*}REPLICA-PDUS-REFS/*')
        for node in replicaPdus_nodes:
            if node.text is None:
                continue
            refText = ''
            refBase = node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + node.text
            self.__replicaPdus_as_string[refText] = None
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
