class ContainerIPdu(IPdu):
    """
    Allows to collect several IPdus in one ContainerIPdu based on the headerType.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'CONTAINER-I-PDU'
        self._node = etree.Element('CONTAINER-I-PDU')
        self.__containerTimeout = None
        self.__containerTrigger = None
        self.__headerType = None
        self.__minimumRxContainerQueueSize = None
        self.__minimumTxContainerQueueSize = None
        self.__rxAcceptContainedIPdu = None
        self.__thresholdSize = None
        self.__unusedBitPattern = None
        self.__containedPduTriggerings = {} # using dict to preserve the order of elements
        self.__containedPduTriggerings_as_string = {} # using dict to preserve the order of elements

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        containerTimeout_value = AutosarNode._get_node_text(node,'CONTAINER-TIMEOUT')
        if containerTimeout_value is not None:
            self.__containerTimeout = datatype_utils.get_float_value(containerTimeout_value)

        containerTrigger_value = AutosarNode._get_node_text(node,'CONTAINER-TRIGGER')
        if containerTrigger_value is not None:
            self.__containerTrigger = ContainerIPduTriggerEnum.get(containerTrigger_value)

        headerType_value = AutosarNode._get_node_text(node,'HEADER-TYPE')
        if headerType_value is not None:
            self.__headerType = ContainerIPduHeaderTypeEnum.get(headerType_value)

        minimumRxContainerQueueSize_value = AutosarNode._get_node_text(node,'MINIMUM-RX-CONTAINER-QUEUE-SIZE')
        if minimumRxContainerQueueSize_value is not None:
            self.__minimumRxContainerQueueSize = datatype_utils.get_int_value(minimumRxContainerQueueSize_value)

        minimumTxContainerQueueSize_value = AutosarNode._get_node_text(node,'MINIMUM-TX-CONTAINER-QUEUE-SIZE')
        if minimumTxContainerQueueSize_value is not None:
            self.__minimumTxContainerQueueSize = datatype_utils.get_int_value(minimumTxContainerQueueSize_value)

        rxAcceptContainedIPdu_value = AutosarNode._get_node_text(node,'RX-ACCEPT-CONTAINED-I-PDU')
        if rxAcceptContainedIPdu_value is not None:
            self.__rxAcceptContainedIPdu = RxAcceptContainedIPduEnum.get(rxAcceptContainedIPdu_value)

        thresholdSize_value = AutosarNode._get_node_text(node,'THRESHOLD-SIZE')
        if thresholdSize_value is not None:
            self.__thresholdSize = datatype_utils.get_int_value(thresholdSize_value)

        unusedBitPattern_value = AutosarNode._get_node_text(node,'UNUSED-BIT-PATTERN')
        if unusedBitPattern_value is not None:
            self.__unusedBitPattern = datatype_utils.get_int_value(unusedBitPattern_value)

        return self

    def _resolve_references(self):
        super()._resolve_references()
        containedPduTriggerings_nodes = self._node.findall('{*}CONTAINED-PDU-TRIGGERING-REFS/*')
        for node in containedPduTriggerings_nodes:
            if node.text is None:
                continue
            refText = ''
            refBase = node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + node.text
            self.__containedPduTriggerings_as_string[refText] = None
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__containedPduTriggerings[ref_value] = None


