class TlsCryptoCipherSuite(Identifiable):
    """
    This meta-class represents a cipher suite for describing cryptographic operations in the context of establishing a connection of ApplicationEndpoints that is protected by TLS.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'TLS-CRYPTO-CIPHER-SUITE'
        self._node = etree.Element('TLS-CRYPTO-CIPHER-SUITE')
        self.__priority = None
        self.__version = None
        self.__authentication = None
        self.__authentication_as_string = None
        self.__certificate = None
        self.__certificate_as_string = None
        self.__encryption = None
        self.__encryption_as_string = None
        self.__keyExchanges = {} # using dict to preserve the order of elements
        self.__keyExchanges_as_string = {} # using dict to preserve the order of elements
        self.__preSharedKey = None
        self.__preSharedKey_as_string = None
        self.__pskIdentity = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        priority_value = AutosarNode._get_node_text(node,'PRIORITY')
        if priority_value is not None:
            self.__priority = datatype_utils.get_int_value(priority_value)

        version_value = AutosarNode._get_node_text(node,'VERSION')
        if version_value is not None:
            self.__version = TlsVersionEnum.get(version_value)

        pskIdentity_node = self._node.find('{*}PSK-IDENTITY')
        if pskIdentity_node is not None:
            if pskIdentity_node.find('{*}SHORT-NAME') is None:
                self.__pskIdentity = TlsPskIdentity()._build(self, pskIdentity_node, file, '[pskIdentity_@]')
            else:
                self.__pskIdentity = TlsPskIdentity()._build(self, pskIdentity_node, file)

        return self

    def _resolve_references(self):
        super()._resolve_references()
        authentication_node = self._node.find('{*}AUTHENTICATION-REF')
        if authentication_node is not None and authentication_node.text is not None:
            refText = ''
            refBase = authentication_node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + authentication_node.text
            self.__authentication_as_string = refText
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__authentication = ref_value

        certificate_node = self._node.find('{*}CERTIFICATE-REF')
        if certificate_node is not None and certificate_node.text is not None:
            refText = ''
            refBase = certificate_node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + certificate_node.text
            self.__certificate_as_string = refText
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__certificate = ref_value

        encryption_node = self._node.find('{*}ENCRYPTION-REF')
        if encryption_node is not None and encryption_node.text is not None:
            refText = ''
            refBase = encryption_node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + encryption_node.text
            self.__encryption_as_string = refText
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__encryption = ref_value

        keyExchanges_nodes = self._node.findall('{*}KEY-EXCHANGE-REFS/*')
        for node in keyExchanges_nodes:
            if node.text is None:
                continue
            refText = ''
            refBase = node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + node.text
            self.__keyExchanges_as_string[refText] = None
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__keyExchanges[ref_value] = None

        preSharedKey_node = self._node.find('{*}PRE-SHARED-KEY-REF')
        if preSharedKey_node is not None and preSharedKey_node.text is not None:
            refText = ''
            refBase = preSharedKey_node.attrib.get('BASE')
