class ComponentClustering(MappingConstraint):
    """
    Constraint that forces the mapping of all referenced SW component instances  to the same ECU, Core, Partition depending on the defined mappingScope attribute.  If mappingScope is not specified then mappingScopeEcu shall be assumed.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'COMPONENT-CLUSTERING'
        self._node = etree.Element('COMPONENT-CLUSTERING')
        self.__mappingScope = None
        self.__clusteredComponents = {} # using dict to preserve the order of elements

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        mappingScope_value = AutosarNode._get_node_text(node,'MAPPING-SCOPE')
        if mappingScope_value is not None:
            self.__mappingScope = MappingScopeEnum.get(mappingScope_value)

        refCounter = 0
        clusteredComponents_nodes = self._node.findall('{*}CLUSTERED-COMPONENT-IREFS/*')
        for clusteredComponents_node in clusteredComponents_nodes:
            buildclusteredComponents_node = None
            if clusteredComponents_node.find('{*}SHORT-NAME') is None:
                buildclusteredComponents_node = ComponentInSystemInstanceRef()._build(self, clusteredComponents_node, file, '[clusteredComponents_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildclusteredComponents_node = ComponentInSystemInstanceRef()._build(self, clusteredComponents_node, file)
            self.__clusteredComponents[(buildclusteredComponents_node)] = None

        return self

    def get_mappingScope(self) -> MappingScopeEnum:
        return self.__mappingScope

    def set_mappingScope(self, value: MappingScopeEnum) -> None:
        self.__mappingScope = value
        XDT.mark_attribute_dirty('mappingScope', self)

    def get_clusteredComponents(self) -> list[ComponentInSystemInstanceRef]:
        return list(self.__clusteredComponents.keys())

    def add_clusteredComponent(self, value: ComponentInSystemInstanceRef) -> None:
        """
        Adds a single value to the clusteredComponents
        """
        if value is not None:
            if isinstance(value, Referrable) and any(v.name == value.name for v in self.__clusteredComponents.keys()):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, ComponentInSystemInstanceRef) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of ComponentInSystemInstanceRef or its sub-classes'.format(value))
            self.__clusteredComponents[value] = None
            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            value._parent = self #set parent
            value.file = self.file
            if value.name is not None:
                value._update_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'ComponentInSystemInstanceRef_@' + str(len(self.get_children()))) #updates the path
            XDT.mark_dirty(value, self, attributesToMakeDirty = ['timestamp', 'checksum'])

    def set_clusteredComponents(self, values: list[ComponentInSystemInstanceRef]) -> None:
        """
        Adds a list of ref value to the clusteredComponents
        """
        for value in values:
            self.add_clusteredComponent(value)

    def remove_clusteredComponent(self, value: ComponentInSystemInstanceRef) -> None:
        """
        Removes a single value from clusteredComponents
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__clusteredComponents.pop(value)
            value._parent = None #No parent
            value._update_path() #resets the path
            value._node.getparent().remove(value._node)

    def remove_clusteredComponents(self, values: list[ComponentInSystemInstanceRef]) -> None:
        """
        Removes a list of value from clusteredComponents
        """
        for value in values:
            self.remove_clusteredComponent(value)

    def new_ClusteredComponent(self, name: str=None) -> ComponentInSystemInstanceRef:
        """
        Creates a new ComponentInSystemInstanceRef under the ComponentClustering.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        ComponentInSystemInstanceRef_obj = ComponentInSystemInstanceRef()
        if isinstance(ComponentInSystemInstanceRef_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        ComponentInSystemInstanceRef_obj.name = name if isinstance(ComponentInSystemInstanceRef_obj, Referrable) else None
        self.add_clusteredComponent(ComponentInSystemInstanceRef_obj)
        if isinstance(ComponentInSystemInstanceRef_obj, Referrable):
            ComponentInSystemInstanceRef_obj.set_shortName(name)
        return ComponentInSystemInstanceRef_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        children.extend(self.__clusteredComponents)
        return children



    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['MappingScope'] = self.__mappingScope
        return property_values

    def _update_path(self):
        """
        Updates the path of the ComponentClustering and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()


    def _save_contents(self):
        """
        Saves the content of ComponentClustering node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_MappingConstraint()
        if len(self.__clusteredComponents) > 0:
            clusteredComponents_values = AutosarNode._add_or_get_xml_node(self._node, 'CLUSTERED-COMPONENT-IREFS', create_after_nodes = self._insert_after_tags + ['VARIATION-POINT', 'INTRODUCTION', 'T', 'S'] + self._insert_after_tags)
            for value in self.__clusteredComponents:
                if XDT.is_dirty(value) and value.file == self.file:
                    value._node.tag = 'CLUSTERED-COMPONENT-IREF'
			    
                    value._save_contents()
                    if value._node.getparent() is None or value._node.getparent() != clusteredComponents_values:
                        clusteredComponents_values.append(value._node)

        if XDT.is_attribute_dirty('mappingScope', self):
            if self.__mappingScope is None:
                AutosarNode._remove_xml_node_if_exists(self._node, 'MAPPING-SCOPE')
            else:
                mappingScope_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'MAPPING-SCOPE', create_after_nodes = ['CLUSTERED-COMPONENT-IREFS', 'VARIATION-POINT', 'INTRODUCTION', 'T', 'S'] + self._insert_after_tags)
                mappingScope_xml_node.text = self.__mappingScope.literal


