class EcuResourceEstimation(ARObject):
    """
    Resource estimations for RTE and BSW of a single ECU instance.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'ECU-RESOURCE-ESTIMATION'
        self._node = etree.Element('ECU-RESOURCE-ESTIMATION')
        self.__introduction = None
        self.__bswResourceEstimation = None
        self.__ecuInstance = None
        self.__ecuInstance_as_string = None
        self.__rteResourceEstimation = None
        self.__swCompToEcuMappings = {} # using dict to preserve the order of elements
        self.__swCompToEcuMappings_as_string = {} # using dict to preserve the order of elements
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        introduction_node = self._node.find('{*}INTRODUCTION')
        if introduction_node is not None:
            if introduction_node.find('{*}SHORT-NAME') is None:
                self.__introduction = DocumentationBlock()._build(self, introduction_node, file, '[introduction_@]')
            else:
                self.__introduction = DocumentationBlock()._build(self, introduction_node, file)

        bswResourceEstimation_node = self._node.find('{*}BSW-RESOURCE-ESTIMATION')
        if bswResourceEstimation_node is not None:
            if bswResourceEstimation_node.find('{*}SHORT-NAME') is None:
                self.__bswResourceEstimation = ResourceConsumption()._build(self, bswResourceEstimation_node, file, '[bswResourceEstimation_@]')
            else:
                self.__bswResourceEstimation = ResourceConsumption()._build(self, bswResourceEstimation_node, file)

        rteResourceEstimation_node = self._node.find('{*}RTE-RESOURCE-ESTIMATION')
        if rteResourceEstimation_node is not None:
            if rteResourceEstimation_node.find('{*}SHORT-NAME') is None:
                self.__rteResourceEstimation = ResourceConsumption()._build(self, rteResourceEstimation_node, file, '[rteResourceEstimation_@]')
            else:
                self.__rteResourceEstimation = ResourceConsumption()._build(self, rteResourceEstimation_node, file)

        variationPoint_node = self._node.find('{*}VARIATION-POINT')
        if variationPoint_node is not None:
            if variationPoint_node.find('{*}SHORT-NAME') is None:
                self.__variationPoint = VariationPoint()._build(self, variationPoint_node, file, '[variationPoint_@]')
            else:
                self.__variationPoint = VariationPoint()._build(self, variationPoint_node, file)

        return self

    def _resolve_references(self):
        super()._resolve_references()
        ecuInstance_node = self._node.find('{*}ECU-INSTANCE-REF')
        if ecuInstance_node is not None and ecuInstance_node.text is not None:
            refText = ''
            refBase = ecuInstance_node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + ecuInstance_node.text
            self.__ecuInstance_as_string = refText
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
