            if isinstance(value, Referrable) and any(v.name == value.name for v in self.__txNmPdus.keys()):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, NmPdu) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of NmPdu or its sub-classes'.format(value))
