class NmCoordinator(ARObject):
    """
    A NM coordinator is an ECU, which is connected to at least two busses, and where the requirement exists that shutdown of NM of at least two of these busses (also referred to as coordinated busses) has to be performed synchronously.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'NM-COORDINATOR'
        self._node = etree.Element('NM-COORDINATOR')
        self.__index = None
        self.__nmActiveCoordinator = None
        self.__nmCoordSyncSupport = None
        self.__nmGlobalCoordinatorTime = None
        self.__nmShutdownDelayTimer = None
        self.__nmNodes = {} # using dict to preserve the order of elements
        self.__nmNodes_as_string = {} # using dict to preserve the order of elements

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        index_value = AutosarNode._get_node_text(node,'INDEX')
        if index_value is not None:
            self.__index = datatype_utils.get_int_value(index_value)

        nmActiveCoordinator_value = AutosarNode._get_node_text(node,'NM-ACTIVE-COORDINATOR')
        if nmActiveCoordinator_value is not None:
            self.__nmActiveCoordinator = datatype_utils.get_bool_value(nmActiveCoordinator_value)

        nmCoordSyncSupport_value = AutosarNode._get_node_text(node,'NM-COORD-SYNC-SUPPORT')
        if nmCoordSyncSupport_value is not None:
            self.__nmCoordSyncSupport = datatype_utils.get_bool_value(nmCoordSyncSupport_value)

        nmGlobalCoordinatorTime_value = AutosarNode._get_node_text(node,'NM-GLOBAL-COORDINATOR-TIME')
        if nmGlobalCoordinatorTime_value is not None:
            self.__nmGlobalCoordinatorTime = datatype_utils.get_float_value(nmGlobalCoordinatorTime_value)

        nmShutdownDelayTimer_value = AutosarNode._get_node_text(node,'NM-SHUTDOWN-DELAY-TIMER')
        if nmShutdownDelayTimer_value is not None:
            self.__nmShutdownDelayTimer = datatype_utils.get_float_value(nmShutdownDelayTimer_value)

        return self

    def _resolve_references(self):
        super()._resolve_references()
        nmNodes_nodes = self._node.findall('{*}NM-NODE-REFS/*')
        for node in nmNodes_nodes:
            if node.text is None:
                continue
            refText = ''
            refBase = node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + node.text
            self.__nmNodes_as_string[refText] = None
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__nmNodes[ref_value] = None


    def get_index(self) -> int:
        return self.__index

    def set_index(self, value: int) -> None:
        self.__index = value
        XDT.mark_attribute_dirty('index', self)

    def get_nmActiveCoordinator(self) -> bool:
        return self.__nmActiveCoordinator

