class FlexrayNmClusterCoupling(NmClusterCoupling):
    """
    FlexRay attributes that are valid for each of the referenced (coupled) FlexRay clusters.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'FLEXRAY-NM-CLUSTER-COUPLING'
        self._node = etree.Element('FLEXRAY-NM-CLUSTER-COUPLING')
        self.__nmControlBitVectorEnabled = None
        self.__nmDataDisabled = None
        self.__nmScheduleVariant = None
        self.__coupledClusters = {} # using dict to preserve the order of elements
        self.__coupledClusters_as_string = {} # using dict to preserve the order of elements

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        nmControlBitVectorEnabled_value = AutosarNode._get_node_text(node,'NM-CONTROL-BIT-VECTOR-ENABLED')
        if nmControlBitVectorEnabled_value is not None:
            self.__nmControlBitVectorEnabled = datatype_utils.get_bool_value(nmControlBitVectorEnabled_value)

        nmDataDisabled_value = AutosarNode._get_node_text(node,'NM-DATA-DISABLED')
        if nmDataDisabled_value is not None:
            self.__nmDataDisabled = datatype_utils.get_bool_value(nmDataDisabled_value)

        nmScheduleVariant_value = AutosarNode._get_node_text(node,'NM-SCHEDULE-VARIANT')
        if nmScheduleVariant_value is not None:
            self.__nmScheduleVariant = FlexrayNmScheduleVariant.get(nmScheduleVariant_value)

        return self

    def _resolve_references(self):
        super()._resolve_references()
        coupledClusters_nodes = self._node.findall('{*}COUPLED-CLUSTER-REFS/*')
        for node in coupledClusters_nodes:
            if node.text is None:
                continue
            refText = ''
            refBase = node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + node.text
            self.__coupledClusters_as_string[refText] = None
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__coupledClusters[ref_value] = None


    def get_nmControlBitVectorEnabled(self) -> bool:
        return self.__nmControlBitVectorEnabled

    def set_nmControlBitVectorEnabled(self, value: bool) -> None:
        self.__nmControlBitVectorEnabled = value
        XDT.mark_attribute_dirty('nmControlBitVectorEnabled', self)

    def get_nmDataDisabled(self) -> bool:
        return self.__nmDataDisabled

    def set_nmDataDisabled(self, value: bool) -> None:
        self.__nmDataDisabled = value
        XDT.mark_attribute_dirty('nmDataDisabled', self)

    def get_nmScheduleVariant(self) -> FlexrayNmScheduleVariant:
        return self.__nmScheduleVariant

    def set_nmScheduleVariant(self, value: FlexrayNmScheduleVariant) -> None:
        self.__nmScheduleVariant = value
        XDT.mark_attribute_dirty('nmScheduleVariant', self)

    def get_coupledClusters(self) -> list[FlexrayNmCluster]:
        return list(self.__coupledClusters.keys())

    def get_coupledClusters_as_string(self) -> str:
        return list(self.__coupledClusters_as_string.keys())

    def add_coupledCluster(self, value: FlexrayNmCluster) -> None:
        """
        Adds a single value to the coupledClusters
        """
        if value is not None:
            if isinstance(value, Referrable) and any(v.name == value.name for v in self.__coupledClusters.keys()):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, FlexrayNmCluster) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of FlexrayNmCluster or its sub-classes'.format(value))
            self.__coupledClusters[value] = None
            value.referenced_by.add(self)
            XDT.mark_dirty(value, self)

    def set_coupledClusters(self, values: list[FlexrayNmCluster]) -> None:
        """
        Adds a list of ref value to the coupledClusters
        """
        for value in values:
            self.add_coupledCluster(value)

    def remove_coupledCluster(self, value: FlexrayNmCluster) -> None:
        """
        Removes a single value from coupledClusters
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__coupledClusters.pop(value)
            value.referenced_by.remove(self)

    def remove_coupledClusters(self, values: list[FlexrayNmCluster]) -> None:
        """
        Removes a list of value from coupledClusters
        """
        for value in values:
            self.remove_coupledCluster(value)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['NmControlBitVectorEnabled'] = self.__nmControlBitVectorEnabled
        property_values['NmDataDisabled'] = self.__nmDataDisabled
        property_values['NmScheduleVariant'] = self.__nmScheduleVariant
        property_values['CoupledClusters'] = self.__coupledClusters
        return property_values

    def _update_path(self):
        """
        Updates the path of the FlexrayNmClusterCoupling and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

    def is_atp_splitable(self) -> bool:
        return True

    def _save_contents(self):
        """
        Saves the content of FlexrayNmClusterCoupling node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_NmClusterCoupling()
        if len(self.__coupledClusters) > 0:
            AutosarNode._remove_xml_node_if_exists(self._node, 'COUPLED-CLUSTER-REFS')
        if len(self.__coupledClusters) > 0:
            coupledClusters_values = AutosarNode._add_or_get_xml_node(self._node, 'COUPLED-CLUSTER-REFS', create_after_nodes = self._insert_after_tags + ['VARIATION-POINT', 'T', 'S'] + self._insert_after_tags)
            for value in self.__coupledClusters:
                coupledClusters_value = AutosarNode._add_or_get_xml_node(coupledClusters_values, 'COUPLED-CLUSTER-REF', dest = value, create_after_nodes = ['COUPLED-CLUSTER-REF'], forceCreate = True)
                coupledClusters_value.text = value.autosar_path
                coupledClusters_value.attrib['DEST'] = value.tag

        if XDT.is_attribute_dirty('nmControlBitVectorEnabled', self):
            if self.__nmControlBitVectorEnabled is None:
                AutosarNode._remove_xml_node_if_exists(self._node, 'NM-CONTROL-BIT-VECTOR-ENABLED')
