class UdpNmCluster(NmCluster):
    """
    Udp specific NmCluster attributes
    """
    def __init__(self):
        super().__init__()
        self.tag = 'UDP-NM-CLUSTER'
        self._node = etree.Element('UDP-NM-CLUSTER')
        self.__nmCbvPosition = None
        self.__nmChannelActive = None
        self.__nmImmediateNmCycleTime = None
        self.__nmImmediateNmTransmissions = None
        self.__nmMessageTimeoutTime = None
        self.__nmMsgCycleTime = None
