class UdpNmClusterCoupling(NmClusterCoupling):
    """
    Udp attributes that are valid for each of the referenced (coupled) UdpNm clusters.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'UDP-NM-CLUSTER-COUPLING'
        self._node = etree.Element('UDP-NM-CLUSTER-COUPLING')
        self.__nmBusLoadReductionEnabled = None
        self.__nmImmediateRestartEnabled = None
        self.__coupledClusters = {} # using dict to preserve the order of elements
        self.__coupledClusters_as_string = {} # using dict to preserve the order of elements

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
