class DltMessageCollectionSet(FibexElement):
    """
    Collection of DltMessages
    """
    def __init__(self):
        super().__init__()
        self.tag = 'DLT-MESSAGE-COLLECTION-SET'
        self._node = etree.Element('DLT-MESSAGE-COLLECTION-SET')
        self.__dltMessages = {} # using dict to preserve the order of elements

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        refCounter = 0
        dltMessages_nodes = self._node.findall('{*}DLT-MESSAGES/*')
        for dltMessages_node in dltMessages_nodes:
            builddltMessages_node = None
            if dltMessages_node.find('{*}SHORT-NAME') is None:
                builddltMessages_node = DltMessage()._build(self, dltMessages_node, file, '[dltMessages_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                builddltMessages_node = DltMessage()._build(self, dltMessages_node, file)
            self.__dltMessages[(builddltMessages_node)] = None

        return self

    def get_dltMessages(self) -> list[DltMessage]:
        return list(self.__dltMessages.keys())

    def add_dltMessage(self, value: DltMessage) -> None:
        """
        Adds a single value to the dltMessages
        """
        if value is not None:
            if isinstance(value, Referrable) and any(v.name == value.name for v in self.__dltMessages.keys()):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, DltMessage) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of DltMessage or its sub-classes'.format(value))
            self.__dltMessages[value] = None
            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            value._parent = self #set parent
            value.file = self.file
            if value.name is not None:
                value._update_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'DltMessage_@' + str(len(self.get_children()))) #updates the path
            XDT.mark_dirty(value, self, attributesToMakeDirty = ['uuid', 'category', 'shortName', 'timestamp', 'checksum'])

    def set_dltMessages(self, values: list[DltMessage]) -> None:
        """
        Adds a list of ref value to the dltMessages
        """
        for value in values:
            self.add_dltMessage(value)

    def remove_dltMessage(self, value: DltMessage) -> None:
        """
        Removes a single value from dltMessages
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__dltMessages.pop(value)
            value._parent = None #No parent
            value._update_path() #resets the path
            value._node.getparent().remove(value._node)

    def remove_dltMessages(self, values: list[DltMessage]) -> None:
        """
        Removes a list of value from dltMessages
        """
        for value in values:
            self.remove_dltMessage(value)

    def new_DltMessage(self, name: str=None) -> DltMessage:
        """
        Creates a new DltMessage under the DltMessageCollectionSet.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        DltMessage_obj = DltMessage()
        if isinstance(DltMessage_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        DltMessage_obj.name = name if isinstance(DltMessage_obj, Referrable) else None
        self.add_dltMessage(DltMessage_obj)
        if isinstance(DltMessage_obj, Referrable):
            DltMessage_obj.set_shortName(name)
        return DltMessage_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        children.extend(self.__dltMessages)
        return children

    def add_child(self, child: AutosarNode) -> None:
        if child is not None:
            super().add_child(child)
            if isinstance(child, DltMessage):
                self.__dltMessages[child] = None


