    def _save_contents(self):
        """
        Saves the content of GlobalTimeDomain node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_FibexElement()
        if len(self.__communicationClusters) > 0:
            AutosarNode._remove_xml_node_if_exists(self._node, 'COMMUNICATION-CLUSTER-REFS')
