class DoIpInterface(Identifiable):
    """
    A logical interface over which the DoIP Node is able to communicate via DoIP independently from other existing DoIpInterfaces.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'DO-IP-INTERFACE'
        self._node = etree.Element('DO-IP-INTERFACE')
        self.__aliveCheckResponseTimeout = None
        self.__generalInactivityTime = None
        self.__initialInactivityTime = None
        self.__initialVehicleAnnouncementTime = None
        self.__isActivationLineDependent = None
        self.__maxTesterConnections = None
        self.__useMacAddressForIdentification = None
        self.__useVehicleIdentificationSyncStatus = None
        self.__vehicleAnnouncementCount = None
        self.__vehicleAnnouncementInterval = None
        self.__doIpRoutingActivations = {} # using dict to preserve the order of elements
        self.__doipChannelCollection = None
        self.__doipChannelCollection_as_string = None
        self.__doipConnections = {} # using dict to preserve the order of elements
        self.__doipConnections_as_string = {} # using dict to preserve the order of elements
