class TpConnection(ARObject):
    """
    TpConnection Base Class.
    """
    def __init__(self):
        super().__init__()
        self.__ident = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        ident_node = self._node.find('{*}IDENT')
        if ident_node is not None:
            if ident_node.find('{*}SHORT-NAME') is None:
                self.__ident = TpConnectionIdent()._build(self, ident_node, file, '[ident_@]')
            else:
                self.__ident = TpConnectionIdent()._build(self, ident_node, file)

        return self

    def get_ident(self) -> TpConnectionIdent:
        return self.__ident

    def set_ident(self, value: TpConnectionIdent) -> None:
        """
        Adds a single value to the ident
        """
        if value is not None:
            if isinstance(value, TpConnectionIdent) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of TpConnectionIdent or its sub-classes'.format(value))
            #if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            self.__ident = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._build_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'TpConnectionIdent_@' + str(len(self.get_children()))) #updates the path
        elif self.__ident is not None:
            self.__ident = None
        XDT.mark_dirty(self.__ident, self)

    def new_Ident(self, name: str=None) -> TpConnectionIdent:
        """
        Creates a new TpConnectionIdent under the TpConnection.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        TpConnectionIdent_obj = TpConnectionIdent()
        if isinstance(TpConnectionIdent_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        TpConnectionIdent_obj.name = name if isinstance(TpConnectionIdent_obj, Referrable) else None
        self.set_ident(TpConnectionIdent_obj)
        if isinstance(TpConnectionIdent_obj, Referrable):
            TpConnectionIdent_obj.set_shortName(name)
        return TpConnectionIdent_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        if self.__ident is not None:
            children.append(self.__ident)
        return children



    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        return property_values

    def _update_path(self):
        """
        Updates the path of the TpConnection and its children.
        """
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()


    def _save_TpConnection(self):
        """
        Saves the content of TpConnection node
        """
        super()._save_ARObject()
        if self.__ident is not None:
            if XDT.is_dirty(self.__ident) and self.__ident.file == self.file:
                self.__ident._node.tag = 'IDENT'
                self.__ident._save_contents()
                if self._node.find('{*}IDENT') is None:
                    AutosarNode._insert_element_after_given_tags(self._node, self.__ident._node, create_after_nodes = self._insert_after_tags + ['T', 'S'])
        else:
            AutosarNode._remove_xml_node_if_exists(self._node, 'IDENT')


