class FlexrayArTpNode(Identifiable):
    """
    TP Node (Sender or Receiver) provides the TP Address and the connection to the Topology description.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'FLEXRAY-AR-TP-NODE'
        self._node = etree.Element('FLEXRAY-AR-TP-NODE')
