class FlexrayTpConnectionControl(Identifiable):
    """
    Configuration parameters to control a FlexRay TP connection.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'FLEXRAY-TP-CONNECTION-CONTROL'
        self._node = etree.Element('FLEXRAY-TP-CONNECTION-CONTROL')
        self.__ackType = None
        self.__maxAr = None
        self.__maxAs = None
        self.__maxBufferSize = None
        self.__maxFcWait = None
        self.__maxFrIf = None
        self.__maxNumberOfNpduPerCycle = None
        self.__maxRetries = None
        self.__separationCycleExponent = None
        self.__timeBr = None
        self.__timeBuffer = None
        self.__timeCs = None
        self.__timeFrIf = None
        self.__timeoutAr = None
        self.__timeoutAs = None
        self.__timeoutBr = None
        self.__timeoutBs = None
        self.__timeoutCr = None
        self.__timeoutCs = None
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        ackType_value = AutosarNode._get_node_text(node,'ACK-TYPE')
        if ackType_value is not None:
            self.__ackType = TpAckType.get(ackType_value)

        maxAr_value = AutosarNode._get_node_text(node,'MAX-AR')
        if maxAr_value is not None:
            self.__maxAr = datatype_utils.get_int_value(maxAr_value)

        maxAs_value = AutosarNode._get_node_text(node,'MAX-AS')
        if maxAs_value is not None:
            self.__maxAs = datatype_utils.get_int_value(maxAs_value)

        maxBufferSize_value = AutosarNode._get_node_text(node,'MAX-BUFFER-SIZE')
        if maxBufferSize_value is not None:
            self.__maxBufferSize = datatype_utils.get_int_value(maxBufferSize_value)

        maxFcWait_value = AutosarNode._get_node_text(node,'MAX-FC-WAIT')
