class J1939TpConnection(TpConnection):
    """
    A J1939TpConnection represents an internal path for the transmission or reception of a Pdu via J1939Tp and describes the sender and the receiver of this particular communication. The J1939Tp module routes a Pdu (J1939 PGN) through the connection.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'J-1939-TP-CONNECTION'
        self._node = etree.Element('J-1939-TP-CONNECTION')
        self.__broadcast = None
        self.__bufferRatio = None
        self.__cancellation = None
        self.__dynamicBs = None
        self.__maxBs = None
        self.__maxExpBs = None
        self.__retry = None
        self.__dataPdu = None
        self.__dataPdu_as_string = None
        self.__directPdu = None
        self.__directPdu_as_string = None
        self.__flowControlPdus = {} # using dict to preserve the order of elements
        self.__flowControlPdus_as_string = {} # using dict to preserve the order of elements
        self.__receivers = {} # using dict to preserve the order of elements
        self.__receivers_as_string = {} # using dict to preserve the order of elements
        self.__tpPgs = {} # using dict to preserve the order of elements
        self.__tpSdus = {} # using dict to preserve the order of elements
        self.__tpSdus_as_string = {} # using dict to preserve the order of elements
        self.__transmitter = None
        self.__transmitter_as_string = None
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        broadcast_value = AutosarNode._get_node_text(node,'BROADCAST')
        if broadcast_value is not None:
            self.__broadcast = datatype_utils.get_bool_value(broadcast_value)

        bufferRatio_value = AutosarNode._get_node_text(node,'BUFFER-RATIO')
        if bufferRatio_value is not None:
            self.__bufferRatio = datatype_utils.get_int_value(bufferRatio_value)

        cancellation_value = AutosarNode._get_node_text(node,'CANCELLATION')
        if cancellation_value is not None:
            self.__cancellation = datatype_utils.get_bool_value(cancellation_value)

        dynamicBs_value = AutosarNode._get_node_text(node,'DYNAMIC-BS')
        if dynamicBs_value is not None:
            self.__dynamicBs = datatype_utils.get_bool_value(dynamicBs_value)

        maxBs_value = AutosarNode._get_node_text(node,'MAX-BS')
        if maxBs_value is not None:
            self.__maxBs = datatype_utils.get_int_value(maxBs_value)

        maxExpBs_value = AutosarNode._get_node_text(node,'MAX-EXP-BS')
        if maxExpBs_value is not None:
            self.__maxExpBs = datatype_utils.get_int_value(maxExpBs_value)

        retry_value = AutosarNode._get_node_text(node,'RETRY')
        if retry_value is not None:
            self.__retry = datatype_utils.get_bool_value(retry_value)

        refCounter = 0
        tpPgs_nodes = self._node.findall('{*}TP-PGS/*')
        for tpPgs_node in tpPgs_nodes:
            buildtpPgs_node = None
            if tpPgs_node.find('{*}SHORT-NAME') is None:
                buildtpPgs_node = J1939TpPg()._build(self, tpPgs_node, file, '[tpPgs_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildtpPgs_node = J1939TpPg()._build(self, tpPgs_node, file)
            self.__tpPgs[(buildtpPgs_node)] = None

        variationPoint_node = self._node.find('{*}VARIATION-POINT')
        if variationPoint_node is not None:
            if variationPoint_node.find('{*}SHORT-NAME') is None:
                self.__variationPoint = VariationPoint()._build(self, variationPoint_node, file, '[variationPoint_@]')
            else:
                self.__variationPoint = VariationPoint()._build(self, variationPoint_node, file)

        return self

    def _resolve_references(self):
        super()._resolve_references()
        dataPdu_node = self._node.find('{*}DATA-PDU-REF')
        if dataPdu_node is not None and dataPdu_node.text is not None:
            refText = ''
            refBase = dataPdu_node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + dataPdu_node.text
            self.__dataPdu_as_string = refText
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__dataPdu = ref_value

        directPdu_node = self._node.find('{*}DIRECT-PDU-REF')
        if directPdu_node is not None and directPdu_node.text is not None:
            refText = ''
            refBase = directPdu_node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + directPdu_node.text
            self.__directPdu_as_string = refText
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__directPdu = ref_value

        flowControlPdus_nodes = self._node.findall('{*}FLOW-CONTROL-PDU-REFS/*')
        for node in flowControlPdus_nodes:
            if node.text is None:
                continue
            refText = ''
            refBase = node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + node.text
            self.__flowControlPdus_as_string[refText] = None
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__flowControlPdus[ref_value] = None

        receivers_nodes = self._node.findall('{*}RECEIVER-REFS/*')
        for node in receivers_nodes:
            if node.text is None:
                continue
            refText = ''
            refBase = node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + node.text
            self.__receivers_as_string[refText] = None
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__receivers[ref_value] = None

        tpSdus_nodes = self._node.findall('{*}TP-SDU-REFS/*')
        for node in tpSdus_nodes:
            if node.text is None:
                continue
            refText = ''
            refBase = node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + node.text
            self.__tpSdus_as_string[refText] = None
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__tpSdus[ref_value] = None

        transmitter_node = self._node.find('{*}TRANSMITTER-REF')
        if transmitter_node is not None and transmitter_node.text is not None:
            refText = ''
            refBase = transmitter_node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + transmitter_node.text
            self.__transmitter_as_string = refText
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__transmitter = ref_value


