class J1939TpNode(Identifiable):
    """
    TP Node (Sender or Receiver) provides the TP Address and the connection to the Topology description.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'J-1939-TP-NODE'
        self._node = etree.Element('J-1939-TP-NODE')
        self.__connector = None
        self.__connector_as_string = None
        self.__tpAddress = None
        self.__tpAddress_as_string = None
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        variationPoint_node = self._node.find('{*}VARIATION-POINT')
        if variationPoint_node is not None:
            if variationPoint_node.find('{*}SHORT-NAME') is None:
                self.__variationPoint = VariationPoint()._build(self, variationPoint_node, file, '[variationPoint_@]')
            else:
                self.__variationPoint = VariationPoint()._build(self, variationPoint_node, file)

        return self

    def _resolve_references(self):
        super()._resolve_references()
        connector_node = self._node.find('{*}CONNECTOR-REF')
        if connector_node is not None and connector_node.text is not None:
            refText = ''
            refBase = connector_node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + connector_node.text
            self.__connector_as_string = refText
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__connector = ref_value

        tpAddress_node = self._node.find('{*}TP-ADDRESS-REF')
        if tpAddress_node is not None and tpAddress_node.text is not None:
            refText = ''
            refBase = tpAddress_node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + tpAddress_node.text
            self.__tpAddress_as_string = refText
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__tpAddress = ref_value


    def get_connector(self) -> CommunicationConnector:
        return self.__connector

    def get_connector_as_string(self) -> str:
        return self.__connector_as_string

    def set_connector(self, value: CommunicationConnector) -> None:
        """
        Adds a single value to the connector
        """
        if value is not None:
            if isinstance(value, CommunicationConnector) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of CommunicationConnector or its sub-classes'.format(value))
            if self.__connector is not None:
                self.__connector.referenced_by.remove(self)
            self.__connector = value
            value.referenced_by.add(self)
        elif self.__connector is not None:
            self.__connector.referenced_by.remove(self)
            self.__connector = None
        XDT.mark_dirty(self.__connector, self)

    def get_tpAddress(self) -> TpAddress:
        return self.__tpAddress

    def get_tpAddress_as_string(self) -> str:
        return self.__tpAddress_as_string

    def set_tpAddress(self, value: TpAddress) -> None:
        """
        Adds a single value to the tpAddress
        """
        if value is not None:
            if isinstance(value, TpAddress) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of TpAddress or its sub-classes'.format(value))
            if self.__tpAddress is not None:
                self.__tpAddress.referenced_by.remove(self)
            self.__tpAddress = value
            value.referenced_by.add(self)
        elif self.__tpAddress is not None:
            self.__tpAddress.referenced_by.remove(self)
            self.__tpAddress = None
        XDT.mark_dirty(self.__tpAddress, self)

    def get_variationPoint(self) -> VariationPoint:
        return self.__variationPoint

    def set_variationPoint(self, value: VariationPoint) -> None:
        """
        Adds a single value to the variationPoint
        """
        if value is not None:
            if isinstance(value, VariationPoint) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of VariationPoint or its sub-classes'.format(value))
            #if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            self.__variationPoint = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._build_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'VariationPoint_@' + str(len(self.get_children()))) #updates the path
        elif self.__variationPoint is not None:
            self.__variationPoint = None
        XDT.mark_dirty(self.__variationPoint, self)

    def new_VariationPoint(self, name: str=None) -> VariationPoint:
        """
        Creates a new VariationPoint under the J1939TpNode.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        VariationPoint_obj = VariationPoint()
        if isinstance(VariationPoint_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        VariationPoint_obj.name = name if isinstance(VariationPoint_obj, Referrable) else None
        self.set_variationPoint(VariationPoint_obj)
        if isinstance(VariationPoint_obj, Referrable):
            VariationPoint_obj.set_shortName(name)
        return VariationPoint_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        if self.__variationPoint is not None:
            children.append(self.__variationPoint)
        return children



    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['Connector'] = self.__connector
        property_values['TpAddress'] = self.__tpAddress
        return property_values

    def _update_path(self):
        """
        Updates the path of the J1939TpNode and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()


    def _save_contents(self):
        """
        Saves the content of J1939TpNode node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_Identifiable()
        if self.__connector is None:
            AutosarNode._remove_xml_node_if_exists(self._node, 'CONNECTOR-REF')
        elif XDT.is_dirty(self.__connector):
            connector_value = AutosarNode._add_or_get_xml_node(self._node, 'CONNECTOR-REF', dest = self.__connector, create_after_nodes = self._insert_after_tags + ['UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'] + self._insert_after_tags)
            connector_value.text = self.__connector.autosar_path
            connector_value.attrib['DEST'] = self.__connector.tag

        if self.__tpAddress is None:
            AutosarNode._remove_xml_node_if_exists(self._node, 'TP-ADDRESS-REF')
        elif XDT.is_dirty(self.__tpAddress):
            tpAddress_value = AutosarNode._add_or_get_xml_node(self._node, 'TP-ADDRESS-REF', dest = self.__tpAddress, create_after_nodes = self._insert_after_tags + ['CONNECTOR-REF', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'] + self._insert_after_tags)
            tpAddress_value.text = self.__tpAddress.autosar_path
            tpAddress_value.attrib['DEST'] = self.__tpAddress.tag

        if self.__variationPoint is not None:
            if XDT.is_dirty(self.__variationPoint) and self.__variationPoint.file == self.file:
                self.__variationPoint._node.tag = 'VARIATION-POINT'
                self.__variationPoint._save_contents()
                if self._node.find('{*}VARIATION-POINT') is None:
                    AutosarNode._insert_element_after_given_tags(self._node, self.__variationPoint._node, create_after_nodes = self._insert_after_tags + ['TP-ADDRESS-REF', 'CONNECTOR-REF', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])
        else:
            AutosarNode._remove_xml_node_if_exists(self._node, 'VARIATION-POINT')


class J1939TpPg(ARObject):
    """
    A J1939TpPg represents one J1939 message (parameter group, PG) identified by the PGN (parameter group number) that can be received or transmitted via J1939Tp.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'J-1939-TP-PG'
        self._node = etree.Element('J-1939-TP-PG')
        self.__pgn = None
        self.__requestable = None
        self.__directPdu = None
        self.__directPdu_as_string = None
        self.__sdus = {} # using dict to preserve the order of elements
        self.__sdus_as_string = {} # using dict to preserve the order of elements
        self.__tpSdu = None
        self.__tpSdu_as_string = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        pgn_value = AutosarNode._get_node_text(node,'PGN')
        if pgn_value is not None:
            self.__pgn = datatype_utils.get_int_value(pgn_value)

        requestable_value = AutosarNode._get_node_text(node,'REQUESTABLE')
        if requestable_value is not None:
            self.__requestable = datatype_utils.get_bool_value(requestable_value)

        return self

    def _resolve_references(self):
        super()._resolve_references()
        directPdu_node = self._node.find('{*}DIRECT-PDU-REF')
        if directPdu_node is not None and directPdu_node.text is not None:
            refText = ''
            refBase = directPdu_node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + directPdu_node.text
            self.__directPdu_as_string = refText
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__directPdu = ref_value

        sdus_nodes = self._node.findall('{*}SDU-REFS/*')
        for node in sdus_nodes:
            if node.text is None:
                continue
            refText = ''
            refBase = node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + node.text
            self.__sdus_as_string[refText] = None
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__sdus[ref_value] = None

        tpSdu_node = self._node.find('{*}TP-SDU-REF')
        if tpSdu_node is not None and tpSdu_node.text is not None:
            refText = ''
            refBase = tpSdu_node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + tpSdu_node.text
            self.__tpSdu_as_string = refText
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__tpSdu = ref_value


    def get_pgn(self) -> int:
        return self.__pgn

    def set_pgn(self, value: int) -> None:
        self.__pgn = value
        XDT.mark_attribute_dirty('pgn', self)

    def get_requestable(self) -> bool:
        return self.__requestable

    def set_requestable(self, value: bool) -> None:
        self.__requestable = value
        XDT.mark_attribute_dirty('requestable', self)

    def get_directPdu(self) -> NPdu:
        return self.__directPdu

    def get_directPdu_as_string(self) -> str:
        return self.__directPdu_as_string

    def set_directPdu(self, value: NPdu) -> None:
        """
        Adds a single value to the directPdu
        """
        if value is not None:
            if isinstance(value, NPdu) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of NPdu or its sub-classes'.format(value))
            if self.__directPdu is not None:
                self.__directPdu.referenced_by.remove(self)
            self.__directPdu = value
            value.referenced_by.add(self)
        elif self.__directPdu is not None:
            self.__directPdu.referenced_by.remove(self)
            self.__directPdu = None
        XDT.mark_dirty(self.__directPdu, self)

    def get_sdus(self) -> list[IPdu]:
        return list(self.__sdus.keys())

    def get_sdus_as_string(self) -> str:
        return list(self.__sdus_as_string.keys())

    def add_sdu(self, value: IPdu) -> None:
        """
        Adds a single value to the sdus
        """
        if value is not None:
            if isinstance(value, Referrable) and any(v.name == value.name for v in self.__sdus.keys()):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, IPdu) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of IPdu or its sub-classes'.format(value))
            self.__sdus[value] = None
            value.referenced_by.add(self)
            XDT.mark_dirty(value, self)

    def set_sdus(self, values: list[IPdu]) -> None:
        """
        Adds a list of ref value to the sdus
        """
        for value in values:
            self.add_sdu(value)

    def remove_sdu(self, value: IPdu) -> None:
        """
        Removes a single value from sdus
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__sdus.pop(value)
            value.referenced_by.remove(self)

    def remove_sdus(self, values: list[IPdu]) -> None:
        """
        Removes a list of value from sdus
        """
        for value in values:
            self.remove_sdu(value)

