class TlvDataIdDefinitionSet(ARElement):
    """
    This meta-class acts as a container of TlvDataIdDefinitions to be used in a given context
    """
    def __init__(self):
        super().__init__()
        self.tag = 'TLV-DATA-ID-DEFINITION-SET'
        self._node = etree.Element('TLV-DATA-ID-DEFINITION-SET')
        self.__tlvDataIdDefinitions = {} # using dict to preserve the order of elements

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        refCounter = 0
        tlvDataIdDefinitions_nodes = self._node.findall('{*}TLV-DATA-ID-DEFINITIONS/*')
        for tlvDataIdDefinitions_node in tlvDataIdDefinitions_nodes:
            buildtlvDataIdDefinitions_node = None
            if tlvDataIdDefinitions_node.find('{*}SHORT-NAME') is None:
                buildtlvDataIdDefinitions_node = TlvDataIdDefinition()._build(self, tlvDataIdDefinitions_node, file, '[tlvDataIdDefinitions_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildtlvDataIdDefinitions_node = TlvDataIdDefinition()._build(self, tlvDataIdDefinitions_node, file)
            self.__tlvDataIdDefinitions[(buildtlvDataIdDefinitions_node)] = None

        return self

    def get_tlvDataIdDefinitions(self) -> list[TlvDataIdDefinition]:
        return list(self.__tlvDataIdDefinitions.keys())

    def add_tlvDataIdDefinition(self, value: TlvDataIdDefinition) -> None:
        """
        Adds a single value to the tlvDataIdDefinitions
        """
        if value is not None:
            if isinstance(value, Referrable) and any(v.name == value.name for v in self.__tlvDataIdDefinitions.keys()):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, TlvDataIdDefinition) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of TlvDataIdDefinition or its sub-classes'.format(value))
            self.__tlvDataIdDefinitions[value] = None
            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            value._parent = self #set parent
