class DiagnosticTroubleCodeGroup(DiagnosticCommonElement):
    """
    The diagnostic trouble code group defines the DTCs belonging together and thereby forming a group.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'DIAGNOSTIC-TROUBLE-CODE-GROUP'
        self._node = etree.Element('DIAGNOSTIC-TROUBLE-CODE-GROUP')
