class PersistencyFileStorage(PersistencyDeployment):
    """
    This meta-class comes with the ability to define a collection of single files (directory) that creates the deployment-side counterpart to a PortPrototype typed by a PersistencyFileStorageInterface.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'PERSISTENCY-FILE-STORAGE'
        self._node = etree.Element('PERSISTENCY-FILE-STORAGE')
        self.__uri = None
        self.__files = {} # using dict to preserve the order of elements

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        uri_value = AutosarNode._get_node_text(node,'URI')
        if uri_value is not None:
            self.__uri = datatype_utils.get_string_value(uri_value)

        refCounter = 0
        files_nodes = self._node.findall('{*}FILES/*')
        for files_node in files_nodes:
            buildfiles_node = None
            if files_node.find('{*}SHORT-NAME') is None:
                buildfiles_node = PersistencyFile()._build(self, files_node, file, '[files_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildfiles_node = PersistencyFile()._build(self, files_node, file)
            self.__files[(buildfiles_node)] = None

        return self

    def get_uri(self) -> str:
        return self.__uri

    def set_uri(self, value: str) -> None:
        self.__uri = value
        XDT.mark_attribute_dirty('uri', self)

    def get_files(self) -> list[PersistencyFile]:
        return list(self.__files.keys())

    def add_file(self, value: PersistencyFile) -> None:
        """
        Adds a single value to the files
        """
        if value is not None:
            if isinstance(value, Referrable) and any(v.name == value.name for v in self.__files.keys()):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, PersistencyFile) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of PersistencyFile or its sub-classes'.format(value))
            self.__files[value] = None
            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            value._parent = self #set parent
            value.file = self.file
            if value.name is not None:
                value._update_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'PersistencyFile_@' + str(len(self.get_children()))) #updates the path
            XDT.mark_dirty(value, self, attributesToMakeDirty = ['updateStrategy', 'uuid', 'category', 'shortName', 'timestamp', 'checksum'])

    def set_files(self, values: list[PersistencyFile]) -> None:
        """
        Adds a list of ref value to the files
        """
        for value in values:
            self.add_file(value)

    def remove_file(self, value: PersistencyFile) -> None:
        """
        Removes a single value from files
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__files.pop(value)
            value._parent = None #No parent
            value._update_path() #resets the path
            value._node.getparent().remove(value._node)

    def remove_files(self, values: list[PersistencyFile]) -> None:
        """
        Removes a list of value from files
        """
        for value in values:
            self.remove_file(value)

    def new_File(self, name: str=None) -> PersistencyFile:
        """
        Creates a new PersistencyFile under the PersistencyFileStorage.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        PersistencyFile_obj = PersistencyFile()
        if isinstance(PersistencyFile_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        PersistencyFile_obj.name = name if isinstance(PersistencyFile_obj, Referrable) else None
        self.add_file(PersistencyFile_obj)
        if isinstance(PersistencyFile_obj, Referrable):
            PersistencyFile_obj.set_shortName(name)
        return PersistencyFile_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        children.extend(self.__files)
        return children

    def add_child(self, child: AutosarNode) -> None:
        if child is not None:
            super().add_child(child)
            if isinstance(child, PersistencyFile):
                self.__files[child] = None


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['Uri'] = self.__uri
        return property_values

    def _update_path(self):
        """
        Updates the path of the PersistencyFileStorage and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

    def is_atp_splitable(self) -> bool:
        return True

    def _save_contents(self):
        """
        Saves the content of PersistencyFileStorage node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_PersistencyDeployment()
        if len(self.__files) > 0:
            files_values = AutosarNode._add_or_get_xml_node(self._node, 'FILES', create_after_nodes = self._insert_after_tags + ['UPDATE-STRATEGY', 'REDUNDANCY-HANDLINGS', 'MINIMUM-SUSTAINED-SIZE', 'MAXIMUM-ALLOWED-SIZE', 'VARIATION-POINT', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'] + self._insert_after_tags)
            for value in self.__files:
                if XDT.is_dirty(value) and value.file == self.file:
                    value._save_contents()
                    if value._node.getparent() is None or value._node.getparent() != files_values:
                        files_values.append(value._node)

        if XDT.is_attribute_dirty('uri', self):
            if self.__uri is None:
                AutosarNode._remove_xml_node_if_exists(self._node, 'URI')
            else:
                uri_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'URI', create_after_nodes = ['FILES', 'UPDATE-STRATEGY', 'REDUNDANCY-HANDLINGS', 'MINIMUM-SUSTAINED-SIZE', 'MAXIMUM-ALLOWED-SIZE', 'VARIATION-POINT', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'] + self._insert_after_tags)
                uri_xml_node.text = str(self.__uri)


class PersistencyKeyValuePair(PersistencyDeploymentElement):
    """
    This meta-class represents the ability to formally model a key-value pair in the context of the deployment of persistency.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'PERSISTENCY-KEY-VALUE-PAIR'
        self._node = etree.Element('PERSISTENCY-KEY-VALUE-PAIR')
        self.__initValue = None
        self.__valueDataType = None
        self.__valueDataType_as_string = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        initValue_obj_dict = {}
        initValue_obj_dict['APPLICATION-RULE-BASED-VALUE-SPECIFICATION'] = 'ApplicationRuleBasedValueSpecification'
        initValue_obj_dict['COMPOSITE-RULE-BASED-VALUE-SPECIFICATION'] = 'CompositeRuleBasedValueSpecification'
        initValue_obj_dict['NUMERICAL-RULE-BASED-VALUE-SPECIFICATION'] = 'NumericalRuleBasedValueSpecification'
        initValue_obj_dict['TEXT-VALUE-SPECIFICATION'] = 'TextValueSpecification'
        initValue_obj_dict['ARRAY-VALUE-SPECIFICATION'] = 'ArrayValueSpecification'
        initValue_obj_dict['RECORD-VALUE-SPECIFICATION'] = 'RecordValueSpecification'
        initValue_obj_dict['APPLICATION-ASSOC-MAP-VALUE-SPECIFICATION'] = 'ApplicationAssocMapValueSpecification'
        initValue_obj_dict['APPLICATION-VALUE-SPECIFICATION'] = 'ApplicationValueSpecification'
        initValue_obj_dict['CONSTANT-REFERENCE'] = 'ConstantReference'
        initValue_obj_dict['NOT-AVAILABLE-VALUE-SPECIFICATION'] = 'NotAvailableValueSpecification'
        initValue_obj_dict['NUMERICAL-VALUE-SPECIFICATION'] = 'NumericalValueSpecification'
        initValue_obj_dict['REFERENCE-VALUE-SPECIFICATION'] = 'ReferenceValueSpecification'
        initValue_node = self._node.find('{*}INIT-VALUE/*')
        if initValue_node is not None:
            if initValue_node.find('{*}SHORT-NAME') is None:
                self.__initValue = __str_to_class__(initValue_obj_dict[etree.QName(initValue_node).localname])()._build(self, initValue_node, file, '[initValue_@]')
            else:
                self.__initValue = __str_to_class__(initValue_obj_dict[etree.QName(initValue_node).localname])()._build(self, initValue_node, file)

        return self

    def _resolve_references(self):
        super()._resolve_references()
        valueDataType_node = self._node.find('{*}VALUE-DATA-TYPE-REF')
        if valueDataType_node is not None and valueDataType_node.text is not None:
            refText = ''
            refBase = valueDataType_node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + valueDataType_node.text
            self.__valueDataType_as_string = refText
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__valueDataType = ref_value


    def get_initValue(self) -> ValueSpecification:
        return self.__initValue

    def set_initValue(self, value: ValueSpecification) -> None:
        """
        Adds a single value to the initValue
        """
        if value is not None:
            if isinstance(value, ValueSpecification) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of ValueSpecification or its sub-classes'.format(value))
            #if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            self.__initValue = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._build_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'ValueSpecification_@' + str(len(self.get_children()))) #updates the path
        elif self.__initValue is not None:
            self.__initValue = None
        XDT.mark_dirty(self.__initValue, self)

    def get_valueDataType(self) -> AbstractImplementationDataType:
        return self.__valueDataType

    def get_valueDataType_as_string(self) -> str:
        return self.__valueDataType_as_string

    def set_valueDataType(self, value: AbstractImplementationDataType) -> None:
        """
        Adds a single value to the valueDataType
        """
        if value is not None:
            if isinstance(value, AbstractImplementationDataType) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of AbstractImplementationDataType or its sub-classes'.format(value))
            if self.__valueDataType is not None:
                self.__valueDataType.referenced_by.remove(self)
            self.__valueDataType = value
            value.referenced_by.add(self)
        elif self.__valueDataType is not None:
            self.__valueDataType.referenced_by.remove(self)
            self.__valueDataType = None
        XDT.mark_dirty(self.__valueDataType, self)

