class ServiceMethodDeployment(Identifiable):
    """
    This abstract meta-class represents the ability to specify a deployment of a Method to a middleware transport layer.
    """
    def __init__(self):
        super().__init__()
        self.__method = None
        self.__method_as_string = None


    def _resolve_references(self):
        super()._resolve_references()
        method_node = self._node.find('{*}METHOD-REF')
        if method_node is not None and method_node.text is not None:
            refText = ''
            refBase = method_node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + method_node.text
            self.__method_as_string = refText
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__method = ref_value


    def get_method(self) -> ClientServerOperation:
        return self.__method

    def get_method_as_string(self) -> str:
        return self.__method_as_string

    def set_method(self, value: ClientServerOperation) -> None:
        """
        Adds a single value to the method
        """
        if value is not None:
            if isinstance(value, ClientServerOperation) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of ClientServerOperation or its sub-classes'.format(value))
            if self.__method is not None:
                self.__method.referenced_by.remove(self)
            self.__method = value
            value.referenced_by.add(self)
        elif self.__method is not None:
            self.__method.referenced_by.remove(self)
            self.__method = None
        XDT.mark_dirty(self.__method, self)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['Method'] = self.__method
        return property_values

    def _update_path(self):
        """
        Updates the path of the ServiceMethodDeployment and its children.
        """
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()


    def _save_ServiceMethodDeployment(self):
        """
        Saves the content of ServiceMethodDeployment node
        """
        super()._save_Identifiable()
        if self.__method is None:
            AutosarNode._remove_xml_node_if_exists(self._node, 'METHOD-REF')
        elif XDT.is_dirty(self.__method):
            method_value = AutosarNode._add_or_get_xml_node(self._node, 'METHOD-REF', dest = self.__method, create_after_nodes = self._insert_after_tags + ['UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'] + self._insert_after_tags)
            method_value.text = self.__method.autosar_path
            method_value.attrib['DEST'] = self.__method.tag


