class VehicleRolloutStep(Identifiable):
    """
    This meta-class represents the ability to define a rollout-condition for a vehicle update campaign.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'VEHICLE-ROLLOUT-STEP'
        self._node = etree.Element('VEHICLE-ROLLOUT-STEP')
        self.__safetyPolicy = None
        self.__ucmProcessings = {} # using dict to preserve the order of elements

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        safetyPolicy_value = AutosarNode._get_node_text(node,'SAFETY-POLICY')
        if safetyPolicy_value is not None:
            self.__safetyPolicy = datatype_utils.get_string_value(safetyPolicy_value)

        refCounter = 0
        ucmProcessings_nodes = self._node.findall('{*}UCM-PROCESSINGS/*')
        for ucmProcessings_node in ucmProcessings_nodes:
            builducmProcessings_node = None
            if ucmProcessings_node.find('{*}SHORT-NAME') is None:
                builducmProcessings_node = UcmStep()._build(self, ucmProcessings_node, file, '[ucmProcessings_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                builducmProcessings_node = UcmStep()._build(self, ucmProcessings_node, file)
            self.__ucmProcessings[(builducmProcessings_node)] = None

        return self

    def get_safetyPolicy(self) -> str:
        return self.__safetyPolicy

    def set_safetyPolicy(self, value: str) -> None:
        self.__safetyPolicy = value
        XDT.mark_attribute_dirty('safetyPolicy', self)

    def get_ucmProcessings(self) -> list[UcmStep]:
        return list(self.__ucmProcessings.keys())

    def add_ucmProcessing(self, value: UcmStep) -> None:
        """
        Adds a single value to the ucmProcessings
        """
        if value is not None:
            if isinstance(value, Referrable) and any(v.name == value.name for v in self.__ucmProcessings.keys()):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, UcmStep) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of UcmStep or its sub-classes'.format(value))
            self.__ucmProcessings[value] = None
            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            value._parent = self #set parent
            value.file = self.file
            if value.name is not None:
                value._update_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'UcmStep_@' + str(len(self.get_children()))) #updates the path
            XDT.mark_dirty(value, self, attributesToMakeDirty = ['uuid', 'category', 'shortName', 'timestamp', 'checksum'])

    def set_ucmProcessings(self, values: list[UcmStep]) -> None:
        """
        Adds a list of ref value to the ucmProcessings
        """
        for value in values:
            self.add_ucmProcessing(value)

    def remove_ucmProcessing(self, value: UcmStep) -> None:
        """
        Removes a single value from ucmProcessings
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__ucmProcessings.pop(value)
            value._parent = None #No parent
            value._update_path() #resets the path
            value._node.getparent().remove(value._node)

    def remove_ucmProcessings(self, values: list[UcmStep]) -> None:
        """
        Removes a list of value from ucmProcessings
        """
        for value in values:
            self.remove_ucmProcessing(value)

    def new_UcmProcessing(self, name: str=None) -> UcmStep:
        """
        Creates a new UcmStep under the VehicleRolloutStep.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        UcmStep_obj = UcmStep()
        if isinstance(UcmStep_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        UcmStep_obj.name = name if isinstance(UcmStep_obj, Referrable) else None
        self.add_ucmProcessing(UcmStep_obj)
        if isinstance(UcmStep_obj, Referrable):
            UcmStep_obj.set_shortName(name)
        return UcmStep_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        children.extend(self.__ucmProcessings)
        return children



    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['SafetyPolicy'] = self.__safetyPolicy
        return property_values

    def _update_path(self):
        """
        Updates the path of the VehicleRolloutStep and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()


    def _save_contents(self):
        """
        Saves the content of VehicleRolloutStep node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_Identifiable()
        if XDT.is_attribute_dirty('safetyPolicy', self):
            if self.__safetyPolicy is None:
                AutosarNode._remove_xml_node_if_exists(self._node, 'SAFETY-POLICY')
            else:
                safetyPolicy_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'SAFETY-POLICY', create_after_nodes = ['UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'] + self._insert_after_tags)
                safetyPolicy_xml_node.text = str(self.__safetyPolicy)

        if len(self.__ucmProcessings) > 0:
            ucmProcessings_values = AutosarNode._add_or_get_xml_node(self._node, 'UCM-PROCESSINGS', create_after_nodes = self._insert_after_tags + ['SAFETY-POLICY', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'] + self._insert_after_tags)
            for value in self.__ucmProcessings:
                if XDT.is_dirty(value) and value.file == self.file:
                    value._save_contents()
                    if value._node.getparent() is None or value._node.getparent() != ucmProcessings_values:
                        ucmProcessings_values.append(value._node)


