class PersistencyInterface(PortInterface):
    """
    This meta-class provides the abstract ability to define a PortInterface for the support of persistency use cases.
    """
    def __init__(self):
        super().__init__()
        self.__minimumSustainedSize = None
        self.__redundancy = None
        self.__updateStrategy = None
        self.__redundancyHandlings = {} # using dict to preserve the order of elements

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        minimumSustainedSize_value = AutosarNode._get_node_text(node,'MINIMUM-SUSTAINED-SIZE')
        if minimumSustainedSize_value is not None:
            self.__minimumSustainedSize = datatype_utils.get_int_value(minimumSustainedSize_value)

        redundancy_value = AutosarNode._get_node_text(node,'REDUNDANCY')
        if redundancy_value is not None:
            self.__redundancy = PersistencyRedundancyEnum.get(redundancy_value)

        updateStrategy_value = AutosarNode._get_node_text(node,'UPDATE-STRATEGY')
        if updateStrategy_value is not None:
            self.__updateStrategy = PersistencyCollectionLevelUpdateStrategyEnum.get(updateStrategy_value)

        refCounter = 0
        redundancyHandlings_obj_dict = {}
        redundancyHandlings_obj_dict['PERSISTENCY-REDUNDANCY-CRC'] = 'PersistencyRedundancyCrc'
        redundancyHandlings_obj_dict['PERSISTENCY-REDUNDANCY-HASH'] = 'PersistencyRedundancyHash'
        redundancyHandlings_obj_dict['PERSISTENCY-REDUNDANCY-M-OUT-OF-N'] = 'PersistencyRedundancyMOutOfN'
        redundancyHandlings_nodes = self._node.findall('{*}REDUNDANCY-HANDLINGS/*')
        for redundancyHandlings_node in redundancyHandlings_nodes:
            buildredundancyHandlings_node = None
            if redundancyHandlings_node.find('{*}SHORT-NAME') is None:
                buildredundancyHandlings_node = __str_to_class__(redundancyHandlings_obj_dict[etree.QName(redundancyHandlings_node).localname])()._build(self, redundancyHandlings_node, file, '[redundancyHandlings_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildredundancyHandlings_node = __str_to_class__(redundancyHandlings_obj_dict[etree.QName(redundancyHandlings_node).localname])()._build(self, redundancyHandlings_node, file)
            self.__redundancyHandlings[buildredundancyHandlings_node] = None

        return self

    def get_minimumSustainedSize(self) -> int:
        return self.__minimumSustainedSize

    def set_minimumSustainedSize(self, value: int) -> None:
        self.__minimumSustainedSize = value
        XDT.mark_attribute_dirty('minimumSustainedSize', self)

    def get_redundancy(self) -> PersistencyRedundancyEnum:
        return self.__redundancy

    def set_redundancy(self, value: PersistencyRedundancyEnum) -> None:
        self.__redundancy = value
        XDT.mark_attribute_dirty('redundancy', self)

    def get_updateStrategy(self) -> PersistencyCollectionLevelUpdateStrategyEnum:
        return self.__updateStrategy

    def set_updateStrategy(self, value: PersistencyCollectionLevelUpdateStrategyEnum) -> None:
        self.__updateStrategy = value
        XDT.mark_attribute_dirty('updateStrategy', self)

    def get_redundancyHandlings(self) -> list[PersistencyRedundancyHandling]:
        return list(self.__redundancyHandlings.keys())

    def add_redundancyHandling(self, value: PersistencyRedundancyHandling) -> None:
        """
        Adds a single value to the redundancyHandlings
        """
        if value is not None:
            if isinstance(value, Referrable) and any(v.name == value.name for v in self.__redundancyHandlings.keys()):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, PersistencyRedundancyHandling) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of PersistencyRedundancyHandling or its sub-classes'.format(value))
            self.__redundancyHandlings[value] = None
            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            value._parent = self #set parent
            value.file = self.file
            if value.name is not None:
                value._update_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'PersistencyRedundancyHandling_@' + str(len(self.get_children()))) #updates the path
            XDT.mark_dirty(value, self, attributesToMakeDirty = ['timestamp', 'checksum'])

    def set_redundancyHandlings(self, values: list[PersistencyRedundancyHandling]) -> None:
        """
        Adds a list of ref value to the redundancyHandlings
        """
        for value in values:
            self.add_redundancyHandling(value)

    def remove_redundancyHandling(self, value: PersistencyRedundancyHandling) -> None:
        """
        Removes a single value from redundancyHandlings
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__redundancyHandlings.pop(value)
            value._parent = None #No parent
            value._update_path() #resets the path
            value._node.getparent().remove(value._node)

    def remove_redundancyHandlings(self, values: list[PersistencyRedundancyHandling]) -> None:
        """
        Removes a list of value from redundancyHandlings
        """
        for value in values:
            self.remove_redundancyHandling(value)

