class ProcessDesign(ARElement):
    """
    This meta-class has the ability to stand in for a Process at the time when the Process does not yet exist. But its future existence already needs to be considered during design phase and for that a dedicated model element is required..
    """
    def __init__(self):
        super().__init__()
        self.tag = 'PROCESS-DESIGN'
        self._node = etree.Element('PROCESS-DESIGN')
        self.__deterministicClientResourceNeeds = {} # using dict to preserve the order of elements
        self.__executable = None
        self.__executable_as_string = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        refCounter = 0
        deterministicClientResourceNeeds_nodes = self._node.findall('{*}DETERMINISTIC-CLIENT-RESOURCE-NEEDSS/*')
        for deterministicClientResourceNeeds_node in deterministicClientResourceNeeds_nodes:
            builddeterministicClientResourceNeeds_node = None
            if deterministicClientResourceNeeds_node.find('{*}SHORT-NAME') is None:
                builddeterministicClientResourceNeeds_node = DeterministicClientResourceNeeds()._build(self, deterministicClientResourceNeeds_node, file, '[deterministicClientResourceNeeds_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                builddeterministicClientResourceNeeds_node = DeterministicClientResourceNeeds()._build(self, deterministicClientResourceNeeds_node, file)
            self.__deterministicClientResourceNeeds[(builddeterministicClientResourceNeeds_node)] = None

        return self

    def _resolve_references(self):
        super()._resolve_references()
        executable_node = self._node.find('{*}EXECUTABLE-REF')
        if executable_node is not None and executable_node.text is not None:
            refText = ''
            refBase = executable_node.attrib.get('BASE')
            if refBase is not None and refBase in __refBaseToArPackageDict__:
                refText = __refBaseToArPackageDict__[refBase].path + '/'
            refText = refText + executable_node.text
            self.__executable_as_string = refText
            if refText in __autosarPathsToNodeDict__:
                ref_value = __autosarPathsToNodeDict__[refText]
                ref_value.referenced_by.add(self)
                self.__executable = ref_value


