class ComFieldGrantDesign(ComGrantDesign):
    """
    This meta-class represents the ability to define a Grant for a ServiceInterface.field.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'COM-FIELD-GRANT-DESIGN'
        self._node = etree.Element('COM-FIELD-GRANT-DESIGN')
        self.__role = None
        self.__field = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        role_value = AutosarNode._get_node_text(node,'ROLE')
        if role_value is not None:
            self.__role = FieldAccessEnum.get(role_value)

        field_node = self._node.find('{*}FIELD-IREF')
        if field_node is not None:
            if field_node.find('{*}SHORT-NAME') is None:
                self.__field = FieldInExecutableInstanceRef()._build(self, field_node, file, '[field_@]')
            else:
                self.__field = FieldInExecutableInstanceRef()._build(self, field_node, file)

        return self

