        if XDT.is_attribute_dirty('role', self):
            if self.__role is None:
                AutosarNode._remove_xml_node_if_exists(self._node, 'ROLE')
            else:
                role_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'ROLE', create_after_nodes = ['FIELD-IREF', 'REMOTE-SUBJECT-REF', 'PROCESS-DESIGN-REF', 'VARIATION-POINT', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'] + self._insert_after_tags)
