class IdsDesign(ARElement):
    """
    This meta-class represents the root element of a SecurityExtract file for IDS development. It defines the scope of an IDS to be designed and implemented by referencing all SecurityExtract meta-classes that need to be included into the IDS development process.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'IDS-DESIGN'
        self._node = etree.Element('IDS-DESIGN')
        self.__elements = {} # using dict to preserve the order of elements

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        refCounter = 0
        elements_nodes = self._node.findall('{*}ELEMENTS/*')
        for elements_node in elements_nodes:
            buildelements_node = None
            if elements_node.find('{*}SHORT-NAME') is None:
                buildelements_node = IdsCommonElementRefConditional()._build(self, elements_node, file, '[elements_@' + str(refCounter) + ']')
                refCounter = refCounter + 1
            else:
                buildelements_node = IdsCommonElementRefConditional()._build(self, elements_node, file)
            self.__elements[(buildelements_node)] = None

        return self

    def get_elements(self) -> list[IdsCommonElementRefConditional]:
        return list(self.__elements.keys())

    def add_element(self, value: IdsCommonElementRefConditional) -> None:
        """
        Adds a single value to the elements
        """
        if value is not None:
            if isinstance(value, Referrable) and any(v.name == value.name for v in self.__elements.keys()):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, IdsCommonElementRefConditional) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of IdsCommonElementRefConditional or its sub-classes'.format(value))
            self.__elements[value] = None
            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None:
                value._parent.get_children().remove(value)

            value._parent = self #set parent
            value.file = self.file
            if value.name is not None:
                value._update_path() #updates the path
            else:
                value._build_path(elementNameIfShortNameMissing = 'IdsCommonElementRefConditional_@' + str(len(self.get_children()))) #updates the path
            XDT.mark_dirty(value, self, attributesToMakeDirty = ['timestamp', 'checksum'])

    def set_elements(self, values: list[IdsCommonElementRefConditional]) -> None:
        """
        Adds a list of ref value to the elements
        """
        for value in values:
            self.add_element(value)

    def remove_element(self, value: IdsCommonElementRefConditional) -> None:
        """
        Removes a single value from elements
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__elements.pop(value)
            value._parent = None #No parent
            value._update_path() #resets the path
            value._node.getparent().remove(value._node)

    def remove_elements(self, values: list[IdsCommonElementRefConditional]) -> None:
        """
        Removes a list of value from elements
        """
        for value in values:
            self.remove_element(value)

    def new_Element(self, name: str=None) -> IdsCommonElementRefConditional:
        """
        Creates a new IdsCommonElementRefConditional under the IdsDesign.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        IdsCommonElementRefConditional_obj = IdsCommonElementRefConditional()
        if isinstance(IdsCommonElementRefConditional_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        IdsCommonElementRefConditional_obj.name = name if isinstance(IdsCommonElementRefConditional_obj, Referrable) else None
        self.add_element(IdsCommonElementRefConditional_obj)
        if isinstance(IdsCommonElementRefConditional_obj, Referrable):
            IdsCommonElementRefConditional_obj.set_shortName(name)
        return IdsCommonElementRefConditional_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        children.extend(self.__elements)
        return children

    def add_child(self, child: AutosarNode) -> None:
        if child is not None:
            super().add_child(child)
            if isinstance(child, IdsCommonElementRefConditional):
                self.__elements[child] = None


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        return property_values

    def _update_path(self):
        """
        Updates the path of the IdsDesign and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

    def is_atp_splitable(self) -> bool:
        return True

    def _save_contents(self):
        """
        Saves the content of IdsDesign node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_ARElement()
        if len(self.__elements) > 0:
            elements_values = AutosarNode._add_or_get_xml_node(self._node, 'ELEMENTS', create_after_nodes = self._insert_after_tags + ['VARIATION-POINT', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'] + self._insert_after_tags)
            for value in self.__elements:
                if XDT.is_dirty(value) and value.file == self.file:
                    value._save_contents()
                    if value._node.getparent() is None or value._node.getparent() != elements_values:
                        elements_values.append(value._node)


